long modpow(long a, long n, long mod) {
    long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

// a^{-1} mod を計算する
long modinv(long a, long mod) {
    return modpow(a, mod - 2, mod);
}

long g(int r, int c, long mod, long *seki, long *shou){
    long g1;
    g1 = seki[r+c+2] * shou[r+1];
    g1 %= mod;
    g1 *= shou[c+1];
    g1 %= mod;
    g1 -= 1;
    if(g1 < 0)
        g1 += mod;
    return g1;
}

