struct ModCombination {
  vector<long long> fac, finv, inv;
  const int MAX, mod;

  ModCombination(int n, int mod) : MAX(n+1), mod(mod) {
    fac.resize(MAX);  fac[0] = fac[1] = 1;
    finv.resize(MAX); finv[0] = finv[1] = 1;
    inv.resize(MAX);  inv[1] = 1;
    for (int i=2; i<MAX; ++i) {
      fac[i] = fac[i-1] * i % MOD;
      inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
      finv[i] = finv[i-1] * inv[i] % MOD;
    }
  }

  long long value(int n, int r) {
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * (finv[r] * finv[n-r] % mod) % mod;
  }
};

void solve() {
  int r1, c1, r2, c2;
  cin >> r1 >> c1 >> r2 >> c2;
  ++r2, ++c2;

  ModCombination comb(r2+c2, MOD);
  ll ans = comb.value(r2+c2, r2) - comb.value(r2+c1, r2) - comb.value(r1+c2, r1) + comb.value(r1+c1, r1);
  while (ans < 0) ans += MOD;
  ans %= MOD;
  cout << ans << endl;
}


/* -------- <programs end> -------- */


signed main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(12);
  solve();
  return 0;
}

