    mint res = 0;
    for(int i=r1; i<=r2; ++i){
        for(int j=c1; j<=c2; ++j){
            mint tmp = bc.fact(i+j) *bc.finv(i) * bc.finv(j);
            res += tmp;
        }
    }

    cout << res << endl;

}

