modular<T> power (const modular<T>& a, U b) {
    assert(b >= 0);
    modular<T> x = a, ret = 1;
    for (; b > 0; b /= 2) {
        if (b % 2 == 1) ret *= x;
        x *= x;
    }
    return ret;
