    A = v[a];
    B = v[b];
    C = v[a-b];
    E(B, MOD, x, y);
    while(x < 0)
        x+=MOD;
    B = M (x);
    A = M (A * B);
    E(C, MOD, x, y);
    while(x < 0)
        x+=MOD;
    C = M(x);
    A = M(A * C);
    return A;
}

long long S (long long a, long long b){
    long long ans = 0;
    long long curr, curr1, x, y;
    for (int it = 1; it <= a; ++it){
        curr = M((b + 1) * v[b + it + 1]);
        curr1 = M(v[b + 1] * v[it + 1]);
        curr = (curr + MOD - curr1) % MOD;
        E(v[it + 1], MOD, x, y);
        while(x < 0)
            x += MOD;
        curr1 = x;
        E(v[b + 1], MOD, x, y);
        while(x < 0)
            x += MOD;
        curr1 = M(curr1 * x);
        curr = M(curr * curr1);
        ans = M (ans + curr);
    }
    return ans;
}

