{
    if (n < k)
        return 0;
    if (n < 0 || k < 0)
        return 0;
    return fac.at(n) * fac_inv.at(k) * fac_inv.at(n - k);
}

mint f(int r, int c)
{
    return comb(r + c, c);
}

mint g(int r, int c)
{
