/**
    find the number of ways to move from (0 , 0)
    to any of square (r , c ) -> r1 <= r <= r2 , c1 <= c <= c2
    Let's represent the number of ways again
    To move from (0 , 0 ) to any (r , c)
    RRRRR -> r chars and UUUUU -> c chars
    and the number of shuffle equal to (r + c)! / (r!) / (c!)
    or (r + c) choose r
    Then it's trivially ask you
    compute summation (r + c) choose (r) from r = r1 to r = r2 and c from c1 to c2
    This can be done easily in O(rc)
    Of course, we can do it better. ;)
    Let's iterate over r from r1 to r2
    summation (r + c) choose r from c1 to c2
    by Pascal's theorem
    (r , 0 ) + (r + 1 , 1 ) + (r + 2 , 2) ...
    (r + 1 , 0) + (r + 1, 1) ->
    (r + 2, 1) + (r + 2 ,  2) -> (r + 3, 2 ) + (r + 3, 3)
    .... (r + c + 1 , c)
*/
int main () {
    prefact () ;

    scanf("%d %d %d %d", &r1, &c1, &r2, &c2);
    auto sum = [&] (int r, int c) -> int{
            /// (r , 0) + (r + 1 , 1) , .... (r + c, c)
            return ncr(r + c + 1, c);
    };
    int ans = 0;
    for (int r = r1 ; r <= r2 ; ++ r) {
        plusle (ans, sub (sum(r , c2), sum (r, c1 - 1)));
    }
    printf("%d\n", ans);
}

