const ll dividend = 1000000007;

ll funcComb(int n, int k) 
{
	ll output = 1;
	int sum = n + k;
	vector<int> dividends;
	for (int i = 0; i < k; i++)
	{
		dividends.push_back(k - i);
	}
	for (int i = 0; i < k; i++)
	{
		output *= sum - i;
		for (auto it = dividends.begin(); it != dividends.end(); it++)
		{
			if (output % *it == 0)
			{
				output /= *it;
				*it = 2147483647;

			}
		}
	}

	return output % dividend;
}

