using namespace std;

int64_t M = 1e9+7;

vector<int64_t> inv_tbl(2000000);

int64_t modpow(int64_t n, int64_t m) {
    if (m == 0) return 1;
    else if (m % 2 == 0) { 
        int64_t r = modpow(n, m / 2);
        return (r * r) % M;
    } else {
        int64_t r = modpow(n, m / 2);
        return ((n * r) % M * r) % M;
    }
}

int64_t inv(int n) {
    return inv_tbl[n];
}

void compute_inv() {
    for (size_t i = 0; i < inv_tbl.size(); ++i) {
        inv_tbl[i] = modpow(i, M - 2);
    }
}

int64_t comb(int n, int k) {
    int64_t c = 1;
    for (int i = 1; i <= k; ++i) {
        c = (((n - i + 1) * inv(i)) % M * c) % M;
    }
    return c;
}

int64_t f(int r, int c) {
    int64_t x = comb(r+1+c+1, c+1);
    return x - 1;
}

