long long MOD = 1000000007;

vector<ll> factorial(int N){
    vector<ll> fact(N+1,1);
    for(int i=1; i<N; i++){
        fact[i+1]=(i+1)*fact[i]%MOD;
    }
    return fact;
}

map<long long, long long> inv_fact;
long long inv_factorial(long long x){
    if (inv_fact.find(x)!=inv_fact.end()){
        return inv_fact[x];
    }
    long long p=MOD-2;
    long long ret=1;
    long long tmp=x;
    while(p>0){
        if(p%2==1)ret=ret*tmp%MOD;
        tmp=tmp*tmp%MOD;
        p/=2;
    }
    inv_fact[x]=ret;
    return ret;
}

long long comb(int a, int b, vector<ll> &fact){
    if(b==0){
        return 1;
    }
    long long ret=fact[a]*inv_factorial(fact[a-b])%MOD;
    return ret*inv_factorial(fact[b])%MOD;
}

int main(){
    int r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;

    vector<ll> fact=factorial(2000001);

    ll ans=0;
    for(int r=0; r<=r2; r++){
        ans+=comb(r+1+c2, c2, fact)-comb(r+c1, c1-1, fact);
        ans%=MOD;
        if(r<=r1){
            ans+=comb(r+c1-1,r, fact)-comb(r+c2,c2,fact);
            ans%=MOD;
        }
    }
    ans=(ans+MOD)%MOD;
    cout << ans << endl;

}

