    ll ans2 = comb(r0 + c1 + 1, r0);
    ll ans3 = comb(r0 + c0, r0);
    ll ans = (ans0 - ans1 - ans2 + ans3 + MOD + MOD) % MOD;
    printf("%lld\n", ans);

    return;
}

