const int nmax=2000100;
const ll mod=1e9+7;
ll fac[nmax],finv[nmax],inv[nmax];

void COMinit(){
  fac[0]=fac[1]=1;
  finv[0]=finv[1]=1;
  inv[1]=1;
  for(int i=2;i<nmax;i++){
    fac[i]=fac[i-1]*i%mod;
    inv[i]=mod-inv[mod%i]*(mod/i)%mod;
    finv[i]=finv[i-1]*inv[i]%mod;
  }
}
ll com(int n,int k){
  if(n<k||n<0||k<0){
    return 0;
  }
  return fac[n]*(finv[k]*finv[n-k]%mod)%mod;
}
int main(){
    COMinit();
    int r1,c1,r,c;
    cin >> r1 >> c1 >> r >> c;
    vector<vector<ll>> sum(r+1,vector<ll>(c+1));
    for(int i=1;i<=r;i++){
        for(int j=1;j<=c;j++){
            sum[i][j]=com(i+j,i); 
        }
    }
    for(int i=0;i<=r;i++){
        for(int j=0;j<c;j++){
            sum[i][j+1]+=sum[i][j];
            sum[i][j+1]%=mod;
        }
    }
    for(int i=0;i<=c;i++){
        for(int j=0;j<r;j++){
            sum[j+1][i]+=sum[j][i];
            sum[j+1][i]%=mod;
        }
    }
    cout << (sum[r][c]-sum[r1-1][c]-sum[r][c1-1]+sum[r1-1][c1-1]+mod*2)%mod << endl;
}

