    Factorial f(r2 + c2 + 10);
    auto g = [&](int r, int c) {
        mint res = 0;
        REP(i, r + 1) {
            res += f.com(i + 1 + c, c);
        }
        return res;
    };
    dump(g(2, 2));
    mint ans = g(r2, c2) - g(r1 - 1, c2) - g(r2, c1 - 1) + g(r1 - 1, c1 - 1);
    cout << ans << endl;
}

