constexpr int MOD = 1000000007;

// O(log(p))
ll mpow(ll x, ll p) {
    if (p == 1) { return x % MOD; }
    if (p % 2) { return (x * mpow(x, p - 1)) % MOD; }
    ll sub = mpow(x, p / 2);
    return (sub * sub) % MOD;
}

// O(1)
ll f(const vll& fac, const vll& inv, int i, int j) {
    if (i == 0 || j == 0) { return 1; }
    if (i == 1 || j == 1) { return (i + j) % MOD; }
    return (((fac[i + j] * inv[i]) % MOD) * inv[j]) % MOD;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;

    int n = r2 + c2;
    vll fac(n + 2, 0), inv(n + 2, 0);

    // O(n)
    fac[0] = 1;
    rep(i, 1, n + 2) { fac[i] = (i * fac[i - 1]) % MOD; }

    // O(nlog(MOD))
    inv.back() = mpow(fac.back(), MOD - 2);
    rrep(i, 0, n + 1) { inv[i] = (inv[i + 1] * (i + 1)) % MOD; }

    // O(n)
    ll sum = 0;
    rep(i, r1, r2 + 1) {
        ll tmp = (f(fac, inv, i + 1, c2) - f(fac, inv, i + 1, c1 - 1)) % MOD;
        if (tmp < 0) { tmp += MOD; }
        sum = (sum + tmp) % MOD;
    }
