LL exgcd(LL a,LL b,LL &x,LL &y)
{
    if(b==0)
    {          
        x=1;
        y=0;
        return a;
    }
    LL r=exgcd(b, a%b, x, y);
    LL t=y;
    y=x-(a/b)*y;    
    x=t;
    return r;
}
LL ny(LL x) {
	if (x == (LL)(0)) {
		return 1;
	}
	LL xx, yy;
	exgcd(x, mod, xx, yy);
	return xx;
}

int getcc(int r, int c) {
	LL res = 1;
	for (int i = c + 1; i <= (r + c); ++i) {
		res *= (LL)(i);
		res %= (LL)(mod);
	}
	for (int i = 1; i <= r; ++i) {
		res *= ny((LL)(i));
		res %= (LL)(mod);
	}
	return (int)(res);
	// C(r + c, r)
}

int getrc(int r, int c) {
	if (r == 0) {
		return c + 1;
	}
	if (c == 0) {
		return r + 1;
	}

	return (getcc(r + 1, c + 1) - 1 + mod) % mod;
}
