	int **rc = new int*[r + 1];
	for (int i = 0; i <= r; ++i) {
		rc[i] = new int[c + 1];
	}
	rc[0][0] = 1;
	for (int i = 1; i <= r; ++i) {
		rc[i][0] = 1;
	}
	for (int i = 1; i <= c; ++i) {
		rc[0][i] = 1;
	}
	for (int i = 1; i <= r; ++i) {
		for (int j = 1; j <= c; ++j) {
			rc[i][j] = rc[i][j - 1] + rc[i - 1][j];
			rc[i][j] %= mod;
		}
	}
	int res = 0;
	for (int i = 0; i <= r; ++i) {
		for (int j = 0; j <= c; ++j) {
			res += rc[i][j];
			res %= mod;
		}
	}
