int qkmod(int a, int n) {
	LL res = 1;
	LL aa = (LL)(a);
	while (n) {
		if (n & 1) {
			res *= aa;
			res %= (LL)(mod);
		}
		aa = (aa * aa) % (LL)(mod);
		n /= 2;
	}
	return int(res);
}

