ModuloOps OPS(1e9 + 7);

long long calc(int n, int m) {
    long long v = 1;
    long long div = 1;
    for (int i = n+1; i <= n+m; i++) {
        v = OPS.mul(v, i);
    }
    for (int i = 1; i <= m; i++) {
        div = OPS.mul(div, i);
    }
    return OPS.mul(v, OPS.inv(div));
}

long long sum(int n, int m) {
    return OPS.sub(calc(n+1, m+1), 1);
}

