long fact(long n) {
  return n == 0 ? 1 : n * fact(n - 1) % mod;
}

long mpow(long b, long e) {
  if (e == 0) return 1;
  if (e % 2 == 1) return b * mpow(b, e - 1) % mod;
  long t = mpow(b, e / 2);
  return t * t % mod;
}

