int binpow(int w, int h)
{
	if(h == 0) return 1;
	if(h % 2 == 1) return binpow(w, h - 1) * w % mod;
	int m = binpow(w, h / 2) % mod;
	return m * m % mod;
}

int c(int n, int k)
{
	int num = f[n];
	int den = f[k] * f[n - k] % mod;
	return num * binpow(den, mod - 2) % mod;
}

