    return stream;
}

struct mintcomb{
    vector<mint> fact;
    vector<mint> ifact;
    mintcomb(ll n) : fact(n + 1, 1), ifact(n + 1, 1) {
        for(ll i = 2; i <= n; ++i){
            fact.at(i) = fact.at(i - 1) * i;
            ifact.at(i) = fact.at(i).inv();
        }
    }

    mint factorial(ll k) const { return fact.at(k); }
    mint combination(ll k, ll l) const {
        return fact.at(k) * ifact.at(l) * ifact.at(k - l);
    }
};

vector<mint> pow2, pow2cs;

mint calc(ll r, ll c){
    mint ans = 0;
    ans += pow2cs.at(r + c);
    mintcomb mc(r + c + 1);
    REP(i, c){
        const mint v = mc.combination(r + i, i);
        ans -= v * pow2cs.at(c - i - 1);
    }
    REP(i, r){
        const mint v = mc.combination(c + i, i);
        ans -= v * pow2cs.at(r - i - 1);
    }
    return ans;
}

