mint comb(ll n, ll r) {
  if(r<0||n<r) return 0;
  const int kMax=2000001;
  static mint fact[kMax+1],factr[kMax+1],inv[kMax+1];
  if(fact[0]==0){
    fact[0]=factr[0]=inv[1]=1;
    for(int i=2;i<=kMax;++i) inv[i]=inv[mod%i]*(mod-mod/i);
    for(int i=1;i<=kMax;++i) fact[i]=fact[i-1]*i, factr[i]=factr[i-1]*inv[i];
  }
  return factr[r]*fact[n]*factr[n-r];
}

