/* 二項係数計算用クラス． */
class Combinaion
{
private:
    /* テーブルの大きさを規定する．(MAX)! まで計算できる． */
    static constexpr ll MAX = 1e6 + 11;
    /* 階乗を格納するテーブル．fac[n] := n! % MOD. */
    vector<mint> fac;
    /* 階乗の逆元を格納するテーブル．finv[n] := (fac[n])^(-1). */
    vector<mint> finv;

    /* 各種テーブルを初期化する． */
    void init(int n)
    {
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        REPM(i, 2, n)
        {
            fac[i] = fac[i - 1] * i;
        }
        finv[n] = fac[n].inv();
        REPR(i, n, 2)
        {
            finv[i - 1] = finv[i] * i;
        }
    }

public:
    /* コンストラクタ． */
    Combinaion(int n = MAX) : fac(n + 1), finv(n + 1)
    {
        init(n);
    }

    /* 二項係数 nCk % MOD を計算する． */
    mint operator()(ll n, ll k) const
    {
        assert(n < MAX);
        assert(k < MAX);
        if (n < k || n < 0 || k < 0)
            return 0;
        return fac[n] * finv[k] * finv[n - k];
    }
};

