ll bigmod(ll a, ll b, ll m){
	a%=m;
	ll res = 1;
	while(b > 0){
		if(b&1)	res=(res*a)%m;
		a = (a*a)%m;
		b >>= 1;
	}
	return res;
}

void precompute(){
	f[0] = 1;
	for (int i = 1; i < MAX; ++i){
		f[i] = f[i-1]*i%MOD;
	}
	invf[MAX-1] = bigmod(f[MAX-1], MOD-2, MOD);
	for (int i = MAX-2; i > 0; --i){
		invf[i] = invf[i+1]*(i+1)%MOD;
	}
	invf[0] = 1;
}

ll nCr(ll n, ll r){
	return f[n]*invf[n-r]%MOD*invf[r]%MOD;
}

int main(){
