	ll ans = 0;
	for (ll i = r1; i <= r2; ++i){
		ans += nCr(i+c2+1, i+1) - nCr(i+c1, i+1) % MOD;
		ans %= MOD;
	}
	cout << (ans+MOD)%MOD << endl;
	return 0;
}

