using i64 = int64_t;

constexpr i64 MOD = 1e9 + 7;

vector<i64> fact(2000003);

i64 extgcd(i64 a, i64 b, i64 &x, i64 &y) {
    i64 d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1;
        y = 0;
    }
    return d;
}

i64 multi_inv(i64 a, i64 md) {
    i64 x, y;
    extgcd(md, a, x, y);
    return (y > 0 ? y : md + y);
}

i64 func(i64 a, i64 b){
    if(a == 0)return (b + 1) % MOD;
    i64 res = fact[a+b+2];
    res *= multi_inv(fact[a+1], MOD);
    res %= MOD;
    res *= multi_inv(fact[b+1], MOD);
