    REP(i, r+c+2){
        ans *= (long)(i+1);
        ans %= mod;
    }
    REP(i, r+1){
        ans *= modinv((long)(i+1), mod);
        ans %= mod;
    }
    REP(i, c+1){
        ans *= modinv((long)(i+1), mod);
        ans %= mod;
    }
    if(ans-1 < 0)
        return ans - 1 + mod;
    else
        return ans - 1;

}

