using namespace std;
#define MOD 1000000007

const int MAX = 1000000;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i=2; i<MAX; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main(){
    int r1, r2, c1, c2;
    cin >> r1 >> c1 >> r2 >> c2;
    long long result = 0;
    COMinit();
    for(int i=r1; i<= r2; i++){
        for(int j=c1; j<=c2; j++){
            result += COM(i+j, i);
            result %= MOD;
        }
    }
    cout << result;
    return 0;
}

