    for(int i=2;i<=kMax;++i) inv[i]=inv[mod%i]*(mod-mod/i);
    for(int i=1;i<=kMax;++i) fact[i]=fact[i-1]*i, factr[i]=factr[i-1]*inv[i];
  }
  return factr[r]*fact[n]*factr[n-r];
}

