    a -= b;
    if (a < 0)
        a += MOD;
    return a;
}

int binpow(int a, int n) {
    if (!n) return 1;
    if (n & 1) {
        return mul(a, binpow(a, n - 1));
    }
    else {
        return binpow(mul(a, a), n / 2);
    }
}

