    fact[0] = rfact[0] = 1;
    for (int i = 1; i < MAXN; i++) {
        fact[i] = mul(fact[i - 1], i);
        rfact[i] = inv(fact[i]);
    }
}

int c_n_k(int n, int k) {
    if (min(n, k) <= 0) return 1;
    return mul(fact[n], mul(rfact[k], rfact[n - k]));
}

