template <std::uint_fast64_t Modulus> class modint {
    using u64 = std::uint_fast64_t;

public:
    u64 a;

    modint(const u64 x = 0) noexcept : a(x % Modulus) {}
    u64 &value() { return a; }
    const u64 &value() const { return a; }
    modint operator+(const modint rhs) const  {
        return modint(*this) += rhs;
    }
    modint operator-(const modint rhs) const {
        return modint(*this) -= rhs;
    }
    modint operator*(const modint rhs) const {
        return modint(*this) *= rhs;
    }
    modint operator/(const modint rhs) const {
        return modint(*this) /= rhs;
    }
    modint &operator+=(const modint rhs) {
        a += rhs.a;
        if (a >= Modulus) {
            a -= Modulus;
        }
        return *this;
    }
    modint &operator-=(const modint rhs) {
        if (a < rhs.a) {
            a += Modulus;
        }
        a -= rhs.a;
        return *this;
    }
    modint &operator*=(const modint rhs) {
        a = a * rhs.a % Modulus;
        return *this;
    }
    modint &operator/=(modint rhs) {
        u64 exp = Modulus - 2;
        while (exp) {
            if (exp % 2) {
                *this *= rhs;
            }
            rhs *= rhs;
            exp /= 2;
        }
        return *this;
    }
};

const int prime = 1000000007;

modint<prime> modcom (int x, int y)
{
    modint<prime> a;
    a.a = 1;
    for (int i=0; i<y; i++) {
        modint<prime> m, n;
        m.a = x-i;
        n.a = i+1;
        a = a*m/n;
    }
    return a;
}

modint<prime> f (int r, int c)
{

    int min;
    if (r<c) { min = r; }
    else { min = c; }

