long long gun(int r, int c)
{
    long long ret;
    ret = fac[r + c];
    ret *= quickpow(fac[r], MOD - 2);
    ret %= MOD;
    ret *= quickpow(fac[c], MOD - 2);
    ret %= MOD;
    return ret;
}

