template <long long Mod = MOD>
class Factorial {
 private:
  int n;

 public:
  vector<long long> fac, inv;

 public:
  Factorial(long long n) : n(n), fac(n + 1), inv(n + 1) {
    fac[0] = 1;
    for (int i = 0; i < n; ++i) fac[i + 1] = fac[i] * (i + 1) % Mod;
    inv[n] = modpow(fac[n], Mod - 2);
    for (int i = n - 1; i >= 0; --i) inv[i] = inv[i + 1] * (i + 1) % Mod;
  };
  long long modpow(long long a, long long n, long long mod = Mod) {
    long long i = 1, ret = 1, p = a;
    while (i <= n) {
      if (i & n) {
        ret = (ret * p) % mod;
      }
      i = (i << 1);
      p = (p * p) % mod;
    }
    return ret;
  }
  long long C(int a, int b) {
    return (fac[a] * inv[b] % Mod) * inv[a - b] % Mod;
  }
  long long P(int a, int b) {
    return (fac[a]) * inv[a - b] % Mod;
  }
  long long H(int a, int b) {  //The number of multisets of length b on a symbols
    return C(a + b - 1, b);
  }
};

class Solver2 {
 public:
  int r1, r2, c1, c2;
  Factorial<> fac;
  Solver2(LL r1, LL r2, LL c1, LL c2) : r1(r1), r2(r2), c1(c1), c2(c2), fac(2222222){};

  void solve() {
    Modint<> ans(0);
    ans += calc(r2, c2);
    ans -= calc(r2, c1 - 1);
    ans -= calc(r1 - 1, c2);
    ans += calc(r1 - 1, c1 - 1);
    cout << ans << endl;
  }

  Modint<> calc(int r, int c) {
    auto ret = sumRows(r + c);
    DBG(ret)
    for (int i = 0; i < c; ++i) {
      // from (r,0) ~ (r,c-1)
      ret -= Modint<>(fac.C(r + i, r)) * sumRows(c - 1 - i);
    }
    for (int i = 0; i < r; ++i) {
      // from (0,c) ~ (r-1,c)
      ret -= Modint<>(fac.C(c + i, c)) * sumRows(r - 1 - i);
    }
    DBG(r, c, ret)
    return ret;
  }

  Modint<> sumRows(int x) {
    return Modint<>(2).mpow(x + 1) - 1;
  }
};
