long long calc(int r, int c) {
  if (c == 0 || r == 0) {
    return max(c + 1, r + 1);
  }

  long long res = 0;

  long long cur = 1;
  for (int i = 2; i < 2 + c; i++) {
    cur = cur * i % mod;
  }
  res = cur;

  for (int i = 1; i <= r; i++) {
    cur = cur * (2 + c + i - 1) % mod;
    cur = cur * inv(2 + i - 1) % mod;
    res = (res + cur) % mod;
  }

  res = res * inv(f[c]) % mod;
  return res;
}

long long calc(int r1, int c1, int r2, int c2) {
