long long comb_mod(long long n, long long r) {
    long long nume = 1;
    long long deno = 1;
    long long r_new = (r <= n/2) ? r : n-r;
    if (r_new < 0) {
        return 0;
    } else if (r_new == 0) {
        return 1;
    }

    for (long long i=1; i<=r_new; i++) {
