        deno %= MOD;
    }
    for (long long i=n-r_new+1; i<=n; i++) {
        nume *= i % MOD;
        nume %= MOD;
    }
    deno = inv(deno);
    return (deno * nume) % MOD;
}

ll sum(int i, int j) {
