const ll MOD = 1000000007;
template <typename T, typename F>
T apply_doubling(const T& x,
    const long long& n,
    const T& id_elem,
    const F& binary_op)
{
    if (n == 0)
        return id_elem;
    T ret = apply_doubling(binary_op(x, x), n / 2, id_elem, binary_op);
    if (n % 2 == 1)
        ret = binary_op(ret, x);
    return ret;
}

long long mod_pow(long long x, long long n, long long mod)
{
    return apply_doubling(x, n, 1ll, [mod](ll a, ll b) { return a * b % mod; });
}

long long mod_inv(long long x, long long mod)
{
    return mod_pow(x, mod - 2, mod);
}

const int MAXIN = 1000010;
//ll fact[MAXIN] = { 0 };
ll fact[MAXIN] = { 0 };

int my_main(int argc, char** argv)
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;

    fact[0] = 1;
    for (int i = 1; i < MAXIN; i++)
        fact[i] = i * fact[i - 1] % MOD;

    auto combi = [&](ll n, ll k) -> ll {
        ll ret = 1;
        ret = ret * fact[n] % MOD;
        ret = ret * mod_inv(fact[n - k], MOD) % MOD;
        ret = ret * mod_inv(fact[k], MOD) % MOD;

        return ret;
    };

    auto g = [&](int r, int c) {
        ll ret = 0;
        for (int i = 1; i <= r + 1; i++) {
            ret += combi((ll)c + i, (ll)i);
            ret %= MOD;
        }
        return ret;
    };

    ll ret = g(r2, c2);
    ret -= g(r2, c1 - 1);
    ret = (ret + MOD) % MOD;
    ret -= g(r1 - 1, c2);
    ret = (ret + MOD) % MOD;

    ret += g(r1 - 1, c1 - 1);
    ret %= MOD;

    cout << ret << endl;
    return 0;
}

