vector <ll> factorials;
vector <ll> inv_factorials;
ll mod=1e9+7;

ll modExp(ll x, ll n)
{
    if (n==0) return 1;
    if (n==1) return x%mod;
    ll ans = modExp(x,n/2);
    ans = (ans*ans)%mod;
    if (n%2) ans*=x;
    return ans%mod;
}

ll modInv(ll a)
{
    return modExp(a, mod-2);
}

ll choose(ll n, ll k) 
{
    if (k==0) return 1;
    if (k<0 || k>n) return 0;
    ll ans = factorials[n] * inv_factorials[k] % mod;
    return (ans * inv_factorials[n - k]) % mod;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    const int kRange = 3e6;
    factorials.resize(kRange + 1, 1);
    inv_factorials.resize(kRange + 1, 1);
    loop(i,2, kRange+1)
    {
        factorials[i]=(factorials[i-1]*i)%mod;
    }
    inv_factorials[kRange] = modInv(factorials[kRange]);
    for (int i = kRange - 1; i >= 0; --i) {
        inv_factorials[i] = (inv_factorials[i + 1] * (i + 1)) % mod;
    }

    ll r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;
    ll ans=0;
    for (ll j=c1; j<=c2; ++j)
    {
        ll temp = (choose(r2+j+1, j+1)-choose(r1+j, j+1)+mod)%mod;
        ans = (ans+temp)%mod;
    }
    cout << ans << "\n";
    return 0;
}

