constexpr int mod = 1000000007;
struct ModCalc {
    vector<int> fact;
    ModCalc(int N) : fact(N + 1) {
        fact[0] = 1;
        rep(i, N) fact[i + 1] = (long long)(i + 1) * fact[i] % mod;
    }
    int ModPow(int x, int y) {
        if (y == 0) return 1;
        long long a = ModPow(x, y / 2);
        if (y & 1) return a * a % mod * x % mod;
        else return a * a % mod;
    }
    int ModCom(int x, int y) {
        if (x < y) return 0;
        int res = fact[x];
        res = (long long)ModPow(fact[y], mod - 2) * res % mod;
        res = (long long)ModPow(fact[x - y], mod - 2) * res % mod;
        return res;
    }
};

int main() {
    int r1, r2, c1, c2;
    cin >> r1 >> c1 >> r2 >> c2;

    ModCalc MC(10000000);
    int sum1 = 0, sum2 = 0;
    for (int i = c1 + 1; i <= c2 + 1; ++i) {
        sum1 += MC.ModCom(r2 + i, i);
        sum1 %= mod;
        sum2 += MC.ModCom(r1 - 1 + i, i);
        sum2 %= mod;
    }
    int ans = sum1 - sum2;
    if (ans < 0) ans += mod;
    cout << ans << endl;
    return 0;
}

