struct Mod {
    static uint64_t PRIME;
    uint64_t value = 0;
    Mod() : value(0) {}
    Mod(ll v) {
        if (v >= 0) {
            value = v % PRIME;
        } else {
            value = PRIME - (-v) % PRIME;
        }
    }
    Mod operator+(const Mod& rhs) const {
        return Mod(*this) += rhs;
    }
    Mod& operator+=(const Mod& rhs) {
        value += rhs.value;
        if (value >= PRIME) {
            value -= PRIME;
        }
        return *this;
    }
    Mod operator-(const Mod& rhs) const {
        return Mod(*this) -= rhs;
    }
    Mod& operator-=(const Mod& rhs) {
        if (value < rhs.value) {
            value += PRIME;
        }
        value -= rhs.value;
        return *this;
    }
    Mod operator*(const Mod& rhs) const {
        return Mod(*this) *= rhs;
    }
    Mod& operator*=(const Mod& rhs) {
        value = (value * rhs.value) % PRIME;
        return *this;
    }
    Mod inv() const {
        return power(*this, PRIME - 2);
    }
    Mod operator/(const Mod& rhs) const {
        return Mod(*this) /= rhs;
    }
    Mod& operator/=(const Mod& rhs) {
        *this *= rhs.inv();
        return *this;
    }
    static Mod power(Mod rhs, ll exp) {
        Mod ans = 1;
        while (exp > 0) {
            if (exp % 2) {
                ans *= rhs;
            }
            rhs *= rhs;
            exp /= 2;
        }
        return ans;
    }
};
uint64_t Mod::PRIME = 1000000007;

vector<Mod> fact_table;

Mod binom(ll n, ll k) {
    if (!(n >= 0 && 0 <= k && k <= n)) {
        return 0;
    }
    if (k == 0 || k == n) {
        return 1;
    }
    return fact_table[n] / fact_table[k] / fact_table[n-k];
}

Mod ans_for(ll I, ll J) {
    Mod ans = 0;
    rep(j,0,J+1) {
        ans += binom(j+1+I, I);
    }
    return ans;
}

