const ll MOD = 1000000007;

vector<ll> sil(1000001);

ll Pot(ll p, ll w)
{
    if (w == 0)
        return 1;
    if (w % 2 == 0)
    {
        ll pol = Pot(p, w / 2);
        return pol * pol % MOD;
    }
    return Pot(p, w - 1) * p % MOD;
}

ll Inv(ll x)
{
    return Pot(x, MOD - 2);
}

ll C(ll n, ll k)
{
    return sil[n] * Inv(sil[n - k]) % MOD * Inv(sil[k]) % MOD;
}

ll Ile(ll a, ll b)
{
    ll il = b + 1;
    for (ll i = 1; i <= a; ++i)
        il = (il + C(i + b + 1, i + 1)) % MOD;
    return il;

}

