    if(r1 > 1)  res = (1LL * res - g(r1 - 1, c2) + MOD) % MOD;
    if(c1 > 1 and r1 > 1)  res = (1LL * res + g(r1 - 1, c1 - 1)) % MOD;
    return res;
}


