ll modp(ll a,ll b)
{
    ll r=1;
    while (b>0)
    {
        if(b&1)
        {
            r*=a;
            r%=modo;
        }
        a*=a;
        a%=modo;
        b>>=1;
    }
    return r;
}

ll ncr(ll n,ll r)
{
    ll nn=fac[n];
    ll dem=(fac[r]*fac[n-r])%modo;
    ll ans= nn*modp(dem,modo-2);
    ans%=modo;
    //cout<<n<<" "<<r<<" "<<ans<<endl;
    return ans;
}

ll help(ll n,ll r)
{
   // cout<<n<<" "<<r<<endl;
    if(n<r)return 0;
    return ncr(n+1,r+1);
}

