long long quickpow(long long b, int e)
{
	return e ? ((e & 1 ? b : 1)*quickpow(((b%MOD)*(b%MOD)) % MOD, e >> 1)) % MOD : 1;
}

long long gun(int r, int c)
{
    long long ret;
    ret = fac[r + c];
    ret *= quickpow(r, MOD - 2);
    ret %= MOD;
    ret *= quickpow(c, MOD - 2);
    ret %= MOD;
    return ret;
}

long long fun(int r, int c)
{
    long long ret = 0;
    for (int i = 1; i <= r; i++) {
        ret += gun(i + 1, c);
        ret %= MOD;
    }
    return ret;
}

