ll fact[N], rev[N];

ll pw(ll a, ll b) {
	if(!b)
		return 1;
	ll ans = pw(a, b / 2);
	ans *= ans;
	ans %= mod;
	if(b & 1)
		ans *= a;
	return ans % mod;
}

void prep() {
	fact[0] = 1;
	for (int i = 1; i < N; i++)
		fact[i] = (fact[i - 1] * i) % mod;
	rev[N - 1] = pw(fact[N - 1], mod - 2);
	for (int i = N - 2; ~i; i--)
		rev[i] = (1LL * rev[i + 1] * (i + 1)) % mod;
}

ll c(int n, int k) {
	if(k > n)
		return 0;
	ll ans = (fact[n] * rev[k]) % mod;
	ans *= rev[n - k];
	return ans % mod;
}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);	
	prep();
	int r1, c1, r2, c2;
	cin >> r1 >> c1 >> r2 >> c2;
	ll ans = 0;
	for (int i = r1; i <= r2; i++) {
		ll t = c(i + c2 + 1, i + 1) - c(i + c1, i + 1);
		t = ((t % mod) + mod) % mod;
		ans += t;
		ans %= mod;
	}
	cout << ans << "\n";
}

