struct Mod {
    static ll gcd(ll x, ll y, ll* out_cx, ll* out_cy) {
        if (x < 0) {
            ll d = gcd(-x, y, out_cx, out_cy);
            if (out_cx) {
                *out_cx *= -1;
            }
            return d;
        }
        if (y < 0) {
            ll d = gcd(x, -y, out_cx, out_cy);
            if (out_cy) {
                *out_cy *= -1;
            }
            return d;
        }
        if (x > y) {
            return gcd(y, x, out_cy, out_cx);
        }
        if (x == 0) {
            if (out_cx && out_cy) {
                *out_cx = 0;
                *out_cy = 1;
            }
            return y;
        }
        ll q = y / x;
        ll r = y % x;
        ll d = gcd(r, x, out_cy, out_cx);
        if (out_cx) {
            *out_cx -= q * *out_cy;
        }
        return d;
    }
    static ll BASE;
    ll value = 0;
    static ll residue(ll value) { return (value % BASE + BASE) % BASE; }
    Mod()
    : value(0) {}
    Mod(ll value)
    : value(residue(value)) {}
    Mod operator+(const Mod& rhs) const { return Mod(value + rhs.value); }
    void operator+=(const Mod& rhs) { *this = *this + rhs; }
    Mod operator-(const Mod& rhs) const { return Mod(value - rhs.value); }
    void operator-=(const Mod& rhs) { *this = *this - rhs; }
    Mod operator*(const Mod& rhs) const { return Mod(value * rhs.value); }
    void operator*=(const Mod& rhs) { *this = *this * rhs; }
    Mod operator/(const Mod& rhs) const { return *this * rhs.inv(); }
    void operator/=(const Mod& rhs) { *this = *this / rhs; }
    Mod inv() const {
        if (value == 0) {
            assert(false);
            throw "[Mod::inv] div by zero";
        }
        ll ans, sub;
        ll d = Mod::gcd(value, BASE, &ans, &sub);
        if (d != 1) {
            assert(false);
            throw "[Mod::inv] not invertible";
        }
        return ans;
    }
};
ll Mod::BASE = 1000000007;

vector<Mod> fact_table;

Mod binom(ll n, ll k) {
    if (!(n >= 0 && 0 <= k && k <= n)) {
        return 0;
    }
    if (k == 0 || k == n) {
        return 1;
    }
    return fact_table[n] / fact_table[k] / fact_table[n-k];
}

Mod ans_for(ll I, ll J) {
    Mod ans = 0;
    rep(j,0,J+1) {
        ans += binom(j+1+I, I);
    }
    return ans;
}

