template<ll N>
class Modfact{
private:
    mint _fact[N + 1], _invfact[N + 1];
public:
    constexpr Modfact() {
        _fact[0] = 1; rep(i, N) _fact[i + 1] = _fact[i] * (i + 1);
        _invfact[N] = mint::pow(_fact[N], -1);
        rep(i, N - 1, -1, -1) _invfact[i] = _invfact[i + 1] * (i + 1);
    }
    constexpr mint fact(ll n) const{return _fact[n];}
    constexpr mint invfact(ll n) const {return _invfact[n];}
    constexpr mint comb(ll n, ll k) const {return 0 <= k && k <= n ? _fact[n] * _invfact[k] * _invfact[n - k] : 0;}
    constexpr mint perm(ll n, ll k) const {return 0 <= k && k <= n ? _fact[n] * _invfact[n - k] : 0;}

};
