typedef long long ll;

vector<vector<ll>> comb(ll n, ll r) {
    vector<vector<ll>> v(n + 1,vector<long long>(n + 1, 0));
    for (ll i = 0; i < (ll)v.size(); i++) {
        v[i][0] = 1;
        v[i][i] = 1;
    }
    for (ll j = 1; j < (ll)v.size(); j++) {
        for (ll k = 1; k < j; k++) {
        v[j][k] = (v[j - 1][k - 1] + v[j - 1][k]) % 1000000007;
        }
    }
    return v;
}

