int revFacts[mx];

const auto precalc = []()
{
	facts[0] = 1;
	revFacts[0] = 1;
	for (int i = 1; i < mx; ++i) facts[i] = 1LL * facts[i - 1] * i % mod;
	revFacts[mx - 1] = inv(facts[mx - 1]) % mod;
	for (int i = mx - 2; i > 0; --i) revFacts[i] = 1LL * revFacts[i + 1] * (i + 1) % mod;
	return true;
}();

ll C(int n, int k)
{
    ll ans = 1;
    for(ll i = n; i >= (n - k + 1); --i) ans = (ans * i) % mod;
    return ans * revFacts[k] % mod;
}

