    ll ans = C(x1 + y1, x1) + C(x2 + y2, x2) - C(x3 + y3, x3) - C(x4 + y4, x4);
    ans %= mod;
    if(ans < 0) ans += mod;
    std::cout << ans << "\n";
	return 0;
}

