#define M 1000000007
ll powll(ll x,ll y){
  if(y==0){
    return 1;
  }
  ll ans=powll(x,y/2);
  if(y%2==0){
    ans=ans*ans%M;
  }else{
    ans=ans*ans%M*x%M;
  }
  return ans;
}
ll rec(ll x){
  ll ans=powll(x,M-2);
  return ans;
}
ll fact(ll x){
  ll ans=1;
  while(x>0){
    ans=ans*x%M;
    x--;
  }
  return ans;
}
ll fr_fa(ll x,ll y){
  ll ans=fact(x+y)%M * rec(fact(x))*rec(fact(y))%M;
  return ans;
}
int main(void){
  ll r1,c1,r2,c2;
  cin>>r1>>c1>>r2>>c2;
  ll ans=(fr_fa(c2+1,r2+1)+fr_fa(c1,r1)-fr_fa(c2+1,r1)-fr_fa(c1,r2+1)+M*2)%M;
  cout<<ans<<endl;
  return 0;
}

