#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1000000007;
#define MAX_V 2000005

inline void mult(int &a, int b) {
    ll p = 1ll * a * b;
    if (p >= MOD) p %= MOD;
    a = (int)p;
}

//Fast Exponentiation
ll fexp(ll base, ll exp, ll mod) {
    if (base >= mod) base %= mod;
    ll result = 1;
    while (exp > 0) {
        if (exp % 2 == 1) result = (result * base) % mod;
        exp >>= 1;
        base = (base * base) % mod;
    }
    return result;
}

int fact[MAX_V], invfact[MAX_V];
int main() {
    int r1, c1, r2, c2; scanf("%d%d%d%d", &r1, &c1, &r2, &c2);

    fact[0] = 1;
    for (int i = 1; i < MAX_V; i++) {
        fact[i] = fact[i - 1];
        mult(fact[i], i);
    }

    invfact[MAX_V - 1] = fexp(fact[MAX_V - 1], MOD - 2, MOD);
    for (int i = MAX_V - 2; i >= 0; --i) {
        invfact[i] = invfact[i + 1];
        mult(invfact[i], i + 1);
    }

    int ans = 0;
    int cur = fact[r2 + c2 + 2];
    mult(cur, invfact[r2 + 1]);
    mult(cur, invfact[c2 + 1]);

    ans += cur;
    if (ans >= MOD) ans -= MOD;

