    ans += cur;
    if (ans >= MOD) ans -= MOD;

    cur = fact[r1 + c2 + 1];
    mult(cur, invfact[r1]);
    mult(cur, invfact[c2 + 1]);

    if (ans >= MOD) ans -= MOD;

    ans %= MOD;
    if (ans < 0) ans += MOD;

    cout << ans;  
    return 0;
}

