		}
		P/=2;
		B=(B*B)%M;
	}
	return R;
}

ll Extended_Euclidean(ll a,ll b,ll &x,ll &y)
{
    if(b==0)
    {
        x=1;y=0;
        return a;
    }

    ll d;

    d=Extended_Euclidean(b,a%b,y,x);
    y=y-(a/b)*x;

    return d;
}
ll Inverse_Modulo(ll a,ll m)
{
    ll x,y,d;

    d=Extended_Euclidean(a,m,x,y);

    if(d==1)    return (x+m)%m; //Solution Exists
    return -1;  //No Solution
}



