#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

vector <long long> fac;

void genFacs(int n) {
  fac.push_back(1);
  for (int i = 1; i <= n; i++) {
    fac.push_back((fac[i-1]*i)%MOD);
  }
}

long long power(long long x, long long y) {
    long long res = 1;
    x = x % MOD;

    if (x == 0) return 0;
    while (y > 0) {
        if (y & 1) res = (res*x) % MOD;
        y = y >> 1;
        x = (x*x) % MOD;
    }
    return res%MOD;
}

int C(int n, int r) {
  return (fac[n]*power(fac[r]*fac[n-r],MOD-2))%MOD;
}

int line(int x, int y) {
  return C(x+y+1,x);
}

int rect(int x, int y) {
  int ans = 0;
  for (int i = 0; i <= y; i++) {
    ans += line(x,i);
    ans %= MOD;
  }
  return ans;
}

int main () {
  int x1,y1,x2,y2;
  cin >> x1 >> y1 >> x2 >> y2;
  genFacs(10000000);
  cout << rect(x1-1,y1-1) + rect(x2,y2) - rect(x1-1,y2) - rect(x2,y1-1) << "\n";
}

