  for (ll i = 1; i <= r2+c2+1; i++) {
    F[i] = (F[i-1] * i) % M;
  }
  for (ll i = c1; i <= c2; i++) {
    // sum(f(i+j, i)) = f(i+r2+1, i+1)
    // f(i+r2+1, i+1) = (i+r2+1)! / ((i+1)! * (r2)!)
    ll R = F[i+r2+1];
    R = (R * inv(F[i+1])) % M;
    R = (R * inv(F[r2])) % M;
    // sum(f(i+j, i)) = f(r1, i+1)
    // f(i+r1, i) = (i+r1)! / ((i+1)! * (r1-1)!)
    ll L = F[i+r1];
    L = (L * inv(F[i+1])) % M;
    L = (L * inv(F[r1-1])) % M;
    //cout << R << ' ' << L << endl;
    ret = (ret + R) % M;
    ret = ((ret - L) % M + M) % M;
  }
