const long long mod = 1e9 + 7;

long long fact[2000006];

long long Bin(long long a, long long n) {
	if (n == 0) return 1;
	long long l = Bin(a, n / 2);
	l = l * l % mod * ((n & 1) ? a : 1) % mod;
	return l;
}

long long rev(long long n) {
	return Bin(n, mod - 2);
}

long long C(long long k, long long n) {
	long long res = fact[n] * rev(fact[k]) % mod * rev(fact[n - k]) % mod;
	return res;
}

long long f(long long n, long long m) {
	if (n == 0 || m == 0) return 0LL;
	vector < long long > s(m);
	s[1] = (n * (n + 3) / 2 ) % mod;

	for (int i = 2; i < m; i++)
		s[i] = (2 * s[i - 1] + 1 - C(i, n + i) + 5 * mod) % mod;

	long long sum = 0;
	for (int i = 1; i < m; i++)
		sum = (sum + s[i]) % mod;

	return sum;
}

void solve(long long r1, long long c1, long long r2, long long c2) {
	r2++;
	c2++;
	c1++;
	r1++;
	long long res = f(r2, c2) + f(r1 - 1, c1 - 1) - f(r1 -1 , c2) - f(r2, c1 - 1);
