ll power(ll base, ll exp){
    ll ret = 1;
    while(exp > 0){
        if(exp % 2 == 0){
            base *= base;
            base %= P;
            exp /= 2;
        }
        else{
            ret *= base;
            ret %= P;
            exp -= 1;
        }
    }
    return ret;
}

ll inv(ll n){
    return power(n, P-2);
}

ll combi(ll r, ll c){
    ll ret = 1;
    ret *= factorial(r+c);
    ret %= P;
    ret *= inv(factorial(r));
    ret %= P;
    ret *= inv(factorial(c));
    ret %= P;
    return ret;
}

ll getAll(ll r, ll c){
    return (combi(r+1, c+1) + P - 1) % P;
}


