long long Modpow(long long a, long long n, long long mod)
{
    long long ans = 1;
    while(n > 0)
    {
        if(n & 1)
        {
            ans = ans * a % mod;
        }
        a = a * a % mod;
        n >>= 1;
    }
    return ans;
}

long long Modinv(long long a, long long mod)
{
    return Modpow(a, mod - 2, mod);
}

int main()
{
    constexpr int MOD = 1000000007;

    int r1, c1, r2, c2;
    std::cin >> r1 >> c1 >> r2 >> c2;

    // rCr + r+1 C r + ... + nCr = n+1 C r+1
    // ゆえに
    // r+c1 C r + ... + r+c2 C r = r+c2+1 C r+1 - r+c1 C r+1

    long long num1 = 1;
    long long den = 1;
    long long num2 = 1;

    // r1+c2+1 C r+1, r1+c1 C r+1
    for(int i = 0; i < r1 + 1; ++i)
    {
        num1 = num1 * (r1 + c2 + 1 - i) % MOD;
        den = den * (i + 1) % MOD;
        num2 = num2 * (r1 + c1 - i) % MOD;
    }

    long long comb1 = num1 * Modinv(den, MOD) % MOD;
    long long comb2 = num2 * Modinv(den, MOD) % MOD;
    long long curPath = (comb1 - comb2) % MOD;
    if(curPath < 0)
    {
        curPath += MOD;
    }
    long long sum = curPath;

    for(int r = r1 + 1; r <= r2; ++r)
    {
        num1 = num1 * (r + c2 + 1) % MOD;
        num2 = num2 * (r + c1) % MOD;
        den = den * (r + 1) % MOD;
        comb1 = num1 * Modinv(den, MOD) % MOD;
        comb2 = num2 * Modinv(den, MOD) % MOD;
        curPath = (comb1 - comb2) % MOD;
        if(curPath < 0)
        {
            curPath += MOD;
        }
        sum = (sum + curPath) % MOD;
    }

    std::cout << sum << std::endl;
}

