typedef long long LL;
const int N = 2e6+7, M = 1e9+7;

LL fac[N],invfac[N];

LL power(LL a, LL p) {
    if (p==0)   return 1;
    LL ans = power(a, p/2);
    ans = (ans * ans)%M;
    if(p%2) ans = (ans * a)%M;
    return ans;
}

void pre() {
    fac[0]= 1;
    for (int i=1; i<N; i++) fac[i] = (fac[i-1] * i)%M;
    invfac[N-1] = power(fac[N-1], M-2);
    for (int i=N-2; i>=0; i--)      invfac[i] = (invfac[i+1] * (i+1))%M;
}

LL C(int n, int r) {
    if ( r< 0 || r> n)  return 0;
    LL num = fac[n];
    LL denom = (invfac[r] * invfac[n-r])%M;
    return (num * denom)%M;
}

