long long quickpow(long long b, int e)
{
	return e ? ((e & 1 ? b : 1)*quickpow(((b%MOD)*(b%MOD)) % MOD, e >> 1)) % MOD : 1;
}

long long gun(int r, int c)
{
	long long ret;
	ret = fac[r + c];
	ret *= inv[r];
	ret %= MOD;
	ret *= inv[c];
	ret %= MOD;
	return ret;
}

long long fun(int r, int c)
{
	long long ret = 0;
	for (int i = 0; i <= r; i++) {
		ret += gun(i + 1, c);
		ret %= MOD;
	}
	return ret;
}

