ll M = 1000000007LL;
ll inv(ll K) {
  ll A = M - 2;
  ll ret = 1;
  ll D = K;
  while (A > 0) {
    if (A % 2 == 1) {
      ret = (ret * D) % M;
    }
    D = (D * D) % M;
    A /= 2;
  }
  return ret;
}
