    ll ans = 0;
    ans += comb(fac, ifac, m, r2+c2+2, c2+1);
    ans += MOD-comb(fac, ifac, m, c2+r1+1, r1);
    ans += MOD-comb(fac, ifac, m, r2+c1+1, c1);
    ans += comb(fac, ifac, m, r1+c1, r1);
    cout << ans%MOD << endl;
}

