template <typename T> struct Binom {
  vector<T> fact_, inv_fact_;

  explicit Binom(int n) : fact_(n + 1), inv_fact_(n + 1) {
    fact_[0] = 1;
    up(i, 1, n) fact_[i] = fact_[i - 1] * i;
    inv_fact_[n] = 1 / fact_[n];
    down(i, n, 1) { inv_fact_[i - 1] = inv_fact_[i] * i; }
  }

  T binom(int x, int y) const {
    if (x < 0 || y < 0)
      return 0;
    if (x < y)
      return 0;
    assert(x < SZ(fact_));
    return fact_[x] * inv_fact_[y] * inv_fact_[x - y];
  }

  T fact(int n) const {
    assert(n >= 0 && n < SZ(fact_));
    return fact_[n];
  }

  T inv_fact(int n) const {
    assert(n >= 0 && n < SZ(inv_fact_));
    return inv_fact_[n];
  }
};

