Fp myf(ll r, ll c) {
  Comb cb(r+c);
  if (r < c) swap(r, c);
  // Thus, we have r >= c.
  Fp tot = 1;
  Fp cur = 1;
  for (ll i = 0; i < r+c; i++) {
    if (i < c) {
      cur *= Fp(2);
      tot += cur;
    }else if (i < r) {
      cur = cur * Fp(2) - cb.comb(i, c);
      tot += cur;
    }else {
      cur = cur * Fp(2) - cb.comb(i, c) - cb.comb(i, r);
      tot += cur;
    }
  }
  return tot;
}

