int r1, c1, r2, c2;


void exgcd(ll a, ll b, ll &x, ll &y)
{
    if (b == 0) {x = 1, y = 0; return;}
    exgcd(b, a % b, y, x);
    y -= a / b * x;
}


ll invmod(ll a, ll m) {
    ll x, y;
    exgcd(a, m, x, y);
    return (x % m + m) % m;
}


void init()
{
    fac[0] = 1;
    for (int i = 1; i < L; i++) fac[i] = fac[i - 1] * i % Mod;
}


ll g(int r, int c)
{
    // sum(i = 0, r, sum(j = 0, c, binomial(i + j, i)))
    // = binomial(c + r + 2, c + 1) - 1
    // = (c + r + 2)! / (c + 1)! / (r + 1)! - 1
    ll ans = fac[c + r + 2] * invmod(fac[c + 1], Mod) % Mod;
    ans = ans * invmod(fac[r + 1], Mod) % Mod;
    ans = (ans - 1 + Mod) % Mod;
    return ans;
}


void solve()
{
    ll ans = g(r2, c2) - g(r1 - 1, c2) - g(r2, c1 - 1) + g(r1 - 1, c1 - 1);
    ans = (ans % Mod + Mod) % Mod;
    cout << ans << endl;
}


