constexpr ll MOD = 1000000007;

ll calc(vector<vll>& dp, int r, int c) {
    if (r == 1 || c == 1) { return (r + c) % MOD; }
    if (dp[r - 1][c - 1] != -1) { return dp[r - 1][c - 1]; }

    int r2 = dp.size(), c2 = dp[0].size();
    if (c <= r2 && r <= c2) {
        return dp[r - 1][c - 1] = dp[c - 1][r - 1] = (calc(dp, r - 1, c) + calc(dp, r, c - 1)) % MOD;
    } else {
        return dp[r - 1][c - 1] = (calc(dp, r - 1, c) + calc(dp, r, c - 1)) % MOD;
    }
}

