vector<bool> elas(ll n) {
	vector<bool> r(n);
	for (ll i = 3; i < n; i += 2)
	{
		r[i] = 1;
	}
	r[0] = 0;
	r[1] = 0;
	r[2] = 1;
	for (ll i = 3; i * i < n; i += 2)
	{
		if (!r[i]) continue;
		ll ti = i * 2;
		while (ti < n)
		{
			r[ti] = false;
			ti += i;
		}
	}
	return r;
}
