double heron(ll a, ll b, ll c) {
	double s = (double)(a + b + c) / 2.0;
	return sqrt(s * (s - a) * (s - b) * (s - c));
}


void solv() {

	ll r1, c1, r2, c2;
	cin >> r1 >> c1 >> r2 >> c2;
	ll res = 0;
	for (size_t i = 0; i <= r2; i++)
	{
		res += COM(c2 + (i + 1), i + 1);
		res %= INF;
	}
	ll sub = 0;
	for (size_t i = 0; i < r1; i++)
	{
		sub += COM(c2 + (i + 1), i + 1);
		sub %= INF;
	}
	for (size_t i = 0; i <= r2; i++)
	{
		sub += COM(c1 - 1 + (i + 1), i + 1);
		sub %= INF;
	}

	for (size_t i = 0; i < r1; i++)
	{
		sub += INF;
		sub -= COM(c1 - 1 + (i + 1), i + 1);
		sub %= INF;
	}

	res += INF;
	res -= sub;
	res %= INF;
	cout << res << endl;
}


