	return sum%MOD;
}

ll f(ll a, ll b)
{
	//(a+b)!/a!/b!;
	return arr[a+b]*cal(arr[a], MOD-2)%MOD*cal(arr[b], MOD-2)%MOD;
}

ll cal(ll a, ll b)
{
