void E(long long a, long long b, long long &x, long long &y)
{
    if(!b)
    {
        y=0;
        x=1;
    }
    else
    {
        long long x0, y0;
        E(b, a%b, x0, y0);
        x = y0;
        y = x0 - (a / b) * y0;
    }
}

long long Cmb(int a,int b)
{
    long long A, B, C, x, y, z;
    A = v[a];
    B = v[b];
    C = v[a-b];
    E(B, MOD, x, y);
    if (x < 0){
        x += ((-x) / MOD + 1LL) * MOD;
    }
    B = M (x);
    A = M (A * B);
    E(C, MOD, x, y);
    if (x < 0){
        x += ((-x) / MOD + 1LL) * MOD;
    }
    C = M(x);
    A = M(A * C);
    return A;
}

long long S (long long a, long long b){
    long long ans = 0;
    long long curr, curr1, x, y;
    if (a > b)
        swap (a, b);
    for (int it = 0; it < a; ++it){
        curr = M((b + 1) * v[b + it + 2]);
        curr1 = M(v[b + 1] * v[it + 2]);
        curr = (curr + MOD - curr1) % MOD;
        E(v[it + 2], MOD, x, y);
        if (x < 0){
            x += ((-x) / MOD + 1LL) * MOD;
        }
        curr1 = x;
        E(v[b + 1], MOD, x, y);
        if (x < 0){
            x += ((-x) / MOD + 1LL) * MOD;
        }
        curr1 = M(curr1 * x);
        curr = M(curr * curr1);
        ans = M (ans + curr);
    }
    return ans;
}

long long S1 (int a, int b){
    long long ans = 0;
    for (int it = 0; it < a; ++it){
        ans = M (ans + Cmb(b + it + 2, b));
    }
    return ans;
}

