ll f(ll r, ll c)
{
    ll ret = 0;
    ll left_r = 0;
    ll left_c = 0;
    ll right_r = 0;
    ll right_c = 0;
    ll incr = 1;

    while (left_r <= right_r && left_c >= right_c) {
        ret += incr;
        ret %= MOD;

        incr *= 2LL;
        incr %= MOD;

        left_c++;
        if (left_c > c) {
            ll diff = perms[left_c-1+left_r];
            diff *= perm_invs[left_c-1];
            diff %= MOD;
            diff *= perm_invs[left_r];
            diff %= MOD;
            incr -= diff;
            if (incr < 0) incr += MOD;
            left_c--;
            left_r++;
        }

        right_r++;
        if (right_r > r) {
            ll diff = perms[right_c+right_r-1];
            diff *= perm_invs[right_c];
            diff %= MOD;
            diff *= perm_invs[right_r-1];
            diff %= MOD;
            incr -= diff;
            if (incr < 0) incr += MOD;
            right_r--;
            right_c++;
        }
    }

    return ret;
}

