mint binomial(int n, int k) {
	return fact[n]/(fact[n-k]*fact[k]);
}

mint get(int r, int c) {
	mint ans = 0;

	for(int i = 0; i <= r; i++)
		ans += binomial(i+1+c, c);

	return ans;
}

