			ncr = ncr - (c - 1);
			add = ncr;
		}
		if (c + r1 > c) {
			mi ncr = nCr(c + r1 + 1 - 1, c + 1);
			ncr = ncr - (c - 1);
			add -= ncr;
		}
		ans += add;
	}
