const ll MOD = 1e9+7;
const ll MAX = 3e6+10;

ll fac[MAX<<2];  // fac[n] = n!
ll finv[MAX<<2]; // (fac[n] * finv[n]) % MOD = 1
ll inv[MAX<<2];  // (n * inv[n]) % MOD = 1

void init() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    FOR (i, 2, MAX<<2) {
        fac[i] = fac[i-1]*i % MOD;
        inv[i] = MOD - inv[MOD%i]*(MOD/i) % MOD;
        finv[i] = finv[i-1]*inv[i] % MOD;
    }
}

ll nCk (int n, int k) {
    if (n < k || k < 0 || n < 0) return 0;
    return fac[n]*finv[k]%MOD*finv[n-k]%MOD;
}

ll count(int x, int y) {
    ll res = (MOD + nCk(x + y + 2, x + 1) - 1) % MOD;
    return res;
}

int solve(int a, int b, int x, int y) {
    return (4ll * MOD + count(x, y) - count(a-1, y) - count(x, b-1) + count(a-1, b-1)) % MOD;
}

