    mint res = 0;
    for(int r = y1; r <= y2; r++){
        mint tmp = bc.com(x2 + r + 1, r + 1) - bc.com(x1 + r, r + 1);
        res += tmp;
    }
    std::cout << res << std::endl;
    return 0;
}

