constexpr int N_MAX = 2000001;
constexpr ll MOD = 1000000007;

ll fact[N_MAX+1], rfact[N_MAX+1];

ll perm(ll n, ll k) {
    if(n-k < 0LL) return 0LL;
    return (fact[n] * rfact[n-k]) % MOD;
}

ll comb(ll n, ll k) {
    if(n-k < 0LL) return 0LL;
    return (perm(n, k) * rfact[k]) % MOD;
}

ll modpow(ll a, ll p) {
    ll ret = 1LL;
    while(p) {
        if(p & 1) {
            ret = (ret * a) % MOD;
        }
        a = (a * a) % MOD;
        p >>= 1;
    }
    return ret;
}

void init_fact(ll n) {
    fact[0] = fact[1] = 1;
    rfact[0] = rfact[1] = 1;
    for(ll i=2;i<=n;++i) {
        fact[i] = (fact[i-1] * i) % MOD;
        rfact[i] = modpow(fact[i], MOD-2);
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    ll r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;

    init_fact(c2+r2+1);

    ll ans = 0LL;
    for(ll r=r1;r<=r2;++r) {
        ans += comb(c2+r+1, r+1);
        ans %= MOD;
        ans += (MOD - comb(r+c1, r+1)) % MOD;
        ans %= MOD;
    }

    cout << ans << endl;
}

