const ll MOD = 1000000007;
struct Modint{
    ll num = 0;
    Modint(){}
    Modint(ll x){ x %= MOD; if(x < 0) x += MOD; num = x; }
    operator ll(){ return num; }
    Modint& operator+=(Modint x){ num += x.num; if(num >= MOD) num -= MOD; return *this; }
    Modint& operator-=(Modint x){ if(num < x.num) num += MOD; num -= x.num; return *this; }
    Modint& operator*=(Modint x){ num = num * x.num % MOD; return *this; }
    Modint& operator/=(Modint x){ return *this *= x.inv(); }
    Modint operator+ (Modint x) const { return Modint(*this) += x; }
    Modint operator- (Modint x) const { return Modint(*this) -= x; }
    Modint operator* (Modint x) const { return Modint(*this) *= x; }
    Modint operator/ (Modint x) const { return Modint(*this) /= x; }
    Modint inv(){
        return pow(MOD - 2); // MOD - 2 乗で逆元を取る
    }
    Modint pow(ll x){
        Modint ans = 1, cnt = *this;
        while(x){
            if(x & 1) ans *= cnt;
            cnt *= cnt;
            x /= 2;
        }
        return ans;
    }
};
Modint operator""_M(unsigned long long x) { return Modint(x); }

const ll MAX = 2020202;
vector<Modint> fac(MAX), inv(MAX);
void init(){
    fac[0] = 1;
    for(ll i = 1; i < MAX; i++) fac[i] = fac[i - 1] * Modint(i);
    inv.back() = fac.back().inv();
    for(ll i = MAX - 1; i > 0; i--) inv[i - 1] = inv[i] * Modint(i);
}

Modint comb(ll n, ll r){
    return fac[n] * inv[r] * inv[n - r];
}

