struct Hashing {
    ull seed, mod;
    vector <ull> hs, pw;

    Hashing(ull seed = 31, ull mod = 1000173169) :
        seed(seed),
        mod(mod) {}

    void build(int n, const string& s) {
        hs.assign(n + 1, 0);
        pw.assign(n + 1, 1);
        pw[0] = 1;

        for (int i = 1; i <= n; ++i)
            pw[i] = pw[i - 1] * seed % mod;
        for (int i = 1; i <= n; ++i)
            hs[i] = (hs[i - 1] * seed + s[i]) % mod;
    }

    ull hash(int l, int r) {
        return (hs[r] - hs[l - 1] * pw[r - l + 1] % mod + mod) % mod;
    }
};

int solve()
{
    int r1, c1, r2, c2;

    cin >> r1 >> c1 >> r2 >> c2;

    vector<int> dp(c2 + 1);
    dp[0] = 1;
    ll ans = 0;
    const int mod = 1000000007;

    for (int i = 0; i <= r2; ++i) {
        for (int j = 1; j <= c2; ++j) {
            dp[j] = (dp[j] + dp[j-1]) % mod;

            if (i >= r1 && j >= c1)
                ans = (ans + dp[j]) % mod;
        }
    }

    cout << ans << endl;

    return 0;
}

int main()
{
    solve();

