int ksm(long long x,long long y)
{
	x %= MOD;
	long long rt = 1LL;
	while ( y )
	{
		if ( y & 1 )
			rt = rt * x % MOD;
		x = x * x % MOD;
		y >>= 1;
	}
	return (int)rt;
}

int C(int n,int m)
{
	if ( n < m )
		return 0;
	long long rt = 1LL;
	for ( int i = 0 ; i < m ; i++ )
		rt = rt * (long long)(n-i) % (long long)MOD * (long long)ksm(i+1,MOD-2) % (long long)MOD;
	return (int)rt;
}

int u(int x,int y)
{
	return C(x+y,min(x,y));
}

