long long comb(int n, int r){
    vector<vector<long long> > v(n + 1, vector<long long>(r + 1, 0));
    for(int i = 0; i < n + 1; i++) {
        v[i][0] = 1;
        if (i < r + 1) {
            v[i][i] = 1;
        }
    }
    for(int i = 1; i < n + 1; i++) {
        for(int j = 1; j < min(i, r+1); j++) {
            v[i][j] = v[i - 1][j - 1] + v[i - 1][j];
        }
    }
    return v[n][r];
}


