    ll R1, R2, C1, C2; cin >> R1 >> C1 >> R2 >> C2;
    ll ans = 0; R1--;
    FOR(i, C1, C2+1) {
        ans += choose(i+R2+1, R2);
        ans += MOD - choose(i+R1+1, R1); ans %= MOD;
    }
