#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

constexpr int MAXN = 1000000, MAXF = 2 * MAXN + 2, MOD = 1000000007;

int fac[MAXF + 2], inv[MAXF + 2];

int mpow(int b, int e) {
	int res = 1;
	while(e) {
		if(e & 1) res = (ll)res * b % MOD;
		b = (ll)b * b % MOD;
		e >>= 1;
	}
	return res;
}

int comb(int n, int k) {
	return (ll)fac[n] * inv[k] % MOD * inv[n - k] % MOD;
}

int reduce(int x) {
	return x >= MOD ? x - MOD : x;
}

int psa(int x, int y) {
	return reduce(comb(x + y + 2, x + 1) + MOD - 1);
}

int rect(int x1, int y1, int x2, int y2) {
	--x1; --y1;
	return ((ll)psa(x2, y2) - psa(x1, y2) - psa(x2, y1) + psa(x1, y1) + 2ll * MOD) % MOD;
}

int main() {
	fac[0] = 1;
	for(int i = 1; i <= MAXF; i++)
		fac[i] = (ll)fac[i - 1] * i % MOD;
	inv[MAXF] = mpow(fac[MAXF], MOD - 2);
	for(int i = MAXF - 1; i > 0; i--)
		inv[i] = (ll)(i + 1) * inv[i + 1] % MOD;
	int r1, c1, r2, c2;
	cin >> r1 >> c1 >> r2 >> c2;
	int ans = rect(c1, r1, c2, r2);
	cout << ans << '\n';
}

