modlong rect(int r, int c) {
    modlong ans = modlong(2).pow(r + c + 1) - 1,
            pow = modlong(2).pow(c);
    for (int i=0; i<c; i++) {
        ans -= modComb(r + i, i) * (pow - 1);
        pow /= 2;
    }
    pow = modlong(2).pow(r);
    for (int i=0; i<r; i++) {
        ans -= modComb(c + i, i) * (pow - 1);
        pow /= 2;
    }
    return ans;
}

