int add(int x,int y) {
  return ((x+y)%mod+mod)%mod;
}
int mul(int x,int y) {
  return (ll)x*y%mod;
}
int mypow(int x,int c) {
  int ret = 1;
  while(c>0) {
    if(c&1) {
      ret = mul(ret,x);
    }
    x = mul(x,x);
    c/=2;
  }
  return ret;
}

int fac[N],invFac[N];
int combi(int n,int r) {
  if(n<r) {
    return 0;
  }
  int ret = mul(fac[n],invFac[r]);
  ret = mul(ret, invFac[n-r]);
  return ret;
}

int f(int r,int c) {
  int ret = 0,pp = r+1;
  ret = pp;
  for(int i=1;i<=c;++i) {
    int tmp = add(mul(r+1,pp), mul(i,combi(r+i,i)));
    tmp = mul(tmp, mypow(i+1,mod-2));
    ret = add(ret,tmp);
    pp = tmp;
  }
  return ret;
}

void solve() {
  int r1,c1,r2,c2;
  scanf("%d %d %d %d ", &r1,&c1,&r2,&c2);
  fac[0] = invFac[0] = 1;
  for(int i=1;i<N;++i) {
    fac[i] = mul(fac[i-1],i);
    invFac[i] = mypow(fac[i],mod-2);
  }
  int ret = add(f(r2,c2),f(r1-1,c1-1));
  ret = add(ret, -add(f(r1-1,c2),f(r2,c1-1)));

  //printf("%d\n", f(r2,c2));
  printf("%d\n", ret);
}

int main() {
    //freopen("input.txt","r",stdin);
    solve();
    return 0;
}

