const int MAX = 1000001;
long long fac[MAX], finv[MAX], inv[MAX];
ll ans[1000001][1000001];

// n次元配列の初期化。第２引数の型のサイズごとに初期化していく。
template<typename A, size_t N, typename T>
void Fill(A (&array)[N], const T &val){
