int main(){

  // read problem
  long long int r1, c1, r2, c2;
  scanf("%lld%lld%lld%lld", &r1, &c1, &r2, &c2);

  // make factorial table
  std::vector<long long int> fact_table(NMAX), fact_inverse(NMAX);
  fact_table[0] = 1;
  fact_inverse[0] = 1;
  for(long long int i = 1; i < NMAX; i++){
    fact_table[i] = (fact_table[i-1]*i + MOD)%MOD;
    fact_inverse[i] = mod_inverse_Fermat(fact_table[i], MOD);
  }

  // solve problem
  long long int tmp1, tmp2, tmp;
  long long int ans = 0;

  tmp2 = 0;
  for(long long int i = r2; i > r1; i--){
    // tmp1 = r+c1 C r
    tmp1 = (fact_table[i+c1] * fact_inverse[i] + MOD)%MOD;
    tmp1 = (tmp1*fact_inverse[c1] + MOD)%MOD;
    // add tmp1
    ans += tmp1;
    ans = (ans+MOD)%MOD;
    // tmp2 += c2-c1 +r2-i C r2-i+1
    tmp = (fact_table[c2-c1+r2-i]*fact_inverse[r2-i+1] + MOD)%MOD;
    tmp = (tmp*fact_inverse[c2-c1-1] + MOD)%MOD;
    tmp2 = (tmp2+tmp+MOD)%MOD;
    // add tmp1*tmp2
    tmp = (tmp1*tmp2 + MOD)%MOD;
    ans += tmp;
    ans = (ans+MOD)%MOD;
  }

  // add f(r1, c1)
  tmp1 = (fact_table[r1+c1] * fact_inverse[r1] + MOD)%MOD;
  tmp1 = (tmp1*fact_inverse[c1] + MOD)%MOD;
  ans += tmp1;
  ans = (ans+MOD)%MOD;

  tmp2 = 0;
  for(long long int i = c2; i > c1; i--){
    // tmp1 = r1+i C r1
    tmp1 = (fact_table[i+r1]*fact_inverse[r1] + MOD)%MOD;
    tmp1 = (tmp1*fact_inverse[i] + MOD)%MOD;
    // add tmp1
    ans += tmp1;
    ans = (ans+MOD)%MOD;
    // tmp2 += r2-r1 + c2-i C c2-i+1
    tmp = (fact_table[r2-r1 + c2-i]*fact_inverse[c2-i+1] + MOD)%MOD;
    tmp = (tmp*fact_inverse[r2-r1-1] + MOD)%MOD;
    tmp2 = (tmp2+tmp+MOD)%MOD;
    // add tmp1*tmp2
    tmp = (tmp1*tmp2 + MOD)%MOD;
    ans += tmp;
    ans = (ans+MOD)%MOD;
  }

  std::cerr << "Answer: " << std::endl;
  std::cout << ans << std::endl;

  return 0;
}


long long int mod(long long int x, long long int m){
  if(x>0){
    return x%m;
  }
  else if(x==0){
    return 0;
  }
  else if((-x)%m == 0){
    return 0;
  }
  else{
    return m - (-x)%m;
  }
}


long long int euclid_extended(long long int a, long long int b, long long int &x, long long int &y){
  long long int d = a;
  if(b != 0){
    d = euclid_extended(b, a%b, y, x);
    y -= (a/b)*x;
  }
  else{
    x = 1;
    y = 0;
  }

  return d;
}

long long int mod_inverse(long long int x, long long int m){
  long long int tmp, x_inv, gcd_xm;
  gcd_xm = euclid_extended(x, m, x_inv, tmp);
  // if the inverse is calculate properly
  if(gcd_xm == 1){
    return mod(x_inv, m);
  }
  else{
    //std::cerr << "Error in mod_inverse: there is no inverse of x in mod m" << std::endl;
    return 0;
  }
}

long long int mod_inverse_Fermat(long long int x, long long int m){
  return fast_power(x, m-2, m);
}

long long int fast_power(long long int x, long long int n, long long int m){
  long long int ans = 1;

  while(n > 0){
    if(n&1){
      ans = ans * x;
      ans = mod(ans, m);
    }
    x = x*x;
    x = mod(x, m);
    n = n>>1;
  }

  return ans;
}

