long long mypow(long long k, long long n) {
	long long temp = 1;

	k = k % DIV;
	while (n) {
		if (n % 2) temp = temp * k % DIV;
		k = k * k % DIV;
		n = n / 2;
	}
	return temp % DIV;
}

ll mmod(ll a, ll b) {
	if (a < 0)a += DIV; if (b < 0) b += DIV;
	a %= DIV, b %= DIV;
	return a * b % DIV;
}

int main() {
	ll r1, c1, r2, c2; cin >> r1 >> c1 >> r2 >> c2;
	vector<ll> f(TE + 1), invf(TE + 1);
	f[0] = 1, invf[0] = 1;
	for (int i = 1; i <= TE; i++) {
		f[i] = mmod(f[i - 1], i);
		invf[i] = mypow(f[i], DIV - 2);
		//cout << i << endl;
	}

	ll ans = 0;
	for (int k = r1; k <= r2; k++) {
		ll temp = mmod(mmod(f[k + c2 + 1], invf[c2]), invf[k + 1]);
		temp -= mmod(mmod(f[k + c1], invf[c1 - 1]), invf[k + 1]);
		temp += DIV;
		temp %= DIV;
		ans = (ans + temp) % DIV;
		//cout << ans << endl;
	}
	cout << ans << endl;
}

