//mod逆元を使ったnCkの計算(速)
const int64_t MAX = 510000;
const int64_t MOD = 1000000007;

int64_t fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

// 二項係数計算
int64_t COM(int64_t n, int64_t k){
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int64_t calc(int64_t x, int64_t y1, int64_t y2){
  int64_t A = COM(x+y2+1, y2); //0からc2まで
  int64_t B = COM(x+y1, y1-1); //0からc1-1まで
  A -= B;
  if(A < 0){
    A += MOD;
  }
  return A % MOD;
}



int main(){
  int64_t r1, c1, r2, c2;
  cin >> r1 >> c1 >> r2 >> c2;
  int64_t sum = 0;
  COMinit();
  for(int i=r1; i<=r2; i++){
    sum += calc(i,c1,c2);
    sum %= MOD;
  }
  cout << sum << endl;
}

