    vector<vector<int> > dp(sr, vector<int>(sc, 0));
    for (int i = 0; i < sr; i++) {
        dp[i][0] = comb(r1 + c1 + i, r1 + i) % mod;
    }
    for (int j = 0; j < sc; j++) {
        dp[0][j] = comb(r1 + c1 + j, r1) % mod;
    }

    for (int i = 1; i < sr; i++) {
        for (int j = 1; j < sc; j++) {
            dp[i][j] = (dp[i - 1][j] + dp[i][j - 1]) % mod;
        }
    }
    int sum = 0;
    for (int i = 0; i < sr; i++) {
        for (int j = 0; j < sc; j++) {
            sum = (sum + dp[i][j]) % mod;
        }
    }

    cout << sum << '\n';

    return 0;
}

