using namespace std;
typedef long long ll;
#define UP 2000005
#define mod 1000000007
ll pw[UP] = {0, 1};
ll inv[UP] = {1, 1};
ll modinv(ll a, ll p) {
    if (p == 1) return 0;
    ll pp = p, y = 0, x = 1;
    while (a > 1) {
        ll q = a / p, t = p;
        p = a % p, a = t, t = y, y = x - q * y, x = t;
    }
    if (x < 0) x += pp;
    return x;
}
void init() {
	for (int i = 2; i < UP; i++) {
		pw[i] = pw[i-1] * i % mod;
		inv[i] = modinv(pw[i], mod);
		//cout <<  i << " " << pw[i] << " " << inv[i] << "\n";
	}
}
ll C(int a, int b) {
	return pw[a] * inv[a-b] % mod * inv[b] % mod;
}
int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	int r1, c1, r2, c2;
	cin >> r1 >> c1 >> r2 >> c2;
	init();
	ll ans = 0;
	for (int x = r1; x <= r2; x++) {
		ans = (ans + C(c2 + x + 1, x + 1)) % mod;
		ans = (ans + mod - C(c1 + x, x + 1)) % mod;
	}
	cout << ans << "\n";
	return 0;
}

