ll numberOfPaths(ll m, ll n) 
{ 
    // Create a 1D array to store results of subproblems 
    ll dp[n] = { 1 }; 
    dp[0] = 1; 

    for (ll i = 0; i < m; i++) { 
        for (ll j = 1; j < n; j++) { 
            dp[j] += dp[j - 1]; 
        } 
    } 

    return dp[n - 1]; 
} 

