ll qpow(ll a,ll b)
{
	if(b==0)	return 1;
	ll c=qpow(a,b/2);
	if(b%2==0)	return c*c%mod;
	else		return c*c%mod*a%mod;
}
ll cnm(ll n,ll m)
{
	return nj[m+n]*qpow(nj[n],mod-2)%mod*qpow(nj[m],mod-2)%mod;
}
ll f()
{
	return cnm(r1,c1)+cnm(r2+1,c2+1)-cnm(r1,c2+1)-cnm(r2+1,c1);
}
