void mulmod(ll &a,ll &b)
{
    if(a<0)
        a += MOD;
    if(b<0)
        b+= MOD;
    a = (a*b)%MOD;
    if(a<0)
        a += MOD;
}

ll bpow(ll base,ll pow)
{
    if(pow == 0) return 1ll;
    ll ans = bpow(base,pow/2);
    mulmod(ans,ans);
    if(pow%2)
        mulmod(ans,base);
    return ans;
}

ll minv(ll i)
{
    return bpow(i,MOD-2);
}

void pre()
{
    fact[0]=1;
    for(int i=1;i<mx;i++)
    {
        fact[i] = (fact[i-1]*i)%MOD;
    }
    modinv[mx-1] = minv(fact[mx-1]);
    for(int i=mx-2;i>=0;i--)
    {
        modinv[i] = (modinv[i+1]*(i+1))%MOD;
    }
}

ll choose(ll n,ll r)
{
    if(r==0) return 1;
    if(r<0 || r>n) return 0;
    ll num = fact[n];
    mulmod(num,modinv[r]);
    mulmod(num,modinv[n-r]);
    return num;
}

void solve()
{
    pre();
    ll r1,c1,c2,r2;
    cin>>r1>>c1>>r2>>c2;
    ll ans = 0,temp;
    //cout<<fact[1e5]<<endl;
    for(int i =c1;i<=c2;i++)
    {
        temp = (choose(i+r2+1,i+1) - choose(i+r1,i+1) + MOD)%MOD;
        ans = (ans + temp)%MOD;
    }   
    cout<<ans<<endl;
}

