using lli = long long int;
lli inf = 1000000007;
using namespace std;

vector<lli> fac(2000010);
vector<lli> inv(2000010);

lli rep_pow(lli x, lli p, lli m = 1000000007)
{
	lli res = 1;
	while (p > 0)
	{
		if ((p & 1) == 1) res = (res * x) % m;
		x = (x * x) % m;
		p >>= 1;
	}
	return res % m;
}

lli conb(lli n, lli r) {
	lli ret = (fac[n] * inv[r]) % inf;
	ret = (ret * inv[n - r]) % inf;
	return ret;
}

lli g(int r, int c) {
	return conb(r + c + 2, c + 1) - 1;
}

void solve() {
	int r1, r2, c1, c2;
	cin >> r1 >> c1 >> r2 >> c2;
	// パスカルの気持ち
	r1 -= 1;
	c1 -= 1;

	// 階乗とその逆元を前計算
	inv[0] = inv[1] = fac[0] = fac[1] = 1;
	for (int i = 2; i <= 2000000; i++) {
		fac[i] = fac[i - 1] * i;
		fac[i] %= inf;
		inv[i] = rep_pow(fac[i], inf - 2);
	}

	lli ans = g(r2, c2) - g(r1, c2) - g(r2, c1) + g(r1, c1);
	cout << ans << endl;

}

int main()
{
	solve();
	return 0;
