constexpr int MAX = 2000002;
constexpr int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
  static bool init = false;
  if (init) {
    return;
  }
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
  init = true;
}

long long COM(int n, int k){
  COMinit();
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


int f(int r, int c) {
  return COM(r + c, r);
}

long long g(int r, int c) {
  long long sum = 0;
  for (int j = 0; j <= r; ++j) {
    sum = (sum + f(j + 1, c)) % MOD;
  }
  return sum;
}

