const long long MOD = 1000000007;

typedef long long LL;
LL n,m,p=MOD;
LL quick_mod(LL a, LL b)
{
    LL ans = 1;
    a %= p;
    while(b)
    {
        if(b & 1)
        {
            ans = ans * a % p;
            b--;
        }
        b >>= 1;
        a = a * a % p;
    }
    return ans;
}
LL C(LL n, LL m)
{
    if(m > n) return 0;
    LL ans = 1;
    for(int i=1; i<=m; i++)
    {
        LL a = (n + i - m) % p;
        LL b = i % p;
        ans = ans * (a * quick_mod(b, p-2) % p) % p;
    }
    return ans;
}
LL Lucas(LL n, LL m)
{
    if(m == 0) return 1;
    return C(n % p, m % p) * Lucas(n / p, m / p) % p;
} 
void solve(int r1,int r2,int c1,int c2){
    auto ret = Lucas(c2+r2+2,c2+1) - Lucas(c2+r1+1,c2+1) - Lucas(c1+r2+1,c1) + Lucas(c1+r1,c1);
    ret = (ret % MOD + MOD ) % MOD;
    cout<<ret<<endl;
}

