uint64_t total_path(uint64_t r, uint64_t c, vector<vector<uint64_t>> &memo)
{
    if(!memo[r][c]) memo[r][c] = (r && c) ? (total_path(r-1, c, memo) + total_path(r, c-1, memo)) % MOD : 1;
    return memo[r][c];
}

