    auto calcu_y = [&](mint k, int r){
        mint ans = k;
        for(int i=1; i<=c2-c1; ++i){
            k *= (c1+r+i);
            k /= (c1+i);
            ans += k;
        }
        return ans;
    };

    mint res = 0;
    for(int i=r1; i<=r2; ++i){
        mint k = bc.fact(i+c1) * bc.finv(i) * bc.finv(c1);
        res += calcu_y(k, i);
        // for(int j=c1; j<=c2; ++j){
        //     mint tmp = bc.fact(i+j) *bc.finv(i) * bc.finv(j);
        //     res += tmp;
        // }
    }

    cout << res << endl;

}

