VLL fact_inv, fact;

ll power(ll a, ll b, ll m){
    ll ret = 1;
    while(b){
        if(b & 1) ret = (ret * a) % m;
        a = (a * a) % m;
        b /= 2;
    }
    return ret;
}

ll power(ll a, ll b) {
    return power(a, b, MOD);
}

ll inv(ll a, ll m){ // GCD(a, m) = 1
    return power(a, m-2);
}

ll inv(ll a){
    return inv(a, MOD);
}

ll comb(ll a, ll b, ll m){
    if(a < b) return 0;
    if(a < 0 || b < 0) return 0;
    ll ret = fact[a];
    ret = ret * fact_inv[b] % m;
    ret = ret * fact_inv[a-b] % m;
    return ret;
}

ll comb(ll a, ll b){
    return comb(a, b, MOD);
}

void precom(int n, ll m){
    fact.resize(n);
    fact_inv.resize(n);
    fact[0] = fact[1] = 1;
    fact_inv[0] = fact_inv[1] = 1;
    for(int i = 2; i < n; ++i) fact[i] = fact[i-1] * i % m;
    for(int i = 2; i < n; ++i) fact_inv[i] = inv(fact[i]);
    return;
}

void precom(int n){
    precom(n, MOD);
    return;
}

ll comsum(int r1,int r2, int c1, int c2){
    ll ret = 0;
    if(r1 == r2){
        FORS(i, c1, c2){
            ret = (ret + comb(r1+i, i)) % MOD;
        }
        if(ret < 0) ret += MOD;
        return ret;
    }
    return comsum(r1+1, r2, c1+1, c2);
}

int main(){
    int r1, c1, r2, c2; cin >> r1 >> c1 >> r2 >> c2;
    precom(r2+c2+1);
    if(r2 - r1 > c2 - c1){
        swap(r1, c1); swap(r2, c2);
    }
    ll ans = (comb(r1+c1, r1) + comb(r2+c2, r2)) % MOD;
    FORS(i, c1+1, c2) ans = (ans + comb(r2+i, r2)) % MOD;
    FORS(i, r1+1, r2-1) ans = (ans + comb(c2+i, c2)) % MOD;
    cout << (ans<0 ? ans + MOD : ans) << endl;
    return 0;
}

