void solve() {
    din(H1, W1, H2, W2);
    auto calc = [&](int H, int W) {
        mint res = 0;
        auto yoko=[&](int N, int B){
            return (N+1)*com(N,B) / (B+1);
        };
        rep(h, H + 1) {
            res += yoko(W+h, h);
            if(h)res -= yoko(h-1,h);
        }
        return res;
    };
    mint res = calc(H2, W2);
    deb(res);
    res -= calc(H1 - 1, W2);
    deb(res);
    res -= calc(H2, W1 - 1);
    deb(res);
    res += calc(H1 - 1, W1 - 1);
    out(res);
}


