int st(int a, int b) {
    if (b == 0) return 1;
    if (b % 2 == 0) {
        int c = st(a, b / 2);
        return c * c % mod;
    }
    return a * st(a, b - 1) % mod;
}

int answer(int x, int y) {
    int ans = 0;
    if (min(x, y) < 0) return 0;
    for (int i = 0; i <= x; ++i) {
        if (y == 0) {
            ans++;
            if (ans >= mod) ans -= mod;
            continue;
        }
        int s = f[i + 1 + y] * rev[i + 1] % mod;
        s *= rev[y];
        s %= mod;
        ans += s;
        if (ans >= mod) ans -= mod;
    }
    return ans;
}

