void COMinit()
{
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++)
    {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

long long COM(int n, int k)
{
    if (n < k)
        return 0;
    if (n < 0 || k < 0)
        return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll sum(int x, int y)
{
    if ((ll)x * y == 0)
        return 0;
    ll res = 0;
    for (int i = 1; i <= y; i++)
    {
        res += COM(i + 1 + x, x);
        res += MOD - COM(i, 0);
        res %= MOD;
    }
    return res;
}

