constexpr int MOD = 1000000007;

ll mpow(ll x, ll p) {
    if (p == 1) { return x % MOD; }
    if (p % 2) { return (x * mpow(x, p - 1)) % MOD; }
    ll sub = mpow(x, p / 2);
    return (sub * sub) % MOD;
}

ll f(const vll& fac, const vll& inv, int i, int j) {
    if (i == 0 || j == 0) { return 1; }
    if (i == 1 || j == 1) { return (i + j) % MOD; }
    ll ans = (fac[i + j] * inv[i]) % MOD;
    return (ans * inv[j]) % MOD;
}

