void solve(){
    ll r1,r2,c1,c2;
    cin >> r1 >> c1 >> r2 >> c2;
    mint ans=1;
    for(ll i=r1+c1; i>r1; i--){
        ans *= (mint)i;
    }
    repi(i,1,c1+1){
        ans /= (mint)i;
    }
    mint cur=ans;
    vector<mint> h(r2-r1),v(c2-c1);
    rp(i,r2-r1){
        cur*=(mint)r1+c1+1+i;
        cur/=(mint)r1+1+i;
        h[i]=cur;
    }
    cur=ans;
    rp(i,c2-c1){
        cur*=(mint)r1+c1+1+i;
        cur/=(mint)c1+1+i;
        v[i]=cur;
    }
    reverse(all(h));
    reverse(all(v));
    vector<mint> hsum(r2-r1),vsum(c2-c1);
    mint com=1;
    rp(i,r2-r1){
        com *= (mint)c2-c1+i;
        com /= (mint)i+1;
        if(i==0) hsum[0]=com;
        else hsum[i]=hsum[i-1]+com;
    }
    com=1;
    rp(i,c2-c1){
        com *= (mint)r2-r1+i;
        com /= (mint)i+1;
        if(i==0) vsum[0]=com;
        else vsum[i]=vsum[i-1]+com;
    }
    rp(i,r2-r1){
        ans += h[i]*(hsum[i]+1);
    }
    rp(i,c2-c1){
        ans += v[i]*(vsum[i]+1);
    }
    print(ans);
    return;
}
