const long MOD = 1000000007;

vector<long> fact, inv_fact;

long mult(long a, long b) {
    return (a * b) % MOD;
}

long power(long a, long b) {
    long res = 1;
    while (b > 0) {
        if (b & 1) 
            res = mult(res, a);
        a = mult(a, a);
        b /= 2;
    }
    return res;
}

long inv(long a) {
    return power(a, MOD - 2);
}

long calc_c(long n, long k) {

    while (n >= (int)fact.size()) {
        fact.push_back(fact.back() * (fact.size() + 1));
        inv_fact.push_back(inv(fact.back()));
    }

    long res = fact[n];
    res = mult(res, inv_fact[k]);
    res = mult(res, inv_fact[n - k]);
    return res;
}

long calc(long r, long c) {
    return calc_c(r + c + 2, r + 1) - 1;
}

