const int N = 2e6 + 2;
ll fact[N+1], finv[N+1], inv[N+1];

void comb_init() {
    // init
    REP(i, 2) {
        fact[i] = 1;
        finv[i] = 1;
        inv[i] = 1;
    }

    FOR(i, 2, N) {
        fact[i] = fact[i-1] * i % MOD;
        inv[i] = MOD - MOD / i * inv[MOD % i] % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}

ll comb(int n, int k) {
    if (n < k || n < 0 || k < 0) return 0;

    return (fact[n] * finv[k] % MOD) * finv[n-k] % MOD;
}


