const int MAX = 1000005;

long long fac[MAX], finv[MAX], inv[MAX];
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAX; i++){
        fac[i] = fac[i-1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod/i) % mod;
        finv[i] = finv[i-1] * inv[i] % mod;
    }
}
long long COM(int n, int k){
    if(n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}


ll g(int r, int c) {
    ll res = 0;
    for(int i=1; i<=r+1; ++i) { res += COM(i+c, i); chmod(res); }
    return res;
}


int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int r1, c1, r2, c2; cin >> r1 >> c1 >> r2 >> c2;
    COMinit();

    ll ans = 0;
    ans += g(r2, c2); chmod(ans);
    ans -= g(r2, c1-1); chmod(ans);
    ans -= g(r1-1, c2); chmod(ans);
    ans += g(r1-1, c1-1); chmod(ans);

    cout << ans << endl;

    return 0;
}

