const int MAX = 3100000;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(long n, long k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

long long Calc(long r,long c){
    long tmp = 0;
    for(int i=c+1;i<=c+1+r;i++){
        tmp += COM(i,c);
        tmp %= MOD;
    }
    return tmp;
}

int main() {
    // 前処理
    COMinit();
    long r1,c1,r2,c2;
    cin >> r1 >> c1 >> r2 >> c2;
    long a = Calc(c1-1,r1-1);
    long b = Calc(c2,r1-1);
    long c = Calc(c1-1,r2);
    long d = Calc(c2,r2);
    cout << (d - b - c + a + MOD) % MOD << endl;
}

