const int N = 1e6 + 7, MOD = 1e9 + 7;

int f[N] = { 1 }, rf[N] = { 1 };

int binpow(int x, int d) {
    int ans = 1;
    while (d) {
        if (d & 1)
            ans = ans * x % MOD;
        x = x * x % MOD;
        d >>= 1;
    }
    return ans;
}

int binom(int n, int k) {
    return f[n] * rf[k] % MOD * rf[n - k] % MOD;
}

void solve() {
    loop1(i, N - 1) {
        f[i] = f[i - 1] * i % MOD;
        rf[i] = binpow(f[i], MOD - 2);
    }
    int lef, rig, up, dwn, rev2 = binpow(2, MOD - 2);
    cin >> lef >> dwn >> rig >> up;
    int sum = binom(rig + up, rig), ans = sum;
    int dx = rig - lef + 1, dy = up - dwn + 1;
    loop1(i, dx + dy - 2) {
        if (dx > i)
            sum = (sum + binom(rig + up - i, rig - i)) % MOD;
        else
            sum = (sum - binom(rig + up - i, lef - 1) + MOD) % MOD;
        if (dy > i)
            sum = (sum + binom(rig + up - i, up - i)) % MOD;
        else
            sum = (sum - binom(rig + up - i, dwn - 1) + MOD) % MOD;
        sum = sum * rev2 % MOD;
        ans = (ans + sum) % MOD;
    }
    cout << ans;
}

