typedef long long ll;
const ll mod=1e9+7;
ll pow(ll x,ll y){
  if(y==0) return 1;
  ll res=pow(x,y/2);
  res*=res;
  res%=mod;
  if(y%2==1) res*=x;
  return res%mod;
}
ll gyaku(ll x){
  return pow(x,mod-2);
}
vector<ll> frac,gfrac;
void set_frac(ll n){
  frac.push_back(1);
  gfrac.push_back(1);
  for(ll i=1;i<=n;i++){
    frac.push_back(frac[i-1]*i%mod);
    gfrac.push_back(gyaku(frac[i]));
  }
}
ll nCr(ll n,ll r){
  ll res=frac[n]*gfrac[r]%mod;
  res*=gfrac[n-r];
  return res%mod;
}

ll solve(vector<ll> vec,ll H,ll W){
  ll res=0;
  ll now_val=W;
  ll ki=1;
  for(ll i=vec.size()-1;i>=0;i--){
    res+=now_val*vec[i];
    res%=mod;

    now_val+=nCr(W+ki,W-1);
    now_val%=mod;
    ki++;
  }
  for(int i=0;i<vec.size();i++){
    res+=vec[i];
    res%=mod;
  }
  return res;
}

int main(){
  ll r1,c1,r2,c2;
  cin>>r1>>c1>>r2>>c2;
  ll H=r2-r1,W=c2-c1;
  set_frac(r2+c2+100);
  ll ans=nCr(r1+c1,r1);

  vector<ll> v1,v2;
  for(int i=r1+1;i<=r2;i++) v1.push_back(nCr(c1+i,c1));
  for(int i=c1+1;i<=c2;i++) v2.push_back(nCr(r1+i,r1));
  ans+=solve(v1,H,W);
  ans%=mod;
  ans+=solve(v2,W,H);
  ans%=mod;
  cout<<ans<<endl;
}

