const int maxn = 2000000 + 10;
const ll mod = 1000000000 + 7;
ll quick(ll a, ll n) {
    ll ans = 1;
    for (; n; n >>= 1, a = a * a % mod) {
        if (n & 1) ans = ans * a % mod;
    }
    return ans;
}
ll fac[maxn], inv[maxn], pre[maxn];
void init() {
    fac[0] = inv[0] = 1;
    for (ll i = 1; i < maxn; i++) {
        fac[i] = fac[i - 1] * i % mod;
    }
    for (ll i = 1; i < maxn; i++) {
        pre[i] = (pre[i] + fac[i - 1]) % mod;
    }
    inv[maxn - 1] = quick(fac[maxn - 1], mod - 2);
    for (ll i = maxn - 2; i >= 1; i--) {
        inv[i] = inv[i + 1] * (i + 1) % mod;
    }
}
ll r1, c1, r2, c2;

ll fun(ll k, ll n) {
    ll m = k;
    n = n + k + 1;
    return fac[n] * inv[n - m] % mod * inv[m] % mod;

}

int main() {
    init();
    cin >> r1 >> c1 >> r2 >> c2;

    ll ans = 0;
    for (ll i = c1; i <= c2; i++) {
        ans += (fun(r2, i) - fun(r1 - 1, i) + mod) % mod;
        ans %= mod;
    }
    cout << ans << endl;
    return 0;
}

