lint fac[MAXN];
lint inv[MAXN];

int r1,c1,r2,c2;

lint Ans1,Ans2;

lint qpow(lint A,int B)
{

	lint res=1;

	while(B>0)
	{
		if(B&1) (res*=A)%=Mod;
		(A*=A)%=Mod;
		B>>=1;
	}

	return res;

}

lint C(int A,int B)
{

	return ( A<B ? 0 : (((fac[A]*inv[B])%Mod)*inv[A-B])%Mod );

}

