using ll = long long;
const ll MOD = 1000000007;

ll factr[2000010];

ll modpow(ll x, ll y) {
	x %= MOD;
	ll ans = 1;
	while (y) {
		if (y & 1)ans *= x;
		y /= 2;
		x *= x;
		ans %= MOD;
		x %= MOD;
	}
	return ans;
}

ll moddiv(ll a, ll b) {
	return a * modpow(b, MOD - 2) % MOD;
}

ll solve(ll X, ll Y) {
	ll ans = 0;

	for (ll i = 0;i <= X;i++) {
		ans += moddiv(moddiv(factr[i + Y + 1], factr[i + 1]), factr[Y]);
		ans %= MOD;
	}
	return ans;
}

