	for (ll i = 1;i < 2000010;i++)factr[i] = factr[i - 1] * i % MOD;

	ll ans = solve(r2, c2) - solve(r2, c1 - 1) - solve(r1 - 1, c2) + solve(r1 - 1, c1 - 1);
	ans %= MOD;
	if (ans < 0)ans += MOD;

	cout << ans << endl;
}

