}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
ll MOD = 1000000007;

ll factorial[3000002];
ll iFactorial[3000002];

ll bigMode( ll base, ll b ){
    ll ans = 1;
    while( b ){
        if( b%2 == 1 ){
            ans = (ans*base)%MOD;
        }
        base = (base*base)%MOD;
        b /= 2;
    }
    return ans%MOD;
}

void fun(  ){
    factorial[0] = 1;
    iFactorial[0] = 1;
    for( int i = 1; i < 3000002; i++ ){
        factorial[i] = (i*factorial[i-1])%MOD;
        iFactorial[i] = (iFactorial[i-1]*bigMode(i, MOD-2))%MOD;
    }
}

int main(){
    fun();
    ll r1,r2,c1,c2;
    while( cin >> r1 >> c1 >> r2 >> c2 ){
        ll ans = 0;
        for( int i = r1 ; i <= r2; i++ ){
            ll r = i+c2+1;
            ll c = c2;
            ///if( r < c )swap( r,c );
            ll tempAns = factorial[r]%MOD;
            tempAns = (tempAns*iFactorial[c])%MOD;
            tempAns = (tempAns*iFactorial[r-c])%MOD;
            r = i+c1;
            c = c1-1;
            ///if( r < c )swap(r,c);
            ll tempAns1;
            tempAns1 = factorial[r];
            tempAns1 = (tempAns1*iFactorial[c])%MOD;
            tempAns1 = (tempAns1*iFactorial[r-c])%MOD;
            tempAns = tempAns - tempAns1;
            if( tempAns < 0 ){
                tempAns = (tempAns+MOD)%MOD;
            }
            ans = (ans+tempAns)%MOD;
        }
        cout << ans%MOD << endl;
    }
}
