class Combination {
	int MAX;
	int mod;
	long long *kai;
	long long *kai_inv;
	long long modpow(long long a, long long n) {
		long long res = 1;
		while (n > 0) {
			if (n & 1) res = res * a % mod;
			a = a * a % mod;
			n >>= 1;
		}
		return res;
	}
	long long modinv(long long a) {
		return modpow(a, mod - 2);
	}
	void Init() {
		for (int i = 1; i < MAX; i++) {
			kai[i] = kai[i - 1] * i;
			kai[i] %= mod;
			kai_inv[i] = modinv(kai[i]);
		}
	}
public:
	Combination(int max, int mod) :mod(mod), MAX(max + 5) {
		kai = new long long[max + 5]{ 1 };
		kai_inv = new long long[max + 5]{ 1 };
		Init();
	}
	~Combination() {
		delete[] kai;
	}
	long long operator()(int n, int k) {
		if (n < 0 || k < 0 || n < k)return 0;
		long long res = kai[n];
		res *= kai_inv[k];
		res %= mod;
		res *= kai_inv[n - k];
		res %= mod;
		//printf("%d C %d = %d\n", n, k, res);
		return res;
	}
};
