struct mint {
  int val;
  mint(int v = 0) noexcept : val(v % MOD) {
    if (val < 0) val += MOD;
  }
  int getMOD() { return MOD; }
  mint operator - () const noexcept {
    return val ? MOD - val : 0;
  }
  mint operator + (const mint& r) const noexcept { return mint(*this) += r; }
  mint operator - (const mint& r) const noexcept { return mint(*this) -= r; }
  mint operator * (const mint& r) const noexcept { return mint(*this) *= r; }
  mint operator / (const mint& r) const noexcept { return mint(*this) /= r; }
  mint& operator += (const mint& r) noexcept {
    val += r.val;
    if (val >= MOD) val -= MOD;
    return *this;
  }
  mint& operator -= (const mint& r) noexcept {
    val -= r.val;
    if (val < 0) val += MOD;
    return *this;
  }
  mint& operator *= (const mint& r) noexcept {
    val = val * r.val % MOD;
    return *this;
  }
  mint& operator /= (const mint& r) noexcept {
    int a = r.val, b = MOD, u = 1, v = 0;
    while (b) {
      int t = a / b;
      a -= t * b; swap(a, b);
      u -= t * v; swap(u, v);
    }
    val = val * u % MOD;
    if (val < 0) val += MOD;
    return *this;
  }
  bool operator == (const mint& r) const noexcept {
    return this->val == r.val;
  }
  bool operator != (const mint& r) const noexcept {
    return this->val != r.val;
  }
  friend ostream& operator << (ostream &os, const mint& x) noexcept {
    return os << x.val;
  }
  friend istream& operator >> (istream &is, mint& x) noexcept {
    return is >> x.val;
  }
  friend mint powMod(const mint &a, int n) noexcept {
    if (n == 0) return 1;
    auto t = powMod(a, n / 2);
    t = t * t;
    if (n & 1) t = t * a;
    return t;
  }
};

struct combination {
  vector<mint> fac, finv, inv;

  combination(int n) {
    fac  = vector<mint>(n, 1);
    finv = vector<mint>(n, 1);
    inv  = vector<mint>(n, 1);
    for (int i = 2; i < n; i++) {
      fac[i] = fac[i - 1] * i;
      inv[i] = - inv[MOD % i] * (MOD / i);
      finv[i] = finv[i - 1] * inv[i];
    }
  }

  mint operator()(int n, int k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * finv[k] * finv[n - k];
  }
}comb(2000000);

