using namespace std;

typedef long long ll;
const int N = 2000006;
const ll MOD = 1000000007;

ll fact[N];
ll infact[N];

ll powermod(ll a,ll b){
	ll ret = 1;
	while(b){
		if(b&1){
			ret *= a;
			ret %= MOD;
		}
		b >>= 1;
		a *= a;
		a %= MOD;
	}
	return ret;
}

ll calc(ll n, ll m){
	ll ret = 0;
	for(int i=2;i<=n;i++){
		ll hano = m*fact[m+i-1] - fact[m] * fact[i];
		hano %= MOD;
		hano += MOD;
		hano %= MOD;
		hano *= infact[m];
		hano %= MOD;
		hano *= infact[i];
		hano %= MOD;
		ret += hano;
		ret %= MOD;
	}
	return ret;
}

int main(){
	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

	fact[0] = 1;
	infact[0] = powermod(1,MOD-2);

	for(int i=1;i<N;i++){
		fact[i] = fact[i-1] * i;
		fact[i] %= MOD;
		infact[i] = powermod(fact[i],MOD-2);
	}

	int r,c,rr,cc;
	cin>>r>>c>>rr>>cc;
	r++;c++;
	rr++;cc++;
	ll ans = calc(rr,cc);
	ans -= calc(rr,c-1);
	ans -= calc(r-1,cc);
	ans += calc(r-1,c-1);
	ans %= MOD;
	ans += MOD;
	ans %= MOD;
	cout<<ans;

	return 0;
}

