// 10進法でn桁の整数xに対して、大きい方の位から、その位の1桁の数字を
//収納した長さnのベクトルを返す
// 0に対しては{0}を返す
//検証済み
vector<ll> keta(ll x) {
	if(x == 0) return {0};
	ll n = log10(x) + 1;  // xの桁数
	vll w(n, 0);
	for(ll i = 0; i < n; i++) {
		ll p;
		p = x % 10;
		x = x / 10;
		w[n - 1 - i] = p;
	}
	return w;
}

