int pw(int base, int power)
{
        int res = 1;
        while (power) {
                if (power & 1)
                        (res *= base) %= mod;
                (base *= base) %= mod;
                power >>= 1;
        }
        return res;
}

int C(int n, int k) { return fac[n] * ifac[k] % mod * ifac[n - k] % mod; }

