        inv[i] =  - inv[mod%i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}

long long nCk(int n, int k){
    if (n < k || n < 0 || k < 0) return 0;
    return fact[n] * (finv[k] * finv[n - k] % mod) % mod;
}

int g(int r, int c) {
  int ret = 0;
  rep2(i, 1, r+2) addm(ret, nCk(i+c, i));
  return ret;
}

