int revfact[FACTSIZE];

int binpow(int a, int b, int mo) {
  if (a >= mo) a %= mo;
  int ans = 1;
  do {
    if (b & 1) ans = 1ll * ans * a % mo;
    a = 1ll * a * a % mo;
  } while (b >>= 1);
  return ans;
}
int modInv(int p) {
  if (p >= MOD) p %= MOD;
  return binpow(p, MOD - 2, MOD);
}
int ncr(int n, int r) {
  if (n < r) return 0;
  int rs = fact[n] * revfact[r];
  if (rs >= MOD) rs %= MOD;
  rs *= revfact[n - r];
  if (rs >= MOD) rs %= MOD;
  return rs;
}
void init() {
  fact[0] = 1, revfact[0] = 1;
  for (int i = 1; i < FACTSIZE; ++i) {
    fact[i] = fact[i - 1] * i % MOD;
    revfact[i] = binpow(fact[i], MOD - 2, MOD);
  }
}

