class factorial_runtime
{
    const int mod;
    int n;
    std::vector<int> fact;
public:
    factorial_runtime() : mod(modint_runtime::mod()), n{1}, fact{1} {}
    void reserve(int m)
    {
        if(m < n) return;
        m = 1 << (32 - __builtin_clz(m));
        fact.resize(m);
        for(int i = n; i < m; ++i) fact[i] = fact[i - 1] * i % mod;
        n = m;
    }
    modint_runtime operator()(const int x) noexcept { reserve(x); return x < 0 ? 0 : fact[x]; }
};

