    ll S = 1, ans = S;
    for(int i=1;i<=x;i++){
        S = (S * 2 - C(n,k) + mod) % mod, n++;
        S = (S + C(n,k+1)) % mod, k++;
//        cout<<n<<' '<<k<<' '<<S<<endl;
        ans += S;
    }
    for(int i=1;i<=y;i++){
        S = (S * 2 - C(n,k) + mod) % mod, n++;
//        cout<<n<<' '<<k<<' '<<S<<endl;
        ans += S;
    }
    n = 0, k = 0, S = 1, ans -= S;
    for(int i=1;i<=y;i++){
        S = (S * 2 - C(n,k) + mod) % mod, n++;
//        cout<<n<<' '<<k<<' '<<S<<endl;
        ans -= S;
