constexpr int64_t mod = 1000000007;
constexpr int64_t MAX = 2000005;

int64_t modInverse(int64_t a) {
    int64_t m = mod;
    int64_t m0 = m;
    int64_t y = 0, x = 1;

    if (m == 1)
        return 0;

    while (a > 1) {
        // q is quotient
        int64_t q = a / m;
        int64_t t = m;

        // m is remainder now, process same as
        // Euclid's algo
        m = a % m, a = t;
        t = y;

        // Update y and x
        y = x - q * y;
        x = t;
    }

    // Make x positive
    if (x < 0)
        x += m0;

    return x;
}

int64_t F[MAX];
int64_t tP[MAX];
int64_t iF[MAX];

int64_t P(int64_t x, int64_t y) {
    int64_t sum = 0;
    for (int yy=0;yy<=y;++yy) {
        sum = (sum + F[x+yy+1]*iF[x+yy+1-x]%mod*iF[x]%mod) % mod;
    }
    return sum;
}

