ll qexp(ll A, ll B, ll M) {
	if (B == 0) return 1; 
	ll half = qexp(A, B/2, M); 
	half = qmult(half, half, M);
	half %= M;
	if (B%2==1) half *= A%M;
	return half%M;
}

