int fact[N], ifact[N];

int pwr(int a,int b) {
	int ans = 1;
	while(b) {
		if(b & 1) {
			ans = (ans * 1LL * a) % mod;
		}
		a = (a * 1LL * a) % mod;
		b >>= 1;
	}
	return ans;
}

int ncr(int a,int b) {
	if(a < b || b < 0) return 0;
	int ans = (fact[a] * 1LL * ifact[b]) % mod;
	return (ans * 1LL * ifact[a - b]) % mod;
}

int f(int r,int c) {
	if(r < 0 || c < 0) return 0;
	int ans = 0;
	for(int i = 0; i <= c; i++) {
		ans += ncr(r + 1 + i, i + 1);
		ans %= mod;
	}
	return ans;
}

