long long pow(long long a, long long b, long long P) {
    long long res = 1;
    a = a % P;
    while (b) {
        if (b & 1) {
            res = res * a % P;
        }
        a = a * a % P;
        b >>= 1;
    }
    return res;
}

int C(int m, int n, int P) {
    long long res = 1;
    for (int i = 0; i < m; ++i) {
        res = res * (n - i) % P;
    }
    for (int i = 2; i <= m; ++i) {
        res = res * pow(i, P - 2, P) % P;
    }
    return (int)res;
}

