int64_t negmod(int64_t a, int64_t n= Nmod){
  int64_t ans= a%n;
  if(ans<0) ans+= n;

  return ans;
}

int64_t fac(int64_t a, int64_t p= Nmod){
  int64_t ans= 1;
  for(auto i=1; i<=a; i++){
    ans= (ans*i)% p;
  }

  return ans;
}

int64_t invmod(int64_t a, int64_t p= Nmod){ // a^{p-1} mod p =1 を利用してinv(a)= a^{p-2} を求める
  int64_t d= p-2;
  int64_t ans= 1;
  int64_t tmp= a;
  while(d > 0){
    if(d%2==1){
      ans= (ans*tmp)% p;
    }
    d/= 2;
    tmp= (tmp*tmp)% p;
  }

  return ans;
}

int64_t choose(int64_t n, int64_t k, int64_t p= Nmod){
  if(n < 0 || min(k,n-k) < 0){
    return 0;
  }
  else{
    return fac(n)*(invmod(fac(k))* invmod(fac(n-k))% p) % p;
  }
}

