long pow(long x, long y, long mod) {
    long ret = 1;
    long tmp = x;
    while (y) {
        if (y % 2) ret = ret * tmp % mod;
        y /= 2;
        tmp = tmp * tmp % mod;
    }
    return ret;
}

long inverse(long v, long mod) {
    return pow(v, mod - 2, mod);
}

long factorial(long x, long mod) {
    long ret = 1;
    for (long i = 1; i <= x; i++) {
        ret = ret * i % mod;
    }
    return ret;
}

long combination(long x, long y, long mod) {
    long ret = factorial(x, mod);
    ret = ret * inverse(factorial(y, mod), mod) % mod;
    ret = ret * inverse(factorial(x - y, mod), mod) % mod;
    return ret;
}



