// [C++17] template <auto N>
template <typename T, T N>
class Modulo {
 public:
  using Type = decltype(N);
  Modulo (Type n = 0) : number_((N + n) % N) {}
  auto operator ~ () const {
    // N が素数であり、かつ
    // number_ が N と互いに素である場合に限る
    return power(*this, N - 2);
  }
  auto operator - () const {
    return Modulo(-number_);
  }
  auto & operator += (const Modulo & m) {
    number_ = (number_ + m.number_) % N;
    return *this;
  }
  auto & operator *= (const Modulo & m) {
    number_ = (number_ * m.number_) % N;
    return *this;
  }
  auto & operator -= (const Modulo & m) {
    return *this += -m;
  }
  friend auto operator + (Modulo lhs, const Modulo & rhs) {
    return lhs += rhs;
  }
  friend auto operator * (Modulo lhs, const Modulo & rhs) {
    return lhs *= rhs;
  }
  friend auto operator - (Modulo lhs, const Modulo & rhs) {
    return lhs -= rhs;
