};

template <typename T>
auto
power (
    T   base,
    int exponent)
{
    decltype(base) result = 1;

    for (; exponent; exponent >>= 1) {
      if ( exponent & 1 ) {
        result *= base;
      }
      base *= base;
    }
    return result;
}

template <typename T, std::size_t INPUT_MAX>
auto
path_count (
    std::size_t r,
    std::size_t c)
{
    static std::array<T, INPUT_MAX + 1> facs;
    static std::array<T, INPUT_MAX + 1> invs;
    static bool ready = false;

    if ( !ready ) {
      const auto N = INPUT_MAX;
      facs[0] = 1;
      for (auto i = 1; i <= N; ++i) {
        facs[i] = facs[i - 1] * i;
      }
      invs[N] = ~facs[N];
      for (auto i = N; 1 <= i; --i) {
        invs[i - 1] = invs[i] * i;
      }
      ready = true;
    }

    return facs[r+c] * invs[r] * invs[c];
}

int
main ()
{
    using Number = Modulo<long long, 1'000'000'007ll>;
    const auto INPUT_MAX = 1'000'000;
    auto f = path_count<Number, INPUT_MAX>;

    int r1, r2, c1, c2;
    std::cin >> r1 >> c1 >> r2 >> c2;

    Number answer;
    for (int r = r1; r <= r2; ++r) {
      for (int c = c1; c <= c2; ++c) {
        answer += f(r, c);
      }
    }
    std::cout << answer << std::endl;
}

