ll gcd(ll a,ll b){ // 高速ユークリッド互除法
    if(a<0) a = -1*a;
    if(b<0) b = -1*b;
    if(a==0) return b;
    if(b==0) return a;
    if(a==b) return a;
    ll c;
    if(a<b){
        c = b-(b/a)*a;
        if(c<a/2) return gcd(a,c);
        else return gcd(a,c-a);
    } else{
        c = a-(a/b)*b;
        if(c<b/2) return gcd(c,b);
        else return gcd(c-b,b);
    }
}

ll binary_method(ll a,ll b,ll m){
    // a^b mod m
    if(b==0) return 1;
    ll ans=1;
    ll ori_b = b;
    ll b_length = 0;
    while(b!=0){
        b = b/2;
        b_length++;
    }

    for(int i=b_length-1;i>-1;i--){
        if((ori_b>>i)&1) ans = (((ans * a) % m) * ans)%m;
        else ans = (ans * ans) % m;
        // cout<<ans<<endl;
    }
    return ans;
}

ll inv(ll a, ll m){
    // a^{-1} mod m, m : 素数
    // cout<<a<<" "<<binary_method(a, m-1, m)<<endl;
    return binary_method(a, m-2, m);
}

ll factorial(ll a, ll m){
    // a! mod m
    if(a<0){
        std::cout<<"factorial error. negative input"<<std::endl;
        return 0;
    }
    ll ans=1;
    for(int i=1;i<a+1;i++){
        ans = (ans * i) % m;
    }
    return ans;
}

ll comb(ll a,ll b,ll m){
    // aCb mod m 
    if(a<0 || b<0 || a<b){
        std::cout<<"combination error."<<std::endl;
    }

    ll A = factorial(a,m);
    ll B = inv(factorial(b,m),m);
    ll C = inv(factorial(a-b,m),m);
    return (((A * B) % m) * C) % m;
}

