template<Int N>
struct Factorial {
    static_assert(N >= 1, "");

    static ModInt fac(Int n) {
        static decltype(auto) table = fac_table();
        return table[n];
    }

    static ModInt ifac(Int n) {
        static decltype(auto) table = ifac_table();
        return table[n];
    }

    static ModInt comb(Int n, Int r) {
        if(n < 0 || r < 0 || n < r) return 0;
        return fac(n) * ifac(n-r) * ifac(r);
    }

private:
    static const ModInt (&fac_table())[N] {
        static ModInt table[N];
        table[0] = 1;
        FOR(i, 1, N) {
            table[i] = i * table[i-1];
        }
        return table;
    }

    static const ModInt (&ifac_table())[N] {
        static ModInt table[N];
        table[N-1] = fac(N-1).inv();
        for(Int i = N-2; i >= 0; --i) {
            table[i] = (i+1) * table[i+1];
        }
        return table;
    }
};

void solve() {
    Int y1 = RD();
    Int x1 = RD();
    Int y2 = RD();
    Int x2 = RD();

    using Fac = Factorial<2'000'010>;

    ModInt ans = 0;
    FOR(y, y1, y2+1) {
        ans += Fac::comb(x2+y+1,x2) - Fac::comb(x1-1+y+1,x1-1);
    }

    PRINTLN(ans);
}

signed main() {
    Int T = 1; //RD();
    LOOP(T) {
        solve();
    }

    EXIT();
}

