template <size_t N, int M>
struct Factorial {
    uint_fast64_t fact_[N + 1];

    constexpr inline Factorial() : fact_{1} {
        for (int_fast64_t i = 1; i <= N; ++i) fact_[i] = (fact_[i - 1] * i) % M;
    }

    constexpr inline Mint operator[] (size_t pos) const { return fact_[pos]; }
};

template <size_t N, int M>
struct InvFact {
    uint_fast64_t inv_[N + 1];
    uint_fast64_t finv_[N + 1];

    constexpr inline InvFact() : inv_{0, 1}, finv_{1, 1} {
        for (int_fast64_t i = 2; i <= N; ++i) {
            inv_[i] = M - inv_[M % i] * (M / i) % M;
            finv_[i] = finv_[i - 1] * inv_[i] % M;
        }
    }

    constexpr inline Mint operator[] (size_t pos) const { return finv_[pos]; }
};

#ifdef constexpr
#undef constexpr
#endif

Factorial<intmax_t(2e6) + 10, MOD> fact;
InvFact<intmax_t(2e6) + 10, MOD> finv;

inline Mint nCr(int n, int r) {
    if (n < r) return 0;
    if (n < 0 || r < 0) return 0;
    return fact[n] * (finv[r] * finv[n - r]);
}

inline Mint nPr(int n, int r) {
    if (n < r) return 0;
    if (n < 0 || r < 0) return 0;
    return fact[n] * finv[r];
}
