int inv[MX], f[MX], invf[MX];
void calc(){
	inv[0] = inv[1] = f[0] = f[1] = invf[0] = invf[1] = 1;
	for (int i = 2; i < MX; i++){
		inv[i] = mod - mod / i * (ll)inv[mod % i] % mod;
		f[i] = (ll)f[i - 1] * i % mod;
		invf[i] = (ll)invf[i - 1] * inv[i] % mod;
	}
}
inline ll comb(ll n, ll k){
	if(n < k || k < 0) return 0;
	return f[n] * (ll)invf[k] % mod * invf[n - k] % mod;
}
