			if(nl > lo) prev = (prev + mod - comb(s - 1, lo)) % mod;
			else prev = (prev + comb(s - 1, lo - 1)) % mod;

			if(nr > hi) prev = (prev + comb(s - 1, hi + 1)) % mod;
			else prev = (prev + mod - comb(s - 1, hi)) % mod;

			lo = nl; hi = nr;
			ans += prev;
		}
	}
