// mod. m での a の逆元 a^{-1} を計算する
ll modinv(ll a, ll m) {
  ll b = m, u = 1, v = 0;
  while (b) {
    ll t = a / b;
    a -= t * b; swap(a, b);
    u -= t * v; swap(u, v);
  }
  u %= m;
  if (u < 0) u += m;
  return u;
}
ll fact[2000020];

ll comb(ll n, ll r) {
  ll res = 1;
  res *= fact[n];
  res %= DVSR;
  res *= modinv(fact[n-r], DVSR);
  res %= DVSR;
  res *= modinv(fact[r], DVSR);
  res %= DVSR;
  return res;
}

