long long modPow(long long a, long long n,long long MOD) {
    long long ret = 1;
    while (n > 0) {
        if (n & 1) ret = ret * a % MOD;  // n の最下位bitが 1 ならば x^(2^i) をかける
        a = a * a % MOD;
        n >>= 1;  // n を1bit 左にずらす
    }
    return ret;
}


