ll record[N];

ll pow(ll a,ll b){
	ll res = 1;
	while(b){
		if(b&1)
			res = (res * a) % MOD;
		a = (a * a) % MOD;
		b >>= 1;
	}
	return res;
}

inline ll A(ll a){
	return record[a];
}

ll C(ll a,ll b){
	ll res = (A(a) * pow((A(a-b)*A(b))%MOD,MOD-2))%MOD;
	return res;
}



