using namespace std;
typedef long long ll;
const int MOD = 1e9 + 7;
const int N = 1e6 + 5;
ll fact[2 * N];

ll binpow(ll a, ll b, ll m) {
    a %= m;
    ll res = 1;
    while (b > 0) {
        if (b & 1)
            res = res * a % m;
        a = a * a % m;
        b >>= 1;
    }
    return res % m;
}

ll inverse(ll x) {
	return binpow(x, MOD - 2, MOD);
}

ll cc(ll n, ll k) {
	return fact[n] * inverse(fact[k]) % MOD * inverse(fact[n - k]) % MOD;
}

