template<typename T>
class combnk_mod{
private:
    T _maxn, _p;
    vector<T> x;
    vector<T> y;
public:
    combnk_mod(T maxn, T p){
        _maxn = maxn;
        _p = p;
        x.push_back(1);
        y.push_back(1);
        for (T i = 1; i <= _maxn; i++){
            x.push_back(x[i - 1] * modpow(i, _p - 2, _p) % _p);
            y.push_back(y[i - 1] * i % _p);
        }
    }

    T combnk(T n, T k){
        if (n < k) return 0;
        return (x[n - k] * x[k] % _p) * y[n] % _p;
    }
};

int main(){
    ll r1, r2, c1, c2;
    cin >> r1 >> c1 >> r2 >> c2;
    ll MOD = 1e9 + 7;
    ll ans = 0;
    combnk_mod<ll> C(r2 + c2, MOD);
    for (ll r = r1; r <= r2; r++){
        for (ll c = c1; c <= c2; c++){
            ans += C.combnk(r + c, r);
            ans %= MOD;
        }
    }
    cout << ans << endl;
}

