#define ll long long

ll mod = 1e9+7;

ll modpower(ll a, ll r){ //a^r
    ll x = 1;
    while (r > 0) {
        if (r & 1) x = x * a % mod;
        r >>= 1;
        a = a * a % mod;
    }
    return x;
}

ll modinv(ll a){
    return modpower(a, mod-2);
}

vector<ll> fact;
vector<ll> invfact;

void set_fact(int n){
    fact.resize(n+1, 1);
    invfact.resize(n+1, 1);
    for (int i = 2; i <= n; i++) {
        fact[i] = fact[i-1] * i % mod;
    }
    invfact[n] = modinv(fact[n]);
    for (int i = n-1; i >= 2; i--) {
        invfact[i] = invfact[i+1] * (i+1) % mod;
    }
    return;
}

ll comb(int n, int k) {
    if (k > n || k < 0) return 0;
    if (k == n || k == 0) return 1;
    return fact[n] * invfact[n-k] % mod * invfact[k] % mod;
}

int main(){
    int r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;
    ll ans = 0;
    set_fact(2000000);
    ans = comb(r1+c1, c1);
    if (r2 != r1 || c2 != c1) {
        ans += comb(r2+c2, c2);
    }
    if (r2-r1 > 0 && c2-c1 > 0) {
        ans += comb(r2+c2, c2);
    }
    ans %= mod;
    for (int i = r2-1; i > r1; i--) {
        ans += comb(i+c2, c2);
        ans %= mod;
    }
    for (int i = c2-1; i > c1; i--) {
        ans += comb(i+r2, r2);
        ans %= mod;
    }
    cout << ans%mod << endl;
    return 0;
}

