		if ((this->x += MOD-a.x) >= MOD) this->x -= MOD;
		return *this;
	}
	constexpr mint& operator*=(const mint& a) {
		(this->x *= a.x) %= MOD;
		return *this;
	}
	constexpr mint operator+(const mint& a) const {
		mint res(*this);
		return res+=a;
	}
	constexpr mint operator-(const mint& a) const {
		mint res(*this);
		return res-=a;
	}
	constexpr mint operator*(const mint& a) const {
		mint res(*this);
		return res*=a;
	}
	constexpr mint pow(LL t) const {
		if (!t) return 1;
		mint a = pow(t>>1);
		a *= a;
		if (t&1) a *= *this;
		return a;
	}

	// for prime MOD
	constexpr mint inv() const {
		return pow(MOD-2);
	}
	constexpr mint& operator/=(const mint& a) {
		return (*this) *= a.inv();
	}
	constexpr mint operator/(const mint& a) const {
		mint res(*this);
		return res/=a;
	}

	constexpr bool operator==(const mint& a) const {
		return this->x == a.x;
	}
	constexpr bool operator!=(const mint& a) const {
		return this->x != a.x;
	}
	constexpr bool operator<(const mint& a) const {
		return this->x < a.x;
	}

	friend istream& operator>>(istream& is, mint& m) {
