long long power(long long x, long long y) {
    long long res = 1;
    x = x % MOD;

    if (x == 0) return 0;
    while (y > 0) {
        if (y & 1) res = (res*x) % MOD;
        y = y >> 1;
        x = (x*x) % MOD;
    }
    return res%MOD;
}

long long C(long long n, long long r) {
  return (fac[n]*power(fac[r]*fac[n-r],MOD-2))%MOD;
}

long long line(long long x, long long y) {
  return C(x+y+1,x);
}

long long rect(long long x, long long y) {
  long long ans = 0;
  for (long long i = 0; i <= y; i++) {
    ans += line(x,i);
    ans %= MOD;
  }
  return ans;
}

