const int MOD = 1e9 + 7;
const int MX = 2e6 + 5;

LL expo(LL a, LL x) {
	if(x == 0) {
		return 1;
	}
	LL ret = expo(a, x/2);
	ret = (ret * ret)%MOD;
	if(x%2 != 0) {
		ret = (ret * (a%MOD))%MOD; 
	}
	return ret;
}

LL fact[MX], ifact[MX];
void aux() {
	fact[0] = 1;
	ifact[0] = 1;
	for(int i=1;i<MX;i++) {
		fact[i] = (fact[i-1] * i)%MOD;
		ifact[i] = expo(fact[i], MOD-2);
	}
}

LL ncr(int n, int r) {
	if(r > n || r < 0) return 0;
	LL ret = ((fact[n] * ifact[n-r])%MOD * ifact[r])%MOD;
	return ret;
}

LL calc(int r, int c) {
	LL ret = 0;
	for(int i=0;i<=r;i++) {
		ret = (ret + ncr(i + 1 + c, c))%MOD;
	}
	return ret;
}

