	ios::sync_with_stdio(false);

	ll r1, c1, r2, c2;
	cin >> r1 >> c1 >> r2 >> c2;

	ll mod = rll::default_mod_;
	rll res(0LL);
	res = rccll(r2 + c2 + 2LL, mod).calculate(c2 + 1LL) - r2 - c2 - 2LL;
	if (r1 > 1) {
		res -= rccll((r1 - 1LL) + c2 + 2LL, mod).calculate(c2 + 1LL) - (r1 - 1LL) - c2 - 2LL;
	}
	if (c1 > 1) {
		res -= rccll(r2 + (c1 - 1LL) + 2LL, mod).calculate(r2 + 1LL) - r2 - (c1 - 1LL) - 2LL;
	}
	if (r1 > 1 && c1 > 1) {
		res += rccll((r1 - 1LL) + (c1 - 1LL) + 2LL, mod).calculate((r1 - 1LL) + 1) - (r1 - 1LL) - (c1 - 1LL) - 2LL;
	}

	cout << res << endl;

	return 0;
}

