//ax + by = gcd(a, b) = d
// 扩展欧几里德算法
/**
 *	a*x + b*y = 1
 *	如果ab互质，有解
 *	x就是a关于b的逆元
 *	y就是b关于a的逆元
 *	 
 *	证明： 
 *		a*x % b + b*y % b = 1 % b
 *		a*x % b = 1 % b
 *		a*x = 1 (mod b)
 */
inline void ex_gcd(SLL a, SLL b, SLL &x, SLL &y, SLL &d){
    if (!b) {d = a, x = 1, y = 0;}
    else{
        ex_gcd(b, a % b, y, x, d);
        y -= x * (a / b);
    }
}

// 求a关于p的逆元，如果不存在，返回-1 
// a与p互质，逆元才存在 
inline SLL inv_mod(SLL a, SLL p = mod){
    SLL d, x, y;
    ex_gcd(a, p, x, y, d);
    return d == 1 ? (x % p + p) % p : -1;
}

inline SLL comb_mod(SLL m, SLL n) {
	SLL ret;

	if(m > n) swap(m, n);

	ret = (fac[n] * inv_mod(fac[m], mod)) % mod;
	ret = (ret * inv_mod(fac[n - m], mod)) % mod;

	return ret;
}

SLL compute_mod(SLL x, SLL y) {
	SLL ret = 0;

	Rep(i, y) {
		ret = (ret + comb_mod(i + 1, x + i)) % mod;
		//cout << ret << endl;
	}
	return ret;
}

