const ll MOD = 1e9 + 7;

// return a^b O(log b)
template<typename T>
T mypow(T a, T b){
    if (b == 0)
        return 1;
    T tmp = mypow(a, b / 2);
    if (b % 2)
        return (((tmp * tmp) % MOD) * a) % MOD;
    else
        return (tmp * tmp) % MOD;
}
// return nCk 前処理 O(N) + query あたり O(1)
static bool init = false;
ll cb_res = 1;
const ll M = 1e6 + 10;
vll frc(M + 1, 1), inv(M + 1, 1);
long long comb(int n, int k){
    if(!init){
        init = true;
        REP(i, M){
            frc[i + 1] = (frc[i] * (i + 1)) % MOD;
            inv[i + 1] = mypow(frc[i + 1], MOD - 2);
        }
    }
    if (k < 0 || n < k) return 0;
    cb_res = (((frc[n] * inv[k]) % MOD) * inv[n - k]) % MOD;
    return cb_res;
}

