const int mod=1e9+7;
const int N=1e6+6;
ll r1,c1,r2,c2;
ll fac[N],infac[N];
ll sq(ll a){
	return (a*a)%mod;
}
ll pw(ll a,ll b){
	if(b==0)return 1;
	if(b==1)return a%mod;
	if(b&1) return (a*sq(pw(a,b>>1)))%mod;
	return sq(pw(a,b>>1))%mod;
}
ll ncr(ll n,ll r){
	if(n==r)return 1;
	if(n<r)return 0;
	ll res=fac[n];
	res*=infac[r];
	res%=mod;
	res*=infac[n-r];
	res%=mod;
	return res;
}
int main(){
	infac[1]=infac[0]=fac[0]=fac[1]=1;
	for(int i=1;i<N;i++){
		fac[i]=fac[i-1]*i;
		fac[i]%=mod;
		infac[i]=pw(fac[i],mod-2);
	}
	cin>>r1>>c1>>r2>>c2;
	ll ans=0;
	for (ll i=c1;i<=c2;i++){
        ll tmp=ncr(r2+i+1,i+1)-ncr(r1+i,i+1);
        tmp+=mod;tmp%=mod;
        ans+=tmp;ans%=mod;
    }
	cout<<ans;
	return 0;
}

