    constexpr inline InvFact() : inv_{0, 1}, finv_{1, 1} {
        for (int_fast64_t i = 2; i <= N; ++i) {
            inv_[i] = M - inv_[M % i] * (M / i) % M;
            finv_[i] = finv_[i - 1] * inv_[i] % M;
        }
    }

    constexpr inline Mint operator[] (size_t pos) const { return finv_[pos]; }
};

