ll nCr(ll n, ll r, ll M = MOD) {
  if (r > n) return 0;
  assert(fact[2] == 2);
  ll ret = fact[n];
  if (rfact[r] == 0) {
    rfact[r] = mod_inverse(fact[r], M);
  }
  ret = (ret*rfact[r]) % M;
  if (rfact[n - r] == 0) {
    rfact[n - r] = mod_inverse(fact[n - r], M);
  }
  ret = (ret*rfact[n - r]) % M;
  return ret;
}

ll nHr(ll n, ll r) {
  return nCr(n+r-1, r);
}

ll solve(int h, int w) {
  ll sum = 0;
  for (int a = 0; a <= h; a++) {
    ll add = (w + 1) * fact[a + w + 1] % MOD * mod_inverse(a + 1) % MOD * rfact[a] % MOD * rfact[w + 1] % MOD;
    sum += add;
  }
  sum %= MOD;
  return sum;
}

