const int64_t MOD= 1000000007;
const int Nfac= 2000007;
/* 剰余環 Z_n */
struct mint{ // Z_n に関する演算(n:素数の場合は除算も)をサポートする構造体
  int64_t rep; // 出力すべき代表元 rep \in {0,1,..,MOD- 1}
  mint(int64_t x=0): rep(((x%MOD)+ MOD)% MOD){}
  mint operator-() const { return mint(-rep);}
  mint& operator+=(const mint& x){
    rep+= x.rep; 
    if(rep>= MOD) rep-= MOD;
    return *this;
  }
  mint& operator-=(const mint& x){
    rep-= x.rep;
    if(rep< 0) rep+= MOD;
    return *this;
  }
  mint& operator*=(const mint& x){
    rep*= x.rep; rep%= MOD;
    return *this;
  }
  mint operator+(const mint x) const {
    mint ans(*this);
    ans+= x;
    return ans;
  }
  mint operator-(const mint x) const {
    mint ans(*this);
    ans-= x;
    return ans;
  }
  mint operator*(const mint x) const {
    mint ans(*this);
    ans*= x;
    return ans;
  }

  mint pow(int64_t d) const{ // d \geq 0
    if(d==0) return 1;
    else{
      mint ans= pow(d>>1);
      ans*= ans;
      if(d&1){ ans*= *this; }

      return ans;
    }
  }

  // MOD が素数(<=> Z_n が体)のとき
  mint inv() const{
    return pow(MOD-2);
  }
  mint& operator/=(const mint& x){
    *this *= x.inv();
    return *this;
  }
  mint operator/(const mint x) const {
    mint ans(*this);
    ans/= x;
    return ans;
  }
};

/* 階乗,二項係数 */
vector<mint> fac(Nfac+1), ifac(Nfac+1);
void fact_modp_init(int N= Nfac){
  fac.at(0)= 1;
  mint buf;
  for(int i=1; i<=N; i++){
    buf= i;
    fac.at(i)= fac.at(i-1)* buf;
  }

  ifac.at(N)= fac.at(N).inv();
  for(int i=N; i>0; i--){
    buf= i;
    ifac.at(i-1)= ifac.at(i)* buf;
  }
}

mint choose_modp(int n, int k){
  if(n < 0 || min(n,n-k) < 0) return 0;
  else return fac.at(n)* ifac.at(k)* ifac.at(n-k);
}
// ^^^ テンプレここまで ^^^
mint route(int r, int c){
  return choose_modp(r+c, c);
}

