ll g(ll a, ll b)
{
	ll sum = 0;
	for(ll i = 1; i<=a+1; ++i) 
		sum+=f(i, b)%MOD;
	return sum%MOD;
}

ll f(ll a, ll b)
{
	//(a+b)!/a!/b!;
	return arr[a+b]*cal(arr[a], MOD-2)%MOD*cal(arr[b], MOD-2)%MOD;
}

ll cal(ll a, ll b)
{
	if(b==0) return 1;
	if(b%2) return a*cal(a*a%MOD, b/2)%MOD;
	return cal(a*a%MOD, b/2)%MOD;
}

