template<long long mod>
class modint{
private:
  long long a;
public:
  constexpr modint(const long long x = 0) noexcept : a(x%mod) {}
  constexpr long long& value() noexcept { return a; }
  constexpr const long long& value() const noexcept { return a; }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }
  constexpr modint& operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if(a >= mod) a -= mod;
    return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
    if(a < rhs.a) a += mod;
    a -= rhs.a;
    return *this;
  }
  constexpr modint& operator*=(const modint rhs) noexcept {
    a = a*rhs.a%mod;
    return *this;
  }
  constexpr modint& operator/=(modint rhs) noexcept {
    long long k = mod-2;
    while(k > 0){
      if(k&1){
        *this *= rhs;
      }
      rhs *= rhs;
      k /= 2;
    }
    return *this;
  }
  friend ostream& operator<<(ostream &os, const modint &X){
    return os << X.a;
  }
  friend istream& operator>>(istream &is, modint &X){
    is >> X.a;
    X.a %= mod;
    if(X.a < 0) X.a += mod;
    return is;
  }
};


template<typename T>
struct Combination {
private:
  int sz;
  vector<T> F, F_;
public:
  Combination(int sz) : sz(sz), F(sz+1), F_(sz+1) {
    F[0] = 1;
    for(int i = 0; i < sz; ++i) F[i+1] = F[i]*(i+1);
    F_.back() = (T)1/F.back();
    for(int i = sz-1; i >= 0; --i) F_[i] = F_[i+1]*(i+1);
  }
  T C(int n, int k){
    assert(n <= sz);
    if(n < 0 or k > n) return (T)0;
    return F[n]*F_[k]*F_[n-k];
  }
};

int main(){
  using mint = modint<(int)1e9+7>;

  int r1, r2, c1, c2;
  cin >> r1 >> c1 >> r2 >> c2;
  //f(r,c) = (r+c)Cr
  //f(r+1,c) = (r+1+c)C(c) = (r+c)C(c) + (r+c)C(c-1)
  //(r+c)C(c-1) = (r-1)/c*(r+c)C(c)
  Combination<mint> comb((int)2e6+10);
  mint s = comb.C(r1+c1,c1);
  mint ans = s;
  int c_min = c1, c_max = c1;
  for(int r = r1+c1+1; r <= r2+c2; ++r){
    int c_min_ = max(c1,r-r2);// c_min_ >= c_min
    int c_max_ = min(c2,r-r1);// c_max_ >= c_max
    // sum(rCc | c_min <= c <= c_max)
    s *= 2;
    s -= comb.C(r-1,c_max);
    s += comb.C(r-1,c_min-1);
    for(int c = c_min; c < c_min_; ++c){
      s -= comb.C(r,c);
    }
    for(int c = c_max+1; c <= c_max_; ++c){
      s += comb.C(r,c);
    }
    ans += s;
    c_min = c_min_;
    c_max = c_max_;
  }
  cout << ans << endl;
}

