long long mypow(long long k, long long n) {
	long long temp = 1;

	k = k % DIV;
	while (n) {
		if (n % 2) temp = temp * k % DIV;
		k = k * k % DIV;
		n = n / 2;
	}
	return temp % DIV;
}

ll mmod(ll a, ll b) {
	if (a < 0)a += DIV; if (b < 0) b += DIV;
	a %= DIV, b %= DIV;
	return a * b % DIV;
}

