void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < 1000006; i++) {
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

long long mod_comb(long long n, long long k, long long mod) {
  if (n < k) {
    return 0;
  }
  if (n < 0 || k < 0) {
    return 0;
  }
  return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

long long g(long long x, long long y) {
  long long ret = 0;
  for (int i = 2; i <= y + 1; i++) {
    ret += mod_comb(x + i, i, MOD);
    ret %= MOD;
  }
  return ret;
}
