    ModFac(int n_){
      n=n_;
      f.resize(n+1,1);
      i_f.resize(n+1,1);
      for(int i=0;i<n;i++){
        f[i+1]=f[i]*(modint)(i+1);
      }
      i_f[n]=f[n].power(mod-2);
      for(int i=n-1;i>=0;i--){
        i_f[i]=i_f[i+1]*(modint)(i+1);
      }
    }
    ModFac(modint n_){
      n=(int)n_;
      f.resize(n+1,1);
      i_f.resize(n+1,1);
      for(int i=0;i<n;i++){
        f[i+1]=f[i]*(modint)(i+1);
      }
      i_f[n]=f[n].power(mod-2);
      for(int i=n-1;i>=0;i--){
        i_f[i]=i_f[i+1]*(modint)(i+1);
      }
    }

    modint factorial(int x){
      cout << f.size() << endl;
      return f[x];
    }

    modint inv_factorial(int x){
      return i_f[x];
    }

    modint comb(int m,int k){
      if (m<0 or k<0) return 0;
      if (m<k) return 0;
      return f[m]*i_f[k]*i_f[m-k];
    }
};


