template<int mod> struct mint {
    long long x;
    mint(long long x = 0) : x(x % mod) {
    }

    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) {
            x -= mod;
        }
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod-a.x) >= mod) {
            x -= mod;
        }
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(long long t) const {
        if (!t) {
            return 1;
        }
        mint a = pow(t>>1);
        a *= a;
        if (t&1) {
            a *= *this;
        }
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod-2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};

long long modpow(long long base, long long exp, long long mod) {
    base %= mod;
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long combination(long long n, long long r) {
    uint64_t ans = 1;
    for (uint64_t d = 1; d <= r; ++d) {
        ans *= n--;
        ans /= d;
    }
    return ans;
}

class Combination {
public:

    int mod;
    vector<long long> fact;
    vector<long long> inv;

    Combination(int n, int mod) : mod(mod) {
        assert(0 < n);
        this->fact.resize(n + 1, 1);
        this->inv.resize(n + 1, 1);

        for (int i = 1; i < fact.size(); ++i) {
            this->fact[i] = (i * this->fact[i - 1]) % this->mod;
            this->inv[i] = modpow(this->fact[i], this->mod - 2, this->mod);
        }
    }

    long long nCr(int n, int k) {
        assert(0 <= n and n < this->fact.size() and 0 <= k);
        assert(n >= k);
        auto a = this->fact[n];
        auto b = (this->inv[k] * this->inv[n - k]) % this->mod;
        return (a * b) % this->mod;
    }

    long long nHr(int n, int k) {
        return nCr(n + k - 1, k);
    }
};

const int MOD = 1000000000 + 7;

Combination comb(1000100, MOD);

mint<MOD> solve(LL Y1, LL X1, LL Y2, LL X2) {
    const auto H = Y2 - Y1 + 1;
    const auto W = X2 - X1 + 1;

    mint<MOD> ans = comb.nCr(Y1 + X1, Y1);

    FOR(y, 1, H) {
        auto a = comb.nCr(Y1 + y + X1, X1);
        ans += a;

        LL m = (H - y);
        LL n = (W - 1);
        if (n == 0 or m == 0) {
            continue;
        }
//        FOR(i, 0, m) {
//            FOR(j, 0, n) {
//                count += comb.nCr(i + j, i);
//            }
//        }
        mint<MOD> count = mint<MOD>(m + 1) * comb.nCr(m + n, n - 1) / n - 1;
        ans += count * a;
    }

    FOR(x, 1, W) {
        auto a = comb.nCr(X1 + x + Y1, Y1);
        ans += a;

        LL m = (H - 1);
        LL n = (W - x);
//        FOR(i, 0, H - 1) {
//            FOR(j, 0, W - x) {
//                int c = comb.nCr(i + j, i);
//                count += comb.nCr(i + j, i);
//            }
//        }
        mint<MOD> count = mint<MOD>(m + 1) * comb.nCr(m + n, n - 1) / n - 1;
        ans += count * a;
    }

    return ans;
}

mint<MOD> check(LL Y1, LL X1, LL Y2, LL X2) {
    mint<MOD> ans = 0;

    FOR(y, Y1, Y2 + 1) {
        FOR(x, X1, X2 + 1) {
            ans += comb.nCr(y + x, x);
        }
    }

    return ans;
}

