    return fact[a] * pwr(fact[b], -1) % mod * pwr(fact[a - b], -1) % mod;
}

long long pwr(long long a, long long b){
    if(b < 0)
        return pwr(a, mod - 1 + b);
    if(b == 0)
        return 1;
    long long c = pwr(a, b / 2);
    if(b % 2)
        return c * c % mod * a % mod;
    return c * c % mod;
}

long long kolle(long long r, long long c){
    long long ans = 0;
    for(long long i = 0; i <= r; i++){
        ans += choose(i + 1, c + i + 1);
        ans %= mod;
    }
    return ans;
}

