using namespace std;

typedef long long ll;

#define MOD 1000000007
#define MAXN 2000200

vector<ll> primes;

void mount_sieve(vector<bool>& sieve) {
	sieve[0] = sieve[1] = false;
	for (ll i = 2; i < MAXN; i++) {
		if (sieve[i]) {
			primes.push_back(i);
			ll x = i * i;
			while (x < MAXN) {
				sieve[x] = false;
				x += i;
			}
		}
	}
}

ll mod_pow(ll num, ll pot) {
	if (pot == 0) return 1;
	if (pot % 2 == 0) {
		ll x = mod_pow(num, pot / 2);
		x *= x;
		x %= MOD;
		return x;
	} else {
		ll x = mod_pow(num, pot - 1);
		x *= num;
		x %= MOD;
		return x;
	}
}

ll calc(ll a, ll b) {
	vector<int> factors(primes.size(), 0);
	ll target = a + b;
	for (int i = 0; i < primes.size(); i++) {
		ll prime = primes[i];
		while (prime <= target) {
			factors[i] += target / prime;
			prime *= primes[i];
		}
	}
	target = a;
	for (int i = 0; i < primes.size(); i++) {
		ll prime = primes[i];
		while (prime <= target) {
			factors[i] -= target / prime;
			prime *= primes[i];
		}
	}
	target = b;
	for (int i = 0; i < primes.size(); i++) {
		ll prime = primes[i];
		while (prime <= target) {
			factors[i] -= target / prime;
			prime *= primes[i];
		}
	}
	ll ret = 1;
	for (int i = 0; i < (int)factors.size(); i++) {
		ret *= mod_pow(primes[i], factors[i]);
		ret %= MOD;
	}
	return ret;
}

int main() {
	ios::sync_with_stdio(false);
	vector<bool> sieve(MAXN, true);
	mount_sieve(sieve);
	int r1, c1, r2, c2;
	cin >> r1 >> c1 >> r2 >> c2;
	ll a = calc(r2 + 1, c2 + 1);
	ll b = calc(r1, c1);a
	ll c = calc(r2+1, c1);
	ll d = calc(r1, c2+1);
	ll ans = (a + b) % MOD - (c + d) % MOD;
	ans += MOD;
	ans %= MOD;
	cout << ans << endl;
	return 0;
}

