ll mcomb(ll n, ll k, ll m)
{
    if(n == 0 && k == 0) return 1;
    if(n < k || n < 0) return 0;

    // x^y % m
    auto mpow = [](ll x, ll y, ll m)
    {
        ll ret = 1;
        while(y!=0)
        {
            if(y&1) ret = (ret*x) % m;
            x = (x*x) % m;
            y = y >> 1;
        }
        return ret;
    };

    vector<ll> fac(n+1, 1); // n! % m
    vector<ll> finv(n+1, 1); // 1/k! % m = k!^(m-2) % m
    for(int i=0;i<n;++i)
    {
        fac[i+1] = (fac[i]*(i+1)) % m;
        finv[i+1] = (finv[i]*mpow(i+1, m-2, m)) % m;
    }

    ll kf_inv = (finv[n-k]*finv[k]) % m; // 1/{(n-k)!*k!} % m
    return (fac[n]*kf_inv) % m; // nCk = n!/{(n-k)!*k!}
}

