ll sum(ll x, ll y, ll s){
	ll ret = 0;
	for(ll i=0; i<s; i++){
		ll tmp = fac[x+i+y-1] * inv[x+i] % MOD * inv[y-1] % MOD;
		ret += tmp * memo[s-i];
		ret %= MOD;
	}
	for(ll i=0; i<s; i++){
		ll tmp = fac[x-1+y+i] * inv[x-1] % MOD * inv[y+i] % MOD;
		ret += tmp * memo[s-i];
		ret %= MOD;
	}
	return ret;
}

