  modint& operator*=(const modint a) {
    n *= a.n;
    n %= mod;
    return *this;
  }
  modint operator*(const modint a) { return modint(*this) *= a; }
  modint pow(ll exp) {
    if (exp == 0) return 1;
    modint a = pow(exp >> 1);
    a *= a;
    if (exp & 1) a *= *this;
    return a;
  }
  modint inverse() { return pow(mod - 2); }
  modint operator/(const modint a) { return modint(*this) /= a; }
  modint& operator/=(modint a) { return (*this) *= a.inverse(); }
};
ostream& operator<<(ostream& o, const modint& m) {
  o << m.n;
  return o;
}

modint fact(int n) {
  static vector<modint> f = {1, 1};
  while (n >= (int)f.size()) f.push_back(f[f.size() - 1] * modint(f.size()));
  return f[n];
}

modint f(int r, int c) { return fact(r + c) / fact(r) / fact(c); }

modint sumF(int r, int c) {
  if (r < 0 || c < 0) return 0;
  return f(r + 1, c + 1) - f(r, 0);
}

