#include <bits/stdc++.h>
using namespace std;
#define int long long

/*
    A nice paper on Binomial Coefficients: http://www.cs.columbia.edu/~cs4205/files/CM4.pdf
    Number of ways to go form (0, 0) to (r, c): ncr(r, c) = Choose(r + c, r)
    If column is constant: We have to calculate ncr(r1, c) + ncr(r1 + 1, c) + ncr(r1 + 2, c) + ... + ncr(r2, c)
    Hockey Stick Identity : Σ ncr(i, r) ∀ i ∈ [r, n] = ncr(n + 1, r + 1)
    answer for a constant column = ncr(r2 + c + 1, c + 1) - ncr(r1 + c, c + 1)
    Can apply Hockey Stick Identity once more to simplify it to O(1) formula 
    (Better visualisation using Inclusion Exclusion Principle).
*/

const int MOD = 1e9 + 7;
const int N = 2e6 + 5;

int fac[N], inv[N];

int power(int x, int y) {
    int res = 1;
    while(y) {
        if(y & 1) 
            res = res * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return res;
}

void pre() {
    fac[0] = 1;
    for (int i = 1; i < N; i++)
        fac[i] = i * fac[i - 1] % MOD;

    inv[N - 1] = power(fac[N - 1], MOD - 2);
    for (int i = N - 2; i >= 0; i--)
        inv[i] = (i + 1) * inv[i + 1] % MOD; 
}

int choose(int n, int r) {
    if (r < 0 || r > n)
        return 0;
    return fac[n] * inv[r] % MOD * inv[n - r] % MOD;
}

signed main() {
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);

    pre();

    int T = 1; 
    // cin >> T; 
    while (T--) {
        int r1, c1, r2, c2;
        cin >> r1 >> c1 >> r2 >> c2;

        int ans = 0;
        for (int c = c1; c <= c2; c++) {
            int temp = (choose(r2 + c + 1, c + 1) - choose(r1 + c, c + 1) + MOD) % MOD;
            ans = (ans + temp) % MOD;
        }
        cout << ans << '\n';
    }

    return 0;
}

