class Combination {
 public:
  static constexpr int mod_ = 1000000007;
  static constexpr int n_ = 2000000 + 5;

  Combination() { build(); }

  std::array<Mint, n_> fact_;
  std::array<Mint, n_> inv_;
  std::array<Mint, n_> finv_;

  // return nCk
  Mint get(int n, int k) const noexcept {
    if (n < k || n < 0 || k < 0) return 0;
    return fact_[n] * finv_[k] * finv_[n - k];
  }

 private:
  void build() noexcept {
    fact_[0] = 1;
    fact_[1] = 1;
    finv_[0] = 1;
    finv_[1] = 1;
    inv_[1] = 1;
    for (int i = 2; i < n_; ++i) {
      fact_[i] = fact_[i - 1] * i;
      inv_[i] = mod_ - inv_[mod_ % i] * (mod_ / i);
      finv_[i] = finv_[i - 1] * inv_[i];
    }
  }
};

