    long ans = 0;
    ans = COMMOD(r2 + c2 + 2, c2 + 1) - COMMOD(r1 + c2 + 1, c2 + 1) - (COMMOD(r2 + c1 + 1, c1) - COMMOD(r1 + c1, c1));
    if(ans < 0) ans += MOD * 2;
    ans %= MOD;
    cout << ans << endl;
}

