ll exgcd(ll a, ll b, ll& x, ll& y)
{
    ll d=a;
    if(b!=0){
        d=exgcd(b,a%b,y,x);
        y-=(a/b)*x;
    }else{
        x=1;y=0;
    }
    return d;
}

ll mod_inverse(ll a, ll m)
{
    ll x, y;
    exgcd(a, m, x, y);
    return (m + x % m) % m;
}

ll mul[2*MAXN];

ll compute_f(int r, int c) 
{
    if(r==0 || c==0) return 1;
    ll a1 = mul[r+c];
    ll a2 = mod_inverse(mul[r], MOD);
    ll a3 = mod_inverse(mul[c], MOD);
    return (((a1*a2)%MOD)*a3) % MOD;
}

