const long long mod = 1e9 + 7;
long long fact[2000013];

long long sum_mod (long long a, long long b) {
	return (a + b) % mod;
}

long long mul_mod (long long a, long long b) {
	return (a * b) % mod;
}

long long pow_mod (long long a, long long b) {
	long long res = 1, t = a;
	while (b) {
		if (b & 1) {
			--b;
			res = mul_mod(res, t);
		}
		else {
			b >>= 1;
			t = mul_mod(t, t);
		}
	}
	return res;
}

long long sub_mod (long long a, long long b) {
	return (a - b + mod) % mod;
}

long long div_mod (long long a, long long b) {
	return mul_mod(a, pow_mod(b, mod - 2));
}

void precalc () {
	fact[0] = 1;
	for (long long i = 1; i < 2e6 + 13; ++i) 
		fact[i] = mul_mod(fact[i - 1], i);
}

long long c_mod (int n, int k) {
	if (n < k)
		return 0LL;
	return div_mod (fact[n], mul_mod (fact[k], fact[n - k]));
}

long long f (int r, int c) {
	return c_mod(r + c, c);
}

long long g (int r, int c) {
	long long res = 0LL;
	for (int x = 0; x <= r; ++x)
		res = sum_mod(res, f(x + 1, c));
	return res;
}

