using namespace std;

#define MOD 1000000007L

typedef long long ll;

ll factorialCache[2000010];
ll factorialInverseCache[2000010];

ll add(ll a, ll b) {
  return (a + b) % MOD;
}

ll sub(ll a, ll b) {
  return (a - b + MOD) % MOD;
}

ll mul(ll a, ll b) {
  return (a * b) % MOD;
}

ll pow(long a, long b) {
  if (b == 0) {
    return 1;
  }
  long v = pow(mul(a, a), b / 2);
  if (b % 2 == 1) {
    return mul(v, a);
  } else {
    return v;
  }
}

ll inverse(long a) {
  return pow(a, MOD - 2);
}

ll getC(int n, int k) {
    return mul(factorialCache[n], mul(factorialInverseCache[k], factorialInverseCache[n-k]));
}

ll solve(int r1, int c1, int r2, int c2) {
    factorialCache[0] = 1;
    factorialInverseCache[0] = 1;
    for (int i = 1; i <= r2 + c2; i++) {
      factorialCache[i] = mul(i, factorialCache[i - 1]);
      factorialInverseCache[i] = inverse(factorialCache[i]);
    }


    long answer = 0;
    long pathCount = getC(r1 + c1, r1);
    answer = add(answer, pathCount);
    for (int i = r1 + c1 + 1; i <= r2 + c2; i++) {
//      System.err.println(answer);

      pathCount = mul(pathCount, 2);
      if (i - r1 <= c2) {
        pathCount = add(pathCount, getC(i - 1, r1 - 1));
      } else {
        pathCount = sub(pathCount, getC(i - 1, c2));
      }
      if (i - c1 <= r2) {
        pathCount = add(pathCount, getC(i - 1, c1 - 1));
      } else {
        pathCount = sub(pathCount, getC(i - 1, r2));
      }
//      System.err.printf("pathCount: %d\n", pathCount);

      answer = add(answer, pathCount);
    }
    return answer;
}

int main() {
  int r1, c1, r2, c2;
  cin >> r1 >> c1 >> r2 >> c2;
  cout << solve(r1, c1, r2, c2) << endl;
}

