ll mod = 1000000007;

ll factorial(ll n) {
  ll ret = 1;
  for (ll i = 1; i <= n; ++i) {
    ret *= i;
    ret %= mod;
  }
  return ret;
}

ll pow(ll n, ll k){
  ll ret = 1;
  while (k > 0) {
    if (k & 1) {
      ret = ret * n;
      ret %= mod;
    }
    n = n * n;
    n %= mod;
    k >>= 1;
  }
  return ret;
}

ll inv_factorial(ll n) {
  ll ret = factorial(n);
  ret = pow(ret, mod - 2);
  return ret;
}

ll route(ll x, ll y){
  ll ret = factorial(x + y);
  ret *= inv_factorial(x);
  ret %= mod;
  ret *= inv_factorial(y);
  ret %= mod;
  return ret;
}

