const int MAX = 2000000;
const int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


int main() {
  // 前処理
    COMinit();

  int r_min;
  int c_min;
  int r_max;
  int c_max;
  cin >> r_min >> c_min >> r_max >> c_max;

  long long answer=0;
  r_max++;
  c_max++;
  answer += COM(r_max+c_max,c_max);
  answer -= COM(r_max+c_min,c_min);
  answer -= COM(r_min+c_max,c_max);
  answer += COM(r_min+c_min,c_min);

  answer %= 1000000007;

  cout << answer << endl;
}

