ll modex(ll a, ll b)
{
    ll ans = 1;
    for(; b > 0; b >>= 1, a = (a * a) % mod)
        if(b & 1)
            ans = (ans * a) % mod;
    return ans;
}
ll ncr(ll n, ll r)
{
    if(n < r || r < 0)
        return 0;
    ll ans = (fa[n] * modex(fa[r], mod - 2)) % mod;
    ans = (ans * modex(fa[n - r], mod - 2)) % mod;
}
ll f(ll r, ll c)
{
    ll ans = (mod - r) % mod;
    for(ll i = 1; i <= r; i++)
        ans = (ans + ncr(i + c + 1, c)) % mod;
    // cout << ans << endl;
    return ans;
}
