LL fac[N],invfac[N];

LL power(LL a, LL p) {
    if (p==0)   return 1;
    LL ans = power(a, p/2);
    ans = (ans * ans)%M;
    if(p%2) ans = (ans * a)%M;
    return ans;
}

void pre() {
    fac[0]= 1;
    for (int i=1; i<N; i++) fac[i] = (fac[i-1] * i)%M;
    invfac[N-1] = power(fac[N-1], M-2);
