ll FactorialInv[10000100];
ll Factorial[10000100];
ll beki(ll a, ll b){
    a %= mod;
    if(b == 0){
        return 1;
    }
    ll ans = beki(a, b / 2);
    ans = ans * ans % mod;
    if(b % 2 == 1){
        ans = ans * a % mod;
    }
    return ans;
}
void init_combination(){
    const int MAX = 10000002;
    Factorial[0] = 1;
    inv[0] = 1;
    for(int i = 1; i <= MAX; i++){
        Factorial[i] = Factorial[i - 1] * i % mod;
    }
    FactorialInv[MAX] = beki(Factorial[MAX], mod - 2);
    for(ll i = MAX - 1; i >= 0; i--) {
        FactorialInv[i] = FactorialInv[i+1] * (i+1) % mod;
    }
    for(int i = 1; i <= MAX; i++) {
        inv[i] = FactorialInv[i] * Factorial[i-1] % mod;
    }
}
ll combination(ll a, ll b){
    if((a == b) || (b == 0)){
        return 1;
    }
    if(a < b) return 0;
    ll ans = Factorial[a] * FactorialInv[b] % mod;
    ans = ans * FactorialInv[a - b] % mod;
    return ans;
}

ll f(ll X, ll Y) {
    ll ret = 0;
    ll tmp = beki(2, mod - 2);
    for(int i = 0; i <= X + Y; i++) {
        tmp *= 2;
        tmp %= mod;
        if(i - 1 >= X) {
            tmp -= combination(i-1, i - 1 - X);
        }
        if(i - 1 >= Y) {
            tmp -= combination(i-1, Y);
        }
        tmp += 3 * mod;
        tmp %= mod;
        //cerr << i << " " << tmp << endl;
        ret += tmp;
        ret %= mod;
    }
    cerr << ret << endl;
    return ret;
}

