struct mint {
    int val;

    mint(int v = 0) {
        val = v % MOD;
        if(val < 0) val += MOD;
    }

    static int mod_inv(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;

        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }

        return x < 0 ? x + m : x;
    }

    explicit operator int() const {
        return val;
    }

    mint& operator+=(const mint &other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }

    mint& operator-=(const mint &other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
        return x % m;
    }

    mint& operator*=(const mint &other) {
        val = fast_mod((uint64_t) val * other.val);
        return *this;
    }

    mint& operator/=(const mint &other) {
        return *this *= other.inv();
    }

    friend mint operator+(const mint &a, const mint &b) { return mint(a) += b; }
    friend mint operator-(const mint &a, const mint &b) { return mint(a) -= b; }
    friend mint operator*(const mint &a, const mint &b) { return mint(a) *= b; }
    friend mint operator/(const mint &a, const mint &b) { return mint(a) /= b; }

    mint& operator++() {
        val = val == MOD - 1 ? 0 : val + 1;
        return *this;
    }

    mint& operator--() {
        val = val == 0 ? MOD - 1 : val - 1;
        return *this;
    }

    mint operator++(int32_t) { mint before = *this; ++*this; return before; }
    mint operator--(int32_t) { mint before = *this; --*this; return before; }

    mint operator-() const {
        return val == 0 ? 0 : MOD - val;
    }

    bool operator==(const mint &other) const { return val == other.val; }
    bool operator!=(const mint &other) const { return val != other.val; }

    mint inv() const {
        return mod_inv(val);
    }

    mint pow(int p) const {
        assert(p >= 0);
        mint a = *this, result = 1;

        while (p > 0) {
            if (p & 1)
                result *= a;

            a *= a;
            p >>= 1;
        }

        return result;
    }

    friend ostream& operator<<(ostream &stream, const mint &m) {
        return stream << m.val;
    }
};

int sz;
mint _fac[1000009];
mint getf(int i) {
    if(sz == 0) {
        sz++;
        _fac[0] = 1;
    }
    while(sz <= i) {
        _fac[sz] = _fac[sz-1]*sz;
        sz++;
    }
    return _fac[i];
}

mint choose(int n, int k) {
    mint ans = 1;
    ans *= getf(n);
    ans /= getf(k);
    ans /= getf(n-k);
    return ans;
}

mint f(int r, int c) {
    if(r > c) swap(r, c);
    mint sm = 0;
    for(int i = 0; i <= r; ++i) {
        int n = i+c+1;
        int k = min(i+1, c);
        mint ad = choose(n, k);
        sm += ad;
    }
    return sm;
}

