llint modpow(llint a, llint n)
{
	if(n == 0) return 1ll;
	if(n % 2ll){
		return ((a%mod) * (modpow(a, n-1ll)%mod)) % mod;
	}
	else{
		return modpow((a*a)%mod, n/2ll) % mod;
	}
}

void make_fact()
{
	llint val = 1ll;
	fact[0] = 1ll;
	for(int i = 1ll; i < FACT_MAX; i++){
		val *= i;
		val %= mod;
		fact[i] = val;
	}
	fact_inv[FACT_MAX-1ll] = modpow(fact[FACT_MAX-1ll], mod-2ll);
	for(int i = FACT_MAX-2ll; i >= 0; i--){
		fact_inv[i] = fact_inv[i+1ll] * (i+1ll) % mod;
	}
}

llint comb(llint n, llint k)
{
	llint ret = 1ll;
	ret *= fact[n];
	ret *= fact_inv[k], ret %= mod;
	ret *= fact_inv[n-k], ret %= mod;
	return ret;
}

