ll extgcd(ll a,ll b,ll& x,ll& y){
	ll d=a;
	if(b!=0LL){
		d=extgcd(b,a%b,y,x);
		y-=(a/b)*x;
	}else{
		x=1;
		y=0;
	}
	return d;
}

ll mod_inverse(ll a,ll m){
	ll x,y;
	extgcd(a,m,x,y);
	return (m+x%m)%m;
}

ll fact[3000005];

ll mod_fact(ll n,ll p,ll& e){
	e=0;
	if(n==0)return 1;
	ll res=mod_fact(n/p,p,e);
	e+=n/p;
	if(n/p%2!=0){
		return res*(p-fact[n%p])%p;
	}
	return res*fact[n%p]%p;
}

ll mod_comb(ll n,ll k,ll p){
	if(n<0 || k<0 || n<k)return 0;
	ll e1,e2,e3;
	ll a1=mod_fact(n,p,e1),a2=mod_fact(k,p,e2),a3=mod_fact(n-k,p,e3);
	if(e1>e2+e3)return 0;
	return a1*mod_inverse(a2*a3%p,p)%p;
}



int solve(int sx,int sy,int x,int y){
	int r1=sx+sy,r2=sx;
	int u1=sx+sy,u2=sx;
	int sum=mod_comb(r1,r2,MOD);
	int ans=sum;
	for(int i=sx+sy;i+1<x+y;i++){
		sum=sum+sum;
		if(sum>=MOD){
			sum-=MOD;
		}
		if((i-sx-sy)<(x-sx)){
			sum+=mod_comb(r1,r2+1,MOD);
			if(sum>=MOD){
				sum-=MOD;
			}
			r1++;
			r2++;
		}else{
			sum+=MOD-mod_comb(r1,r2,MOD);
			if(sum>=MOD){
				sum-=MOD;
			}
			r1++;
		}
		if((i-sx-sy)<(y-sy)){
			sum+=mod_comb(u1,u2-1,MOD);
			if(sum>=MOD){
				sum-=MOD;
			}
			u1++;
		}else{
			sum+=MOD-mod_comb(u1,u2,MOD);
			if(sum>=MOD){
				sum-=MOD;
			}
			u1++;
			u2++;
		}
		ans+=sum;
		//printf("%lld\n",sum);
		if(ans>=MOD){
			ans-=MOD;
		}
	}
	if(sx!=x || sy!=y)ans+=mod_comb(x+y,x,MOD);
	if(ans>=MOD){
		ans-=MOD;
	}
	return ans;
}

