/* 二項係数計算用クラス． */
class Combinaion
{
private:
    /* テーブルの大きさの既定値．(MAX)! まで計算できる． */
    static constexpr ll MAX = 1e6 + 11;
    /* 実際のテーブルの大きさ． */
    ll max;
    /* 階乗を格納するテーブル．fac[n] := n! % MOD. */
    vc<mint> fac;
    /* 階乗の逆元を格納するテーブル．finv[n] := (fac[n])^(-1). */
    vc<mint> finv;

    /* 各種テーブルを初期化する． */
    void init(int n)
    {
        max = n;
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        REPM(i, 2, n)
        {
            fac[i] = fac[i - 1] * i;
        }
        finv[n] = fac[n].inv();
        REPR(i, n, 2)
        {
            finv[i - 1] = finv[i] * i;
        }
    }

public:
    /* コンストラクタ． */
    Combinaion(int n = MAX) : fac(n + 1), finv(n + 1)
    {
        init(n);
    }

    /* 二項係数 nCk % MOD を計算する． */
    mint operator()(ll n, ll k) const
    {
        assert(n <= max); // ここで詰まると RE
        assert(k <= max);
        if (n < k || n < 0 || k < 0)
            return 0;
        return fac[n] * finv[k] * finv[n - k];
    }
};

/**
Problem
 */
void solve()
{
    ll r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;

    Combinaion c(r2 + c2 + 2 + 11);
    mint ret = c(c2 + r2 + 2, r2 + 1);
    ret += c(c1 + r1, r1);
    ret -= c(c2 + r1 + 1, r1);
    ret -= c(c1 + r2 + 1, r2 + 1);

