  COMinit();

  ll from = r1 + c1;
  ll to = r2 + c2;
  ll dist = to - from;

  mint now = COM(from, r1);
  mint ans = now;
  ll nr1 = r1, nc1 = c1, nr2 = r1, nc2 = c1;
  for(ll i = 1; i <= dist; i++){    
    now *= 2;
    if(nr1 == r2){
      if(nc1 == c2){        
      } else {
        nc1 += 1;
        now -= COM(nr1 + nc1 - 1, nr1);
      }
    } else {
      nr1 += 1;
      now += COM(nr1 + nc1 - 1, nr1);
    }

    if(nc2 == c2){
      if(nr2 == r2){
      } else {
        nr2 += 1;
        now -= COM(nr2 + nc2 - 1, nc2);      
      }
    } else {
      nc2 += 1;
      now += COM(nr2 + nc2 - 1, nc2);      
    }
    ans += now;
  }
  cout << ans.x << endl;

  return 0;
}

