ll qPow(ll a, ll b)
{
	a %= mod;

	ll res = 1;
	while(b) {
		if(b & 1) res = res * a % mod;
		a = a * a % mod, b >>= 1;
	}
	return res;
}

ll C(ll n, ll m)
{
	if(n < m) return 0;

	ll res = 1;
	for(int i = 1; i <= m; ++i)
		res = res * (n - i + 1) % mod * qPow(i, mod - 2) % mod;
	return res;
}

