class Comb {
public:
    Comb() :fac(0), finv(0) {}
    Comb(int n) :fac(n + 1), finv(n + 1)
    {
        fac[0] = 1;
        for (int i = 1; i <= n; ++i) fac[i] = fac[i - 1] * i;
        finv[n] = fac[n].inv();
        for (int i = n; i >= 1; --i) finv[i - 1] = finv[i] * i;
    }
    void resize(int size) { *this = { size }; }
    mint C(int n, int k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n - k]);
    }
    mint P(int n, int k) {
        if (k < 0) return 0;
        return C(n, k) * fac[k];
    }
    // n!
    mint Fac(int n) {
        if (n < 0) return 0;
        return fac[n];
    }
private:
    std::vector<mint> fac;
    std::vector<mint> finv;
};

