const int mod = 1e9+7;
int add(int a, int b) {
	return a + b >= mod ? a + b - mod : a + b;
}
int mul(int a, int b) {
	return int(1LL * a * b % mod);
}
int fexp(int b, int e = mod - 2) {
	int ans = 1;
	while(e) {
		if(e & 1) ans = mul(ans, b);
		b = mul(b, b);
		e /= 2;
	}
	return ans;
}

const int N = 1000006;

int fat[N], ifat[N];
int C(int n, int k) {
	if(n < k) return 0;
	return mul(mul(fat[n], ifat[k]), ifat[n-k]);
}

int solve(int n, int m) {
	if(n < 0 or m < 0) return 0;
	int ans = 0;
	for(int j = 0; j <= m; j++) {
		ans = add(ans, C(j + n + 1, j + 1));
	}
	return ans;
}

int main() {
	fat[0] = ifat[0] = 1;
	for(int i = 1; i < N; i++) {
		fat[i] = mul(i, fat[i - 1]);
		ifat[i] = fexp(fat[i]);
	}
	int r1, c1, r2, c2;
	scanf("%d %d %d %d", &r1, &c1, &r2, &c2);
	int ans = 0;
	ans = add(ans, solve(r2, c2));
