void E(long long a, long long b, long long &x, long long &y)
{
    if(!b)
    {
        y=0;
        x=1;
    }
    else
    {
        long long x0, y0;
        E(b, a%b, x0, y0);
        x = y0;
        y = x0 - (a / b) * y0;
    }
}

long long Cmb(int a,int b)
{
    long long A, B, C, x, y;
    A = v[a];
    B = v[b];
    C = v[a-b];
    E(B, MOD, x, y);
    while(x < 0)
        x+=MOD;
    B = M (x);
    A = M (A * B);
    E(C, MOD, x, y);
    while(x < 0)
        x+=MOD;
    C = M(x);
    A = M(A * C);
    return A;
}

long long S (int a, int b){
    long long ans = 0;
    for (int it = 0; it < a; ++it){
        ans = M (ans + Cmb(b + it + 2, b));
    }
    return ans;
}

