vector<ll> factorial(int N){
    vector<ll> fact(N+1,1);
    for(int i=1; i<N; i++){
        fact[i+1]=(i+1)*fact[i]%MOD;
    }
    return fact;
}

map<long long, long long> inv_fact;
long long inv_factorial(long long x){
    if (inv_fact.find(x)!=inv_fact.end()){
        return inv_fact[x];
    }
    long long p=MOD-2;
    long long ret=1;
    long long tmp=x;
    while(p){
        if(p&1)(ret*=tmp)%=MOD;
        (tmp*=tmp)%=MOD;
        p>>=1;
    }
    inv_fact[x]=ret;
    return ret;
}

long long comb(int a, int b, vector<ll> &fact){
    if(b==0){
        return 1;
    }
    long long ret=fact[a]*inv_factorial(fact[a-b])%MOD;
    return ret*inv_factorial(fact[b])%MOD;
}

