ll MathPow(ll x, ll a)//戻り値はx^a。O(loga)
{
  ll num = 2;
  ll answer = 1;
  ll check = a;
  ll memo = x;

  while(check > 0)
  {
    if(check % num == num / 2)
    {
      check -= num / 2;
      answer *= memo;
    }
  memo *= memo;
  num *= 2;
  }
  return answer;
}

ll DivideMod(ll x, ll a, ll p)//戻り値はx^a(mod p)。O(loga)
{
  ll num = 2;
  ll answer = 1;
  ll check = a;
  ll memo = x%p;

  while(check > 0)
  {
    if(check % num == num / 2)
    {
      check -= num / 2;
      answer *= memo;
      answer %= p;
    }
  memo *= memo;
  memo %= p;
  num *= 2;
  }
  return answer;
}

ll DivideModReverse(ll x, ll p)//戻り値はx^-1(mod p), pは素数。O(logp)
{
  ll answer = DivideMod(x, p-2, p);
  return answer;
}

ll ModFactorial(ll x, ll p)//戻り値はx!(mod p)
{
  ll answer = 1;
  for(int i = 2; i <= x; i++)
  {
    answer *= i;
    answer %= p;
  }
  return answer;
}

ll DivideModFactorial(ll x, ll p)//戻り値はx!^-1(mod p), pは素数
{
  ll answer = 1;
  for(ll i = x; i >= 2; i--)
  {
    answer *= DivideModReverse(i, p);
    answer %= p;
  }
  return answer;
}

ll Comb(ll a, ll b, ll p)//組み合わせC(a,b)(mod p)をO(1)で返す
{
  if(a-b < 0) return 0;//引数a-bが負なら0を返す
  ll answer = 1;
  answer *= factorials[a];
  answer %= p;
  answer *= factorialRs[a-b];
  answer %= p;
  answer *= factorialRs[b];
  answer %= p;
  return answer;
}

