vector <ll> factorials;
ll mod=1e9+7;

ll modExp(ll x, ll n)
{
    if (n==0) return 1;
    if (n==1) return x%mod;
    ll ans = modExp(x,n/2);
    ans = (ans*ans)%mod;
    if (n%2) ans*=x;
    return ans%mod;
}

ll modInv(ll a)
{
    return modExp(a, mod-2);
}

ll choose(ll n, ll k) 
{
    if (k==0) return 1;
    if (k>n) return 0;
    ll num = factorials[n];
    ll den = (factorials[n-k]*factorials[k])%mod;
    den = modInv(den);
    return (num*den)%mod;
}

