int quick_power(int a,int b)
{
	if (b==0)  return 1%mod;

	int res=1ll;
	for (;b;b=b>>1,a=(1ll*a*a)%mod)
	{
		if (b&1ll)  res=(1ll*res*a)%mod;
	}
	return res%mod;
}

int ny(int n)
{
	return quick_power(n,mod-2ll);
}

int C(int n,int k)
{
	if (k==0)  return 1;
	if (k>n-k)  k=n-k;

	int x=1ll,y=1ll;
	for (int i=1;i<=k;i++)
	{
		x=(x*(n-i+1))%mod;
		y=(y*i)%mod;
	}
	return (x*ny(y))%mod;
}

int find_sum(int l,int r,int k)
{
	int big=C(k+r+1,k+1);
	int small=C(k+l,k+1);
	return ((big-small)%mod+mod)%mod;
}

