const int mod = 1e9 + 7;

void add_self (int & a, int b) {
	a += b;
	if (a >= mod) a -= mod;
}

void sub_self (int & a, int b) {
	a -= b;
	if (a < 0) a += mod;
}

int mul (int a, int b) {
	return (int) (((ll) a * b) % mod);
}

int power (int a, int k) {
	int ans = 1;
	while (k >= 1) {
		if (k & 1) ans = mul (ans, a);
		a = mul (a, a);
		k >>= 1;
	}
	return ans;
}

int inverse (int a) {
	return power (a, mod - 2);
}

int choose (int n, int r) {
	int ans = 1;
	int k = 1;
	while (k <= r) {
		ans = mul (ans, mul (n, inverse (k)));
		n--; k++;
	}
	return ans;
}

int f (int r, int c) {
	add_self (r, c);
	add_self (r, 2);
	add_self (c, 1);
	return choose (r, c);
}

