void precompute(){
	fact[0] = 1;
	for(int i = 1; i < N; i++){
		fact[i] = (fact[i-1]*i)%MOD;
	}

	i_fact[N-1] = power(fact[N-1], MOD - 2);

	for(int i = N-2; i >= 0; i--){
		i_fact[i] = ((i+1) * i_fact[i+1])%MOD;
	}
}

ll ncr(int n, int r){
	return (((fact[n]*i_fact[r])%MOD)*i_fact[n-r])%MOD;
}


ll sum(ll r, ll c){

	if(r > c) swap(r, c);


	ll tot = 0;
	for(int i = 0; i <= r + c; i++){
		Mod(tot += (power(2, i)));		
	}


	ll fx = 0;  
	ll gx = -1;
	ll val;
	ll val2;
	for(int x = 1; x <= c; x++){ 
		if(r + x - c - 1 == 0){
			gx = 0;
		}
		Mod(tot -= (gx + 1));
		Mod(tot -= (fx + 1));

		val = ncr(r + x, x) + 1;	
		//debug(fx, r + x, x, val);
		fx = (2*fx + val)%MOD; // f(x + 1)
