    for (ll i=2;i<N;++i)
    {
        fact[i] = (i * fact[i - 1]) % M;
        inv[i]  = M - (inv[M % i] * (M / i)) % M;
        finv[i] = (finv[i - 1] * inv[i]) % M;
    }

    const auto ncr = [&](ll n, ll r)
    {
        return (fact[n] * ((finv[r] * finv[n - r]) % M)) % M;
    };

