  for (size_t i = 1; i <= MAX; i++) {
    fact[i] = fact[i-1]*i%MOD;
  }
  ifact[MAX] = mod_inv(fact[MAX]);
  for (long long i = MAX-1; i >= 0; i--) {
    ifact[i] = ifact[i+1] * (i+1) % MOD;
  }
}

size_t mod_cmb(size_t x, size_t y) {
  return fact[x] * ifact[x-y] % MOD * ifact[y] % MOD;
}

}

