LL fpow(LL x, LL power, LL mod) 
{
    x %= mod;
    LL ans = 1;
    for (; power; power >>= 1, (x *= x) %= mod)
        if(power & 1) (ans *= x) %= mod;
    return ans;
}
LL qinv(LL a)
