const ll MOD = 1e9 + 7;


ll power(ll n, ll p) {
	ll ans = 1;
	while (p > 0) {
		if (p & 1) {
			ans = (n * ans) % MOD;
		}
		n = (n * n) % MOD;
		p /= 2;
	}
	return ans;
}


ll inverse(ll n) {
	return power(n, MOD - 2);
}

