ll times(ll a, ll b)
{
    return modx(modx(a)*modx(b));
}

ll add(ll a, ll b)
{
    return modx(modx(a)+modx(b));
}

ll sub(ll a, ll b)
{
    return modx(MOD+modx(a)-modx(b));
}

ll fastExp(ll base, ll exp)
{
    if(exp == 0LL)
    {
        return 1LL;
    }

    if(exp%2==0)
    {
        return fastExp(times(base, base), exp/2);
    }
    else
    {
        return times(base, fastExp(times(base, base), exp/2));
    }
}

ll choose(ll a, ll b)
{
    ll res = 1LL;
    for(ll i = a; i>=a-b+1; i--)
    {
        res = times(res, i);
    }

    for(ll i = 1; i<= b; i++)
    {
        res = times(res, fastExp(i, MOD-2));
    }
    return res;
}


