mint g(int R, int C) {
    dp[0] = 1;
    int r1 = 0, c1 = 0;
    int r2 = 0, c2 = 0;
    rep(i, 0, R + C) {
        dp[i + 1] = dp[i] * 2;

        if (r1 != R) r1++;
        else {
            dp[i + 1] -= com.aCb(r1 + c1, r1);
            c1++;
