  cin>>R[0]>>C[0]>>R[1]>>C[1];

  //R[0]++;C[0]++;R[1]++;C[1]++;
  setComb();

  ll ans=solve(R[1],C[1]);
  ans-=solve(R[1],C[0]-1);
  ans=(ans+MOD)%MOD;
  ans-=solve(R[0]-1,C[1]);
  ans=(ans+MOD)%MOD;
  ans+=solve(R[0]-1,C[0]-1);
  ans=(ans+MOD)%MOD;
  cout<<ans<<endl;

  return 0;
}

