// r = a^n % mod
int64_t mod_pow(int64_t a, int64_t n, int64_t mod) {
  int64_t r = 1;
  while (n > 0) {
    if (n & 1) {
      r = (r * a) % mod;
    }
    a = (a * a) % mod;
    n >>= 1;
  }
  return r;
}

// a^{-1} % mod
int64_t mod_inv(int64_t a, int64_t mod) {
  return mod_pow(a, mod-2, mod);
}

const int64_t kMod = 1000000007;
const int kMax = 2000017;
std::vector<int64_t> fact(kMax), fact_inv(kMax);

void combi_init() {
  const int n = fact.size();
  fact[0] = 1;
  for (int i = 1; i < n; ++i) {
    fact[i] = (i * fact[i-1]) % kMod;
  }
  fact_inv[n-1] = mod_inv(fact[n-1], kMod);
  for (int i = n-1; i > 0; --i) {
    fact_inv[i-1] = (i * fact_inv[i]) % kMod;
  }
}

int combi(int n, int k) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return (((fact[n] * fact_inv[k]) % kMod) * fact_inv[n-k]) % kMod;
}

int f(int r, int c) {
  return combi(r+c, c);
}

int g(int r, int c) {
  return (f(r+1, c+1) - 1 + kMod) % kMod;
}

