        pre[i] = pre[i-1] * i % mod;
        inv[i] = (mod - mod / i * inv[mod % i] % mod) % mod;
        prei[i] = prei[i-1] * inv[i] % mod;
    }
}
ll C(int n, int k){
   return pre[n] * prei[k] % mod * prei[n-k] % mod;
}
ll pm(int n,int p){
    ll ret = 1;
    ll now = n;
    while(p){
        if(p & 1){
            ret *= now;
            ret %= mod;
        }
        now *= now;
        now %= mod;
        p >>= 1;
    }
    return ret;
}
ll solve(ll x,ll y){
    if(x==0||y==0)return 0;
    ll ret = 0;
    for(int i = 1 ; i <= y ; i++){
        ret += C(x+i+1,x);
        ret += mod - 1;
        ret %= mod;
    }
    return ret;
}

