        k2=COM(c2-i+r2-r1,r2-r1);//(i,r1から)(c2,r2)
        ans+=k1*k2;
        ans%=MOD;
    }

    for(int i=r1;i<=r2;i++){
        ll k1,k2;
        k1=COM(c1+i,c1);//(0,0)から(c1,i)
        k2=COM(c2-c1+r2-i,c2-c1);//(c1,i)から(c2,r2)
        ans+=k1*k2;
        ans%=MOD;
    }

