std::vector<long long> fact, inv;

constexpr auto pow(long long x, long long n, const long long mod) {
    long long ret = 1;
    while(n > 0) {
        if ((n & 1) == 1) ret = (ret * x) % mod;
        x = (x * x) % mod;
        n >>= 1;
    }
    return ret;
}

constexpr auto inverse(const long long x, const long long p) {
    return pow(x, p - 2, p);
}

void init_factorial(const int n, const long long mod) {
    fact.resize(n + 1);
    inv.resize(n + 1);
    fact[0] = 1;
    for (long long i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
    inv[n] = inverse(fact[n], mod);
    for (long long i = n; i > 0; i--) inv[i - 1] = inv[i] * i % mod;
}

constexpr i64 mod = 1000000007;

i64 calc(i64 r, i64 c) {
    if (!r || !c) return 0;
    if (r > c) std::swap(r, c);

    i64 s = 0, ret = 0;

    for (int i = 2; i <= r + 1; i++) {
        s = (s + 1) * 2 % mod;
        ret = (ret + s) % mod;
    }

    for (int i = r + 2; i <= c + 1; i++) {
        s = (s * 2 + 1 + mod - fact[i - 1] * inv[r] % mod * inv[i - 1 - r] % mod) % mod;
        ret = (ret + s) % mod;
    }

    for (int i = c + 2; i <= r + c; i++) {
        s = (s * 2 + mod * 2 - fact[i - 1] * inv[r] % mod * inv[i - 1 - r] % mod - fact[i - 1] * inv[c] % mod * inv[i - 1 - c] % mod) % mod;
        ret = (ret + s) % mod;
    }

    return ret;
}

