#define mod 1000000007
#define MAX 100005
#define M 32

using namespace std;
using namespace __gnu_pbds;

ll fact[1000010];
ll inv_fact[1000010];

ll modex(ll x,ll y)
{
    x=x%mod;
    ll r=1;
    while(y>0)
    {
        if(y%2==1)
            r=(r*x)%mod;
        y/=2;
        x=(x*x)%mod;
    }
    return r;
}

ll mm(ll x,ll y)
{
    x=x%mod;
    y=y%mod;
    return (x*y)%mod;
}

void build(void)
{
    fact[0]=1;
    ll i;
    fs(i,1,1000010)
    {
        fact[i]=mm(fact[i-1],i);
    }
    inv_fact[1000009]=modex(fact[1000009],mod-2);
    fr(i,1000008)
    {
        inv_fact[i]=mm(inv_fact[i+1],i+1);
    }
}

ll C(ll n,ll r)
{
    if(n<r)
        return 0;
    ll res=fact[n];
    res=mm(res,inv_fact[n-r]);
    res=mm(res,inv_fact[r]);
    return res;
}

