vector<Int> divisors_proper(Int n) {
    if(n == 1) return {};
    vector<Int> res(1, 1);

    Int d = 2;
    for(; d*d < n; ++d) {
        if(n % d == 0) {
            res.emplace_back(d);
            res.emplace_back(n/d);
        }
    }
    if(d*d == n)
        res.emplace_back(d);

    return res;
}

