}

// F(0) = 0
// F(1) = 1
// F(n) = F(n-1) + F(n-2)
//
// // decltype(auto) で受けると SIZE() が使える (auto だとポインタになってしまう)
// decltype(auto) fib = fibonacci_table<1000>();
template<Int N>
ModInt (&fibonacci_table())[N] {
    static_assert(N >= 2, "");
    static ModInt fib[N] {};

    if(fib[1] != 1) {
        fib[0] = 0;
        fib[1] = 1;
        FOR(i, 2, N) {
            fib[i] = fib[i-1] + fib[i-2];
        }
    }
    return fib;
}

template<Int N>
ModInt (&factorial_table())[N] {
    static_assert(N >= 1, "");
    static ModInt fac[N] {};

    if(fac[0] != 1) {
        fac[0] = 1;
        FOR(i, 1, N) {
            fac[i] = i * fac[i-1];
        }
    }
    return fac;
}

template<Int N>
ModInt (&ifactorial_table())[N] {
    static_assert(N >= 1, "");
    static ModInt ifac[N] {};

    if(ifac[0] != 1) {
        decltype(auto) fac = factorial_table<N>();
        ifac[N-1] = fac[N-1].inv();
        for(Int i = N-2; i >= 0; --i) {
            ifac[i] = (i+1) * ifac[i+1];
        }
    }
    return ifac;
}

ModInt permutation_count_fac(Int n, Int r, const ModInt* fac, const ModInt* ifac) {
    if(n < r) return 0;
    return fac[n] * ifac[n-r];
}

template<Int H, Int W>
ModInt (&combination_count_table())[H][W] {
    static_assert(W >= 1 && H >= W, "");
    static ModInt dp[H][W] {};

    if(dp[0][0] != 1) {
        REP(i, H) {
            dp[i][0] = 1;
            dp[i][i] = 1;
        }
        FOR(i, 1, H) FOR(j, 1, i) {
            dp[i][j] = dp[i-1][j-1] + dp[i-1][j];
        }
    }
    return dp;
}

template<Int H, Int W>
auto combination_count_func() {
    static_assert(W >= 1 && H >= W, "");
    return FIXMEMO<H,W>([](auto&& self, Int n, Int r) -> ModInt {
        if(n <  r) return 0;
        if(r == 0) return 1;
        if(n == r) return 1;
        return self(n-1,r-1) + self(n-1,r);
    });
}

ModInt combination_count_fac(Int n, Int r, const ModInt* fac, const ModInt* ifac) {
    if(n < r) return 0;
    return fac[n] * ifac[r] * ifac[n-r];
}

// 分割数 P(n,k) (n を k 個の正整数の和で表す場合の数)
//
// 「n を 最大値 k の正整数の和で表す場合の数」でもある。
// 「n を k 個『以下』の正整数の和で表す場合の数」は sum(P(n,i)) (1<=i<=k)
// 「n を k 個の『非負整数』の和で表す場合の数」は P(n+k,k)
//
// P(0,0) = 1
// P(n,0) = 0
// P(0,k) = 0
// n < k のとき P(n,k) = 0
// P(n,1) = 1
// P(n,n) = 1
//
// 順序を区別するものは合成(composition)とよばれる。
// 「n を k 個の順序つき正整数列の和で表す場合の数」は Q(n,k) = comb(n-1,k-1)
// 「n を k 個の順序つき『非負整数』列の和で表す場合の数」は Q(n+k,k) = comb(n+k-1,k-1) = comb(n+k-1,n)
// 「n を順序つき正整数列の和で表す場合の数」は 2^(n-1)
template<Int H, Int W>
ModInt (&partition_count_table())[H][W] {
    static_assert(W >= 1 && H >= W, "");
    static ModInt dp[H][W] {};

    if(dp[0][0] != 1) {
        REP(j, W) {
            dp[j][j] = 1;
        }
        FOR(i, 2, H) {
            dp[i][1] = 1;
        }
        FOR(i, 3, H) {
            FOR(j, 2, MIN(i,W)) {
                dp[i][j] = dp[i-1][j-1] + dp[i-j][j];
            }
        }
    }
    return dp;
}

// 分割数 メモ化再帰版
template<Int H, Int W>
auto partition_count_func() {
    static_assert(W >= 1 && H >= W, "");
    return FIXMEMO<H,W>([](auto&& self, Int n, Int k) -> ModInt {
        if(n <  k) return 0;
        if(n == k) return 1;
        if(k == 1) return 1;
        return self(n-1,k-1) + self(n-k,k);
    });
}

