long long Modpow(long long a, long long n, long long mod)
{
    long long ans = 1;
    while(n > 0)
    {
        if(n & 1)
        {
            ans = ans * a % mod;
        }
        a = a * a % mod;
        n >>= 1;
    }
    return ans;
}

long long Modinv(long long a, long long mod)
{
    return Modpow(a, mod - 2, mod);
}

long long ModCmb(long long n, long long c, long long mod, const std::vector<long long>& fac)
{
    return ((fac.at(n) * Modinv(fac.at(c), mod)) % mod) * Modinv(fac.at(n-c), mod) % mod;
}

int main()
{
    constexpr int MOD = 1000000007;

    int r1, c1, r2, c2;
    std::cin >> r1 >> c1 >> r2 >> c2;

    // rCr + r+1 C r + ... + nCr = n+1 C r+1
    // ゆえに
    // r+c1 C r + ... + r+c2 C r = r+c2+1 C r+1 - r+c1 C r+1

    std::vector<long long> factorial;
    factorial.reserve(r2+c2+2);
    factorial.emplace_back(1); // 0! = 1
    for(int i = 1; i < r2 + c2 + 2; ++i)
    {
        factorial.emplace_back(factorial.back() * i % MOD);
    }

    long long sum = 0;
    for(int r = r1; r <= r2; ++r)
    {
        long long curPath = (ModCmb(r+c2+1, r+1, MOD, factorial) - ModCmb(r+c1, r+1, MOD, factorial)) % MOD;
        if(curPath < 0)
        {
            curPath += MOD;
        }
        sum = (sum + curPath) % MOD;
    }
    std::cout << sum << std::endl;
}

