void fact_memo(ll n, ll mod){
    memo[0] = 1; memoinv[0] = modinv(memo[0], mod);
    rep(i, n + 1){
        memo[i + 1] = ((i + 1) * memo[i]) % mod;
        memoinv[i + 1] = modinv(memo[i + 1], mod);
    }
