ll f(ll x, ll y) {
	ll ans = 0;
	ll n = x;
	if (x == 0) return y + 1;
	else if (y == 0) return x + 1;
	for (ll j = 1; j <= y + 1; j++) {
		(ans += C(n + j, n)) %= mod;
	}

	return ans;
}

