    vll fac(n + 2, 0), inv(n + 2, 0);

    // O(n)
    fac[0] = 1;
    rep(i, 1, n + 2) { fac[i] = (i * fac[i - 1]) % MOD; }

    // O(nlog(MOD))
    inv.back() = mpow(fac.back(), MOD - 2);
    rrep(i, 0, n + 1) { inv[i] = (inv[i + 1] * (i + 1)) % MOD; }

    // O(n)
    ll sum = 0;
    vvi dp(n + 1, vi(n + 1, -1));
    rep(i, r1, r2 + 1) {
        sum = (sum + f(fac, inv, i + 1, c2) - f(fac, inv, i + 1, c1 - 1)) % MOD;
    }
    cout << sum << endl;
    return 0;
}

#include <iostream>

constexpr int MAX = 1000001;
constexpr int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
  static bool init = false;
  if (init) {
    return;
  }
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
  init = true;
}

long long COM(int n, int k){
  COMinit();
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


