// ax+by=1の解
int extgcd(int a, int b, int& x, int& y){
    int d = a;
    if (b != 0){
        d = extgcd(b, a%b, y, x);
        y -= (a / b)*x;
    }
    else{
        x = 1; y = 0;
    }
    return d;
}

// mod mでのaの逆数
int mod_inv(int a, int m){
    int x, y;
    extgcd(a, m, x, y);
    return (m + x%m) % m;
}

// nの階乗 mod p
int factorial(int n, int p){
    int r = 1;
    for (int i = 1; i <= n; i++)
        r = (r*i) % p;
    return r;
}

// nPr mod p
int permutation(int n, int r, int p){
    int a = 1;
    for (int i = n-r+1; i <= n; i++)
        a = (a*i) % p;
    return a;
}

// nCr mod p
int combination(int n, int r, int p){
    if (r == 0 || r == n) return 1;
    if (r > n) return 0;
    if (r > n / 2) r = n - r;
    int numerator = permutation(n, r, p);
    int denominator = factorial(r, p) % p;
    int inv = mod_inv(denominator, p);
    return (numerator * inv) % p;
}

int calc(int a, int b){
    int r = 0;
    r = ((a+2) *combination(a+b+2, a+2, mod) % mod + mod )- b - 1;
    r *= mod_inv(b+1, mod);
    r %= mod;
    return (r+mod-1)%mod;
}

