// C(i + j, i) where i and j have limits <= n and <= m
// C(i + m + 1, i + 1)
#define ll long long

const ll mod = 1e9 + 7; // change to something else

ll euclid(ll a, ll b, ll &x, ll &y) {
	if (b) { ll d = euclid(b, a % b, y, x);
		return y -= a/b * x, d; }
	return x = 1, y = 0, a;
}
struct Mod {
	ll x;
	Mod(ll xx = 0) : x(xx) {}
	Mod operator+(Mod b) { return Mod((x + b.x) % mod); }
	Mod operator-(Mod b) { return Mod((x - b.x + mod) % mod); }
	Mod operator*(Mod b) { return Mod((x * b.x) % mod); }
	Mod operator/(Mod b) { return *this * invert(b); }
	Mod invert(Mod a) {
		ll x, y, g = euclid(a.x, mod, x, y);
		assert(g == 1); return Mod((x + mod) % mod);
	}
	Mod operator^(ll e) {
		if (!e) return Mod(1);
		Mod r = *this ^ (e / 2); r = r * r;
		return e&1 ? *this * r : r;
	}
};

const int N = 2e6 + 55;
Mod fac[N], ifac[N]; 

Mod c (int n, int r) {
	if (r > n)
		return Mod(0);
	Mod ans = (fac[n] * ifac[r]) * ifac[n - r];
	return ans;
} 

Mod get (int n, int m) {
	Mod ans = 0;
	rep(i, 0, n + 1) {
		ans = ans + c(i + m + 1, i + 1);
	}
	return ans;
}
void solve() {
    fac[0] = 1;
    rep(i, 1, N)
    	fac[i] = fac[i - 1] * Mod(i);
    ifac[N - 1] = Mod(1)/Mod(fac[N - 1]);
    for (int i = N - 2; i >= 0; --i) {
    	ifac[i] = (ifac[i + 1] * Mod(i + 1));
    }
    int r1, r2, c1, c2;
    cin >> r1 >> c1 >> r2 >> c2;
    Mod ans = get(r2, c2) - get(r1 - 1, c2) - get(r2, c1 - 1) + get(r1 - 1, c1 - 1);
    cout << ans.x;
}

