void solve()
{
	READ(llong, L, T, R, B);
	R++;
	B++;

	const llong MOD = 1000000007;
	ModCombination m(2000001, MOD);

	auto lt = m.Fact(L + T) * m.modFactInv[L] % MOD * m.modFactInv[T] % MOD;
	auto rb = m.Fact(R + B) * m.modFactInv[R] % MOD * m.modFactInv[B] % MOD;
	auto lb = m.Fact(L + B) * m.modFactInv[L] % MOD * m.modFactInv[B] % MOD;
	auto rt = m.Fact(R + T) * m.modFactInv[R] % MOD * m.modFactInv[T] % MOD;

	WRITE((rb + lt - lb - rt) % MOD);

#if 0
	int cnt = 1;
	int W = R - L + 1;
	int H = B - T + 1;

	llong num = 1;
	FOR(i, L+T, R+B+1)
	{
		int k = cnt - max(0, cnt - W) - max(0, cnt - H);
		num += modPow(m.Fact(i), k, MOD);
		num %= MOD;
		cnt++;
	}

	llong denom = 1;
	FOR(i, L, R + 1)
	{
		denom *= modPow(m.Fact(i), H, MOD);
		denom %= MOD;
	}

	FOR(i, T, B + 1)
	{
		denom *= modPow(m.Fact(i), W, MOD);
		denom %= MOD;
	}

	llong ans = num * modInvPrime(denom, MOD);
	ans %= MOD;
	WRITE(ans);
#endif
}

