LL expo(LL a, LL x) {
	if(x == 0) {
		return 1;
	}
	LL ret = expo(a, x/2);
	ret = (ret * ret)%MOD;
	if(x%2 != 0) {
		ret = (ret * (a%MOD))%MOD; 
	}
	return ret;
}

LL fact[MX], ifact[MX];
void aux() {
