	for(int i=1;i<MX;i++) {
		fact[i] = (fact[i-1] * i)%MOD;
		// ifact[i] = expo(fact[i], MOD-2);
	}
	ifact[MX-1] = expo(fact[MX-1], MOD-2);
	for(int i=MX-2;i>=0;i--) {
		ifact[i] = (ifact[i+1] * (i+1))%MOD;
	}
}

LL ncr(int n, int r) {
	if(r > n || r < 0) return 0;
	LL ret = ((fact[n] * ifact[n-r])%MOD * ifact[r])%MOD;
	return ret;
}

