ll comb(ll a, ll b) {
	static constexpr ll size = 3 * 1e6;
	static VL fac(size);
	static VL finv(size);
	static VL inv(size);
	static ll n = 0;
	static auto mod = [](ll x, ll m = MOD) {
		return (x > m) ? x % m : x;
	};
	if (n > a) {
		return mod(fac[a] * mod(finv[b] * finv[a - b]));
	}
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	FOR(i, 2, a + 1) {
		inv[i] = MOD - mod(inv[MOD % i] * (MOD / i));
		fac[i] = mod(fac[i - 1] * (ll)i);
		finv[i] = mod(finv[i - 1] * inv[i]);
	}
	n = a + 1;
	return comb(a, b);
}



