const int mod = 1e9+7;
const int MAX = 2000100;

ll fc[MAX]; // fc[i] := iの階乗
ll fci[MAX]; // fci[i] := iの階乗の逆元

ll modpow(ll a, ll b) {
    if ( ! b) return 1;
    if (b % 2) return (a * modpow(a, b-1)) % mod;
    ll t = modpow(a, b/2);
    return (t * t) % mod;
}

void init_fact() {
    fc[0] = fc[1] = 1;
    for (int i=2; i<MAX; ++i) {
        fc[i] = (fc[i-1] * i) % mod;
    }
    fci[0] = fci[1] = 1;
    for (int i=2; i<MAX; ++i) {
        fci[i] = (fci[i-1] * modpow(i, mod-2)) % mod;
    }
}

ll sum(int r, int c) {
    if (r < 0 || c < 0) return 0;
    ll res = 0;
    for (int i=1; i<=r+1; ++i) {
        ll x = 1;
        x *= fc[i+c];
        x %= mod;
        x *= fci[i];
        x %= mod;
        x *= fci[c];
        x %= mod;
        res += x;
        res %= mod;
    }
    return res;
}

int main() {
    init_fact();

    ll r1, c1, r2, c2;    
