    ans += sum(r2, c2);
    ans %= mod;
    ans += mod - sum(r2, c1-1);
    ans %= mod;
    ans += mod - sum(r1-1, c2);
    ans %= mod;
    ans += sum(r1-1, c1-1);
    ans %= mod;
    cout << ans << endl;

    return 0;
}

