class Combination {
public:
    vector <ll> fac, inv, fiv;

    Combination(int N) : fac(N + 1), inv(N + 1), fiv(N + 1) {
        fac[0] = inv[0] = fiv[0] = fac[1] = inv[1] = fiv[1] = 1;
        for (ll i = 2; i <= N; i++) {
            fac[i] = fac[i - 1] * i % MOD; // n!
            inv[i] = inv[MOD % i] * (MOD - MOD / i) % MOD; // n^-1
            fiv[i] = fiv[i - 1] * inv[i] % MOD; // (n!)^-1
        }
    }

    ll C(ll n, ll k) {
        if (k < 0 || n < k) return 0;
        return fac[n] * fiv[k] % MOD * fiv[n - k] % MOD;
    }
};

int main() {
    cin.sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    ll r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;

    Combination com(2000005);

    ll cur = com.C(r1 + c1, r1);
    ll ans = cur;
    ll mn = r1, mx = r1;
    for (int i = r1 + c1 + 1; i <= r2 + c2; i++) {
        cur = cur * 2 % MOD;

        ll new_mn = max(r1, i - c2);
        if (new_mn == mn) {
            cur += com.C(i - 1, mn - 1);
        } else {
            cur -= com.C(i - 1, mn);
        }
        mn = new_mn;

        ll new_mx = min(r2, i - c1);
        if (new_mx == mx) {
            cur -= com.C(i - 1, mx);
        } else {
            cur += com.C(i - 1, mx + 1);
        }
        mx = new_mx;

        cur = (cur + MOD) % MOD;
        ans = (ans + cur) % MOD;
    }

    cout << ans << "\n";
    return 0;
}

