}
vector<int> fact, rev_fact;
void setFact(int n)
{
    fact.resize(n);
    rev_fact.resize(n);
    fact[0] = 1;
    for (int i = 1; i < n; i++)
    {
        fact[i] = fact[i - 1] * i;
        fact[i] %= MOD;
    }
    rev_fact[n - 1] = modpow(fact[n - 1], MOD - 2);
    for (int i = n - 2; i >= 0; i--)
    {
        rev_fact[i] = rev_fact[i + 1] * (i + 1);
        rev_fact[i] %= MOD;
    }
}
int getCombination(int a, int b)
{
    return (((fact[a] * rev_fact[b]) % MOD) * rev_fact[a - b]) % MOD;
}

