const int MAX = 2000001;
const int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
/* end */

long long sumCOM(int n, int k) { // (1, 1) start.
  if (n <= k) return 0;
  if (n <= 0 || k <= 0) return 0;
  return COM(n+2, k+1) - k - (n-k);
}

int main(void) {
  int r_1, c_1, r_2, c_2;
  cin >> r_1 >> c_1 >> r_2 >> c_2;
  r_1--; c_1--;

  COMinit();

  long long ans = sumCOM(r_2+c_2, c_2) + sumCOM(r_1+c_1, c_1) - sumCOM(r_1+c_2, c_2) - sumCOM(r_2+c_1, c_1);
  while (ans < (long long)0) {
    ans += MOD;
  }
  ans %= MOD;

  cout << ans << endl;

  return 0;
}

