ll fact[MAXIN] = { 0 };

int my_main(int argc, char** argv)
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;

    fact[0] = 1;
    for (int i = 1; i < MAXIN; i++)
        fact[i] = (i * fact[i - 1]) % MOD;

    std::unordered_map<ll, ll> inv_map;
    auto memo_mod_inv = [&inv_map](ll n) {
        auto it = inv_map.find(n);
        if (it != inv_map.end())
            return it->second;
        else {
            return inv_map[n] = mod_inv(n, MOD);
        }
    };

    map<pair<ll, ll>, ll> combi_map;
    auto combi = [&](ll n, ll k) -> ll {
        const auto key = make_pair(n, k);
        auto it = combi_map.find(key);
        if (it != combi_map.end())
            return it->second;

        ll ret = 1;
        ret = ret * fact[n] % MOD;
        ret = ret * memo_mod_inv(fact[n - k]) % MOD;
        ret = ret * memo_mod_inv(fact[k]) % MOD;

        return combi_map[key] = ret;
    };

    auto g = [&](int r, int c) {
        ll ret = 0;
        for (int i = 1; i <= r + 1; i++) {
            ret += combi(c + i, (ll)i);
            ret %= MOD;
        }
        return ret;
    };

    ll ret = g(r2, c2);
    ret -= g(r2, c1 - 1);
    ret = (ret + MOD) % MOD;
    ret -= g(r1 - 1, c2);
    ret = (ret + MOD) % MOD;

    ret += g(r1 - 1, c1 - 1);
    ret %= MOD;

    cout << ret << endl;
    return 0;
}

