ll fastExp(ll base, ll exp)
{
    if(exp == 0LL)
    {
        return 1LL;
    }

    if(exp%2==0)
    {
        return fastExp(times(base, base), exp/2);
    }
    else
    {
        return times(base, fastExp(times(base, base), exp/2));
    }
}

ll choose( ll n, ll k )
{
    if (k > n)
        return 0LL;
    if (k * 2 > n)
        k = n-k;
    if (k == 0)
        return 1LL;

    ll result = n;
    for( ll i = 2; i <= k; ++i )
    {
        result = times(result, n-i+1);
        result = times(result, fastExp(i, MOD-2));
    }
    return result;
}


