long long ksm(long long x,long long y)
{
	x %= MOD;
	long long rt = 1LL;
	while ( y )
	{
		if ( y & 1 )
			rt = rt * x % MOD;
		x = x * x % MOD;
		y >>= 1;
	}
	return rt;
}

int C(int n,int m)
{
	if ( n < m )
		return 0;
	long long rt = 1LL;
	for ( int i = 0 ; i < m ; i++ )
		rt = rt * (long long)(n-i) % (long long)MOD * ksm(i+1,MOD-2) % (long long)MOD;
	return (int)rt;
}

