  }
}

ll conv(int n, int k){
  ll res = 1LL;
  res = (res * f[n]) % mod;
  res = (res * finv[n-k]) % mod;
  res = (res * finv[k]) % mod;
  return res;
}

ll calc(int r, int c){
  ll res = 0LL;
  for(int i = 0;i <= c;++i){
    res = (res + conv(r+i+1, r)) % mod;
  }
  return res;
}


