const int mod = (int)1e9 + 7;
const int N = (int)4e6 + 123;

int fact[N];

int mult(int a, int b)
{
	return 1ll * a * b % mod;
}

int add(int a, int b)
{
	a += b;
	if(a < 0) a += mod;
	if(a >= mod) a %= mod;
	return a;
}

int Binpow(int a, int n)
{
	if(!n) return 1;
	if(n & 1) return mult(Binpow(a, n - 1), a);
	else
	{
		int b = Binpow(a, n / 2);
		return mult(b, b);
	}
}

int C(int n, int k)       
{
	if(k > n) return 0;
	int up = fact[n];
	int down = mult(fact[k], fact[n - k]);
	return mult(up, Binpow(down, mod - 2));
}

int Get(int n, int k, int z)
{
	int all = C(n + z + 1, z + k);
	int pre = C(n, k - 1);
	return add(all, -pre);
}

