ll calc_init(ll r, ll c)
{
    ll ret = 1LL;
    ret *= perms[r+c];
    ret %= MOD;
    ret *= perm_invs[r];
    ret %= MOD;
    ret *= perm_invs[c];
    ret %= MOD;
    debug_printf("init r=%lld c=%lld ret=%lld\n", r, c, ret);
    return ret;
}

ll calc_total(ll r, ll c)
{
    ll total = 0LL;
    total += powsums[r+c+2LL];
    total %= MOD;

    ll decr = 0LL;

    rep (rp, r+1LL) {
        ll cnt = calc_init(rp, c);
        cnt *= powsums[r+1-rp];
        cnt %= MOD;
        decr += cnt;
        decr %= MOD;
    }

    rep (cp, c+1LL) {
        ll cnt = calc_init(r, cp);
        cnt *= powsums[c+1-cp];
        cnt %= MOD;
        decr += cnt;
        decr %= MOD;
    }

    total -= decr;
    while (total < 0LL) total += MOD;
    return total;
}

