struct constexpr_inv{
  long long inv[N + 1] , fac[N + 1] , finv[N + 1];
  constexpr_inv() : inv() , fac() , finv(){
    fac[0] = fac[1] = finv[0] = finv[1] = inv[1] = 1;
    for (int i = 2; i <= N; i++){
      fac[i] = fac[i - 1] * i % MOD;
      inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
      finv[i] = finv[i - 1] * inv[i] % MOD;
    }
  }
};

