    }
}
// 二項係数計算 O(1)
long long modcom(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}
ll solve(ll n,ll r,ll k){
    if(k==0)return 0;
    ll res=modcom(n,r);
    ll b=res;
    rep(i,k-1){
        b=(b*2+modcom(n+i,r-1)+modcom(n+i,r+i+1))%mod;
        res+=b;
        res%=mod;
    }
    return res;
}
