int exp(int x, int n)
{
	int tmp;
	if (n == 0) return 1;
	tmp = exp(x, n / 2);
	tmp = 1LL * tmp * tmp % MOD;
	if (n % 2) tmp = 1LL * tmp * x % MOD;
	return tmp;
}

int calc(int n, int m)
{
	return 1LL * f[n] * fr[m] % MOD * fr[n-m] % MOD;
}

