int fast_power(int a, int b) {
  long long p = 1, q = a;
  while (b) {
    if (b & 1)
      p = p * q % mod;
    q = q * q % mod;
    b >>= 1;
  }
  return p;
}

void factorial(int n) {
  f.push_back(1);
  g.push_back(1);
  for (int i = 1; i <= n; i++) {
    f.push_back(1LL * f[i - 1] * i % mod);
    g.push_back(fast_power(f[i], mod - 2));
  }
}

long long h(int r, int c) {
  if (r > c) swap(r, c);

  long long res = 0;
  for (int i = 1; i <= r + 1; i++)
    res = (res + 1LL * f[c + i] * g[i] % mod * g[c] % mod) % mod;
  return res;
}

