long long MOD = 1000000007;
long long binary_pow(long long x, long long deg){
    if (deg == 1){
        return (x % MOD);
    }
    if (deg == 0){
        return 1;
    }
    if (deg % 2 == 0){
        long long t = binary_pow(x, deg / 2) % MOD;
        return (t*t) % MOD;
    }
    if (deg % 2 == 1){
        long long t = binary_pow(x, (deg - 1) / 2) % MOD;
        return (t * t * x) % MOD;
    }
}
long back(long long x){
    return binary_pow(x, MOD - 2);
}
