ll cmb(ll x, ll y){
    if(y>x||y<0) return 0LL;
    ll c = 1;
    for(ll i = 0LL; i < y; i++) {
        c *= (x-i)%mod;
        c %= mod;
        c *= pow(i+1,mod-2,mod);
        c%= mod;
    }
    return c;
}

