// a>=0, b>=0, x*a+y*b=gcd>=0, a>0,b>0=>abs(y)<=a,abs(x)<=b
LL gcdex(LL a,LL b,LL& x, LL& y){
	LL ax=1,ay=0;
	LL bx=0,by=1;
	while(b){
		LL r=a/b;
		LL t=a-r*b; a=b; b=t;
		LL tx=ax-r*bx; ax=bx; bx=tx;
		LL ty=ay-r*by; ay=by; by=ty;
	}
	x=ax;
	y=ay;
	return a;
}
LL modinv(LL a, LL mod){
	LL x,y;
	gcdex(a,mod,x,y);
	if(x<0){
		x+=mod;
	}
	return x;
}

template<int S>
struct Comb
{
	LL f[S+1];
	LL r[S+1];
	LL mod;
	Comb(int m)
	{
		mod=m;
		f[0]=1;
		r[0]=1;
		for(LL i=1;i<=S;i++){
			f[i]=i*f[i-1]%m;
			r[i]=modinv(i,m)*r[i-1]%m;
		}
	}
	LL c(int n,int i){
		if(i<0&&n<i)
		{
			assert(0);
			return 0;
		}
		return f[n]*r[i]%mod*r[n-i]%mod;
	}
};
Comb<N> comb(M);
LL C(int n,int i){
	return comb.c(n,i);
}

LL f(LL a, LL b)
{
	LL ret=0;
	for(int i=b+1;i<=a+b+1;i++){
		ret+=C(i,b);
		ret%=M;
		//cerr << i << ", " << b << ", " << C(i,b) << endl;
	}
	//cerr << a << ", " << b << ": " << ret << endl;
	return ret%M;
}
void solve(std::vector<long long> r, std::vector<long long> c){
	cout << (f(r[1],c[1])+M-f(r[0]-1,c[1])+M-f(r[1],c[0]-1)+f(r[0]-1,c[0]-1))%M << endl;

}

