#include <bits/stdc++.h>
#define ll long long
#define MAX 1000005
#define P ((ll)1e9+7)
using namespace std;

ll qpow(ll a, ll n){
    ll res = 1;
    while(n){
        if(n&1) res = res*a%P;
        a = a*a%P;
        n >>= 1;
    }
    return res;
}

ll fac[MAX], inv[MAX];

void init(){
    fac[0] = 1;
    for(int i = 1; i < MAX; i++){
        fac[i] = fac[i-1]*i%P;
    }
    inv[MAX-1] = qpow(fac[MAX-1], P-2);
    for(int i = MAX-2; i >= 0; i--){
        inv[i] = inv[i+1]*(i+1)%P;
    }
}

ll C(ll n, ll m){
    if(!m) return 1;
    return fac[n]*inv[m]%P*inv[n-m]%P;
}

ll calc(ll x, ll l, ll r){
    return (C(r+1, x+1)-C(l, x+1)+P)%P;
}

int main()
{
    init();
    ll x1, y1, x2, y2, ans = 0;
    cin >> x1 >> y1 >> x2 >> y2;
    for(int i = x1; i <= x2; i++){
        ans = (ans+calc(i, i+y1, i+y2))%P;
    }
    cout << ans << endl;

    return 0;
}

