ll Pow(ll A, ll N){
  if (N == 0){
    return 1;
  }else{
    if (N % 2 == 0){
      return Pow(A * A % nmax, N / 2) % nmax;
    }else{
      return A * Pow(A * A % nmax, N / 2) % nmax;
    }
  }
}

int main(){
  ll R1, C1, R2, C2;
  cin >> R1 >> C1 >> R2 >> C2;

  vector <ll> kaijou(2e6 + 5), gyakugen(2e6 + 5);

  kaijou[0] = 1;
  for (ll i = 1; i < 2e6 + 5; i++){
    kaijou[i] = kaijou[i - 1] * i;
    kaijou[i] %= nmax;
  }

  for (ll i = 0; i < 2e6 + 5; i++){
    gyakugen[i] = Pow(kaijou[i], nmax - 2);
    gyakugen[i] %= nmax;
  }

  ll ans = 0;

  ll now = kaijou[R2 + C2 + 2] * gyakugen[R2 + 1]; now %= nmax;
  now *= gyakugen[C2 + 1]; now %= nmax;
  ans += now;

  now = kaijou[R2 + C1 + 1] * gyakugen[R2 + 1]; now %= nmax;
