  ans -= now;

  now = kaijou[R1 + C2 + 1] * gyakugen[C2 + 1]; now %= nmax;
  now *= gyakugen[R1]; now %= nmax;
  ans -= now;

  now = kaijou[R1 + C1] * gyakugen[R1]; now %= nmax;
  now *= gyakugen[C1]; now %= nmax;
  ans += now;

  ans %= nmax; ans += nmax;
  ans %= nmax;

  cout << ans << endl;

