ll bigmod(ll a, ll b, ll m){
	a%=m;
	ll res = 1;
	while(b > 0){
		if(b&1)	res=(res*a)%m;
		a = (a*a)%m;
		b >>= 1;
	}
	return res;
}

void precompute(){
	inv[1] = 1;
	for (int i = 2; i < MAX; ++i){
		inv[i] = bigmod(i, p-2, p);
	}
	fact[1] = 1;
	for (int i = 2; i < MAX; ++i){
		fact[i] = (i*fact[i-1])%p;
	}
	invf[0] = 1;
	invf[1] = 1;
	for (ll i = 2; i < MAX; ++i){
		invf[i] = ((inv[i]%p) * (invf[i-1])%p) % p;
	}
}

ll nCr(ll n,ll r)
{
    ll c=(invf[r]*invf[n-r])%p;
    return (fact[n]*c)%p;
}

