    	fact[i] = (i * fact[i - 1]) % mod;
}
ll give(ll x , ll y)
{
	ll res = 0;
	ll t = power(fact[y] , mod - 2 , mod);
	for(ll i = 1 ; i <= x + 1 ; i++ )
 	{
 		res = ( res + ( (fact[i + y] * t  % mod) * power(fact[i] , mod - 2 , mod) % mod) ) % mod;
 	}
 	return res ;
}
int main()
{
