template <typename T>
class Combination {
 public:
  vector<T> f, invf;

  Combination(int n) : f(n + 1, 1), invf(n + 1, 1) {
    for (int i = 1; i < n + 1; i++) {
      f[i] = f[i - 1] * i;
    }
    invf[n] /= f[n];
    for (int i = n; i > 0; i--) {
      invf[i - 1] = invf[i] * i;
    }
  }

  // nCr
  const T operator()(int n, int r) const {
    if (r < 0 || n < r) return 0;
    return f[n] * invf[r] * invf[n - r];
  }
};

