void treeDFS(int from, int current, int dist, int &maxDist, int &maxVertex)
{
    if (dist > maxDist)
    {
        maxDist = dist;
        maxVertex = current;
    }

    for (auto to : G[current])
    {
        if (to == from)
            continue;
        treeDFS(current, to, dist + 1, maxDist, maxVertex);
    }
}

pair<int, int> getTreeDiameter()
{
    int start = 0, end = 0, maxDist = 0;
    treeDFS(-1, start, 0, maxDist, end);
    start = end, end = 0, maxDist = 0;
    treeDFS(-1, start, 0, maxDist, end);
    return make_pair(start, end);
}

ll dp[100010][100010];

void solve(std::vector<long long> r, std::vector<long long> c)
{
    dp[0][0] = 1;
    for (int i = 0; i <= max(r[0], r[1]); i++)
    {
        for (int j = 0; j <= max(c[0], c[1]); j++)
        {
            dp[i + 1][j] += dp[i][j];
            dp[i][j + 1] += dp[i][j];
            dp[i + 1][j] %= MOD;
            dp[i][j + 1] %= MOD;
        }
    }
    for (int i = 0; i <= max(r[0], r[1]); i++)
    {
        for (int j = 0; j <= max(c[0], c[1]); j++)
        {
            if (i >= 1)
            {
                dp[i][j] += dp[i - 1][j];
                dp[i][j] %= MOD;
            }
        }
    }
    for (int i = 0; i <= max(r[0], r[1]); i++)
    {
        for (int j = 0; j <= max(c[0], c[1]); j++)
        {
            if (j >= 1)
            {
                dp[i][j] += dp[i][j - 1];
                dp[i][j] %= MOD;
            }
        }
    }

    cout << dp[r[1]][c[1]] - dp[r[1]][c[0] - 1] - dp[r[0] - 1][c[1]] + dp[r[0] - 1][c[0] - 1] << endl;
}

