//Solution

int binpow(int x,int y){
    x %= mod;
    int res = 1;
    while(y){
        if(y&1) res = (res*x)%mod;
        x = (x*x)%mod;
        y = y/2;
    }
    return res;
}

int inv(int a){
    return binpow(a,mod-2);
}

int fact[N], invfact[N];

void precompute(){
    fact[0] = 1;
    for(int i=1;i<N;i++) fact[i] = (fact[i-1]*i)%mod;
    invfact[N-1] = inv(fact[N-1])%mod;
    for(int i=N-2;i>=0;i--) invfact[i] = (invfact[i+1]*(i+1))%mod;
}

int ncr(int n, int r){
    if(n<r) return 0;
    return (((fact[n]*invfact[r])%mod)*invfact[n-r])%mod;
}

int g(int x,int y){
    int ret = ncr(x+y+2,x+1);
    ret--;
    ret += mod;
    ret %= mod;
    return ret;
}

void solve(){
    precompute();
    int r1,c1,r2,c2;
    cin>>r1>>c1>>r2>>c2;
    int ans = g(r2,c2);
    ans = (ans-g(r2,c1-1)+mod)%mod;
    ans = (ans-g(r1-1,c2)+mod)%mod;
    ans = (ans+g(r1-1,c1-1))%mod;
    cout<<ans<<endl;
}

