template<typename RET = mint, typename Integral>
RET combination(Integral all, Integral get)
{
	assert(all >= get);
	get = std::min(all - get, get);
#if 1
	//時間計算量O(1)+初期化O(NlogMOD)
#ifdef _DEBUG
	static const auto fact_v = fact_set_c<30000 + 1>();
#else
	static const auto fact_v = fact_set_c<3000000 + 1>();
#endif
	static const auto fact_div_v = [&]() {
		auto tmp = fact_v;
		for (auto& i : tmp) { i = ~i; }
		return tmp;
	}();
	//return fact_v[all] / (fact_v[get] * fact_v[all - get]);
	return fact_v[all] * fact_div_v[get] * fact_div_v[all - get];
#elif 0
	//時間計算量O(1)
	//空間計算量、初期化時間計算量O(N^2)
	constexpr int32_t ALL_MAX = 要素数;// 10'000;
	static std::vector<RET> DP_comb[ALL_MAX + 1];
	if (!DP_comb[all].empty())
	{
		return DP_comb[all][get];
	}

	if (DP_comb[0].empty())
	{
		DP_comb[0].resize(1);
		DP_comb[0][0] = (RET)1;
		DP_comb[1].resize(1);
		DP_comb[1][0] = (RET)1;
	}
	for (int32_t i = 2; i <= all; i++)
	{
		if (DP_comb[i].empty())
		{
			int32_t size = i / 2 + 1;
			DP_comb[i].resize(size);
			DP_comb[i][0] = (RET)1;
			for (int32_t j = 1; j < size - 1; j++)
			{
				DP_comb[i][j] = DP_comb[i - 1][j - 1] + DP_comb[i - 1][j];
			}
			DP_comb[i][size - 1] = DP_comb[i - 1][size - 2] + DP_comb[i - 1][(i & 1) ? (size - 1) : (size - 2)];
		}
	}
	return DP_comb[all][get];
#else
	//時間計算量O(get * logMOD)
	RET ret = (RET)1;
	for (Integral i = 1; i <= get; ++i)
	{
		ret *= all + 1 - i;
		ret /= i;
	}
	return ret;
#endif
}


mint solve(int R, int C)
{
	if (R < C) {
		std::swap(C, R);
	}
	assert(C <= R);

	mint sum = 0;
	mint now = 1;
	mint add = 0;
	for (int i = 0; i < C; i++)
	{
		sum += now;
		now += now;
	}
	for (int i = C; i < R; i++)
	{
		auto mv = combination(i, i - C);
		now += add - mv;
		sum += now;
		now += now;
		add = mv;
	}
	for (int i = R; i < C + R - 1; i++)
	{
		now += add;
		now -= combination(i, i - C);
		now -= combination(i, i - R);
		sum += now;
		now += now;

		add = combination(i, i - C)+combination(i, i - R);
	}
	std::cerr << now + add - combination(C + R-1, C) - combination(C + R-1, R) << std::endl;
	return sum;
}

