int main()
{
    ll r1,c1,r2,c2;
    cin >> r1 >> c1 >> r2 >> c2;
    const ll m = 1e9+7;
    ll n = r2+c2+2;

    auto mpow = [](ll x, ll y, ll m)
    {
        ll ret = 1;
        while(y!=0)
        {
            if(y&1) ret = (ret*x) % m;
            x = (x*x) % m;
            y = y >> 1;
        }
        return ret;
    };

    vector<ll> fac(n+1, 1); // n! % m
    vector<ll> finv(n+1, 1); // 1/k! % m = k!^(m-2) % m
    for(int i=0;i<n;++i)
    {
        fac[i+1] = (fac[i]*(i+1)) % m;
        finv[i+1] = (finv[i]*mpow(i+1, m-2, m)) % m;
    }

    auto mcomb = [&](ll r, ll c) {
        ll kf_inv = (finv[r-c]*finv[c]) % m;
        return (fac[r]*kf_inv) % m;
    };

    ll ans = mcomb(r2+c2+2,r2+1) - mcomb(r1+c2+1,r1) - mcomb(r2+c1+1,c1) + mcomb(r1+c1,r1);
    ans = (ans + 2*m) % m;

    cout << ans << endl;
    return 0;
}

