ll power(ll x,ll y){
	ll ans = 1;
	while (y > 0){
		if (y & 1) ans *= x;
		y /= 2;
		x *= x;
		x %= mod;
		ans %= mod;
	}
	return ans;
}

ll func(ll c,ll r){
	ll ans = 0;
	for (int z=1;z<=r+1;z++){
		ans += ((fact[z+c]*power(fact[z],mod-2))%mod*power(fact[c],mod-2))%mod;
		ans %= mod;
	}
	return ans;
}

