// ===================### mod関係 ###=================== //
// n%pのサイズの階乗配列を準備するか
bool USE_KAIJO_ARRAY = true;
const ll MAX_KAIJO_N = 2000100;
ll kaijo[MAX_KAIJO_N];
ll extgcd(ll a, ll b, ll &x, ll &y) {
    ll g = a;
    x = 1;
    y = 0;
    if (b != 0)
        g = extgcd(b, a % b, y, x), y -= (a / b) * x;
    return g;
}
ll modinv(ll a, ll m) {
    ll x, y;
    extgcd(a, m, x, y);
    return (m + x % m) % m;
}
ll modfact(ll n, ll p, ll &e) {
    e = 0;
    if (n == 0)
        return 1LL;
    ll ret = modfact(n / p, p, e);
    e += n / p;
    ll kai;
    if (USE_KAIJO_ARRAY) {
        kai = kaijo[n % p];
    } else {
        kai = 1;
        rep1(i, n % p) {
            kai = (kai * i) % p;
        }
    }
    if (n / p % 2 != 0)
        return ret * (p - kai) % p;
    return ret * kai % p;
}
ll modcomb(ll n, ll k, ll p) {
    if (n < 0 || k < 0 || n < k)
        return 0;
    ll e1, e2, e3;
    ll a1 = modfact(n, p, e1), a2 = modfact(k, p, e2), a3 = modfact(n - k, p, e3);
    if (e1 > e2 + e3)
        return 0;
    return a1 * modinv(a2 * a3 % p, p) % p;
}

