// パスカルの三角形のr行,c列目を返す関数
ll pasc(ll r, ll c) {
    if (c > r) {
        swap(r, c);
    }
    ll n = r + c - 1;
    ll k = c;
    return modcomb(n - 1, k - 1, M);
}

signed main() {
    kaijo[0] = 1LL;
    rep1(i, MAX_KAIJO_N) {
        kaijo[i] = (kaijo[i - 1] * i) % M;
    }
    ll r1, c1, r2, c2;
    scanf("%lld%lld%lld%lld", &r1, &c1, &r2, &c2);
