struct mint {
    long long x;
    mint(long long x=0) : x((x%mod+mod)%mod) {}
    mint operator-() const {
      return mint(-x);
    }
    mint& operator+=(const mint& a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint& a) {
        if ((x += mod-a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const  mint& a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint& a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint& a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint& a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }
    mint inv() const {
        return pow(mod-2);
    }
    mint& operator/=(const mint& a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint& a) const {
        mint res(*this);
        return res/=a;
    }
    friend ostream& operator<<(ostream& os, const mint& m){
        os << m.x; return os;
    }
};

struct Factorial{
    vector<mint> fact;
    vector<mint> factinv;
    Factorial(ll n){
        fact = vector<mint>(n+1);
        factinv = vector<mint>(n+1);
        fact[0] = 1;
        REP(i,1,n+1) fact[i] = fact[i-1] * i;
        factinv[n] = fact[n].inv();
        RREP(i,1,n+1) factinv[i-1] = factinv[i] * i;
    }
    mint C(ll n, ll k){
        if(k<0 || k>n) return 0;
        return fact[n] * factinv[n-k] * factinv[k];
    }
    mint P(ll n, ll k){
        if(k<0 || k>n) return 0;
        return fact[n] * factinv[n-k];
    }
    mint H(ll n, ll k){
        if(n==0 && k==0) return 1;
        return C(n+k-1, k);
    }
};

