    cin >> lef >> dwn >> rig >> up;
    int sum = binom(rig + up, rig), ans = sum;
    int dx = rig - lef + 1, dy = up - dwn + 1;
    loop1(i, dx + dy - 2) {
        if (dx > i)
            sum = (sum + binom(rig + up - i, rig - i)) % MOD;
        else
            sum = (sum - binom(rig + up - i, lef - 1) + MOD) % MOD;
        if (dy > i)
            sum = (sum + binom(rig + up - i, up - i)) % MOD;
        else
            sum = (sum - binom(rig + up - i, dwn - 1) + MOD) % MOD;
        sum = sum * rev2 % MOD;
        ans = (ans + sum) % MOD;
    }
    cout << ans;
