long long power(long long x, long long y) {
    long long res = 1;
    x = x % MOD;

    if (x == 0) return 0;
    while (y > 0) {
        if (y & 1) res = (res*x) % MOD;
        y = y >> 1;
        x = (x*x) % MOD;
    }
    return res % MOD;
}

