int pick(long long int m,long long int n){
  //値が入っている
  if(map[m][n] != 0){
    return map[m][n]
  }
  //mCn = mCn-n
  if(map[m][m-n] != 0){
    return map[m][m-n];
  }
  //まだ値が入っていない
  map[m][n] = (pick(m-1,n-1) + pick(m-1,n))%F;
  return map[m][n];
}

