class Combinatons {
public:
    Combinatons(int n = 0) :fact(n + 1), rev(n + 1) {
        fact[0] = 1;
        for (int i = 1; i < n + 1; ++i)fact[i] = fact[i - 1] * i;
        for (int i = 0; i < n + 1; ++i)rev[i] = fact[i].inverse();
    }

    mint C(int n, int r) {
        if (n < r)return 0;
        return fact[n] * rev[r] * rev[n - r];
    }

    mint H(int n, int r) {
        return C(n + r - 1, r);
    }

    mint P(int n, int r) {
        if (r > n)return 0;
        return fact[n] * rev[n - r];
    }

    mint catalan(int n) {
        return fact[2 * n] * rev[n + 1] * rev[n];
    }

private:
    vector<mint> fact, rev;
};

void solve() {
    Combinatons comb(2000010);

    int R1, C1, R2, C2;
    cin >> R1 >> C1 >> R2 >> C2;
    mint ans = 0;
    for (int i = R1; i <= R2; ++i) {
        int lb = i + C1;
        int ub = i + C2;
        ans += comb.C(ub + 1, i + 1);
        ans -= comb.C(lb, i + 1);
    }
    cout << ans << endl;
}

