int modpower(int num, int mod, int to) {
  long ntemp = num;
  int ret = 1;
  for (int pow = 0; pow < 32; pow++) {
    if (to >> pow == 0) {
      return ret;
    }
    if ((to | 1 << pow) == to) {
      ret = (long)(ret * ntemp) % mod;
    }
    ntemp = (long)(ntemp * ntemp) % mod;
  }
  return ret;
}
int MOD = 1e9 + 7;
int modway(int r, int c) {
  int ret = ((long)factmod.at(r + c + 2) *
             modpower(factmod.at(r + 1), MOD, MOD - 2)) %
            MOD;
  ret = ((long)ret * modpower(factmod.at(c + 1), MOD, MOD - 2)) % MOD;
  return ret;
}

