int main()
{
    ll p = 1000000007;
    ll r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;
    vector<ll> fac, ifac;

    // calculate factorial
    fac.push_back(1);
    for (ll i = 1; i <= r2 + c2; i++) {
        ll t = fac[i - 1];
        t *= i;
        fac.push_back(t % p);
    }

    ll fac_t = fac[r2 + c2];
    ll ifac_max = 1;
    for (int i = 0; ((p - 2) >> i) > 0 ; i++) {
        if (((p - 2) >> i) & 1) {
            ifac_max *= fac_t;
            ifac_max %= p;
        }
        fac_t *= fac_t;
        fac_t %= p;
    }
    ifac.push_back(ifac_max);

    for (int i = 1; i <= r2 + c2; i++) {
        ll t = ifac[i - 1];
        t *= r2 + c2 - i + 1;
        ifac.push_back(t % p);
    }
    reverse(ifac.begin(), ifac.end());

    ll ans = 0;
    for (ll i = r1; i <= r2; i++) {
        for (ll j = c1; j <= c2; j++) {
            ll t = fac[i + j];
            t *= ifac[i];
            t %= p;
            t *= ifac[j];
            t %= p;
            ans += t;
            ans %= p;
        }
    }
    cout << ans << endl;

    return 0;
}

