struct Combination {
    vector<ll> kaijou;
    Combination() : kaijou(3001001, 1) {
        rep(i, 3001000) kaijou[i + 1] = (kaijou[i] * (i + 1)) % MOD;
    }
    ll modinv(ll a, ll m) {
        ll b = m, u = 1, v = 0;
        while (b) {
            ll t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        u %= m;
        if (u < 0) u += m;
        return u;
    }
    ll c(int x, int y) {
        if (x < y || y < 0) return 0;
        return kaijou[x] * modinv(kaijou[x - y] * kaijou[y], MOD) % MOD;
    }
    ll h(int x, int y) {
        return c(x + y - 1, y);
    }
    ll calc(int R, int C) {
        ll ret = 0;
        for (int k = 0; k <= C; k++) {
            ret += c(k + R + 1, k + 1);
            ret %= MOD;
        }
        return ret;
    }
};

