class Fp {
private:
    long long val;

public:
    static unordered_map<int, Fp> to_inv;
    Fp() { val = 0; }
    Fp(long long v) : val(v % mod) {
        if (val < 0)
            val += mod;
    }
    long long getVal() { return val; }
    Fp operator+=(const Fp in) {
        val += in.val;
        if (val >= mod)
            val -= mod;
        return *this;
    }
    Fp operator+(const Fp in) const {
        return Fp(*this) += in;
    }
    Fp &operator-=(const Fp in) {
        val -= in.val;
        if (val < 0)
            val += mod;
        return *this;
    }
    Fp operator-(const Fp in) const {
        return Fp(*this) -= in;
    }
    Fp &operator*=(const Fp in) {
        val = val * in.val % mod;
        return *this;
    }
    Fp operator*(const Fp in) const {
        return Fp(*this) *= in;
    }
    friend Fp operator*(const long long n, const Fp in) {
        return in * n;
    }
    Fp &operator/=(const Fp in) {
        *this *= (to_inv.count(in.val) ? to_inv[in.val] : (to_inv[in.val] = in.modpow(mod - 2)));
        //*this *= in.modpow(mod - 2);
        return *this;
    }
    Fp operator/(const Fp in) const {
        return Fp(*this) /= in;
    }
    bool operator==(const Fp in) const {
        return val == in.val;
    }
    bool operator!=(const Fp in) const {
        return val != in.val;
    }
    Fp modpow(long long n) const {
        if (n == 0)
            return 1;
        if (n & 1) {
            return (*this) * ((*this) * (*this)).modpow(n / 2);
        } else {
            return ((*this) * (*this)).modpow(n / 2);
        }
    }
    friend istream &operator>>(istream &is, Fp &fp) {
        is >> fp.val;
        return is;
    }
    friend ostream &operator<<(ostream &os, Fp &fp) {
        os << fp.val;
        return os;
    }
    friend ostream &operator<<(ostream &os, Fp &&fp) {
        os << fp.val;
        return os;
    }
};

