#include <stdio.h>
long long ra, rb, ca, cb;
long long p = 1000000007;
long long ans, x, y;
long long kai[2000100];
long long rui(long long rui_a, long long rui_b) {
	if (rui_b == 0)return 1;
	if (rui_b == 1)return rui_a % p;
	long long rui_c;
	rui_c = rui(rui_a, rui_b / 2);
	rui_c = rui_c * rui_c % p;
	if (rui_b % 2) {
		return rui_c * rui_a % p;
	}
	return rui_c;
}
int main() {
	kai[0] = 1;
	for (long long i = 1; i < 2000100; i++) {
		kai[i] = kai[i - 1] * i % p;
	}
	scanf("%lld%lld%lld%lld", &ra, &ca, &rb, &cb);
	for (long long i = ca; i <= cb; i++) {
		x = kai[i + rb + 1] * rui(kai[rb], p - 2) % p * rui(kai[i + 1], p - 2) % p;
		y = kai[i + ra] * rui(kai[ra - 1], p - 2) % p * rui(kai[i + 1], p - 2) % p;
		ans += x;
		ans -= y;
		if (ans < 0)ans += p;
		ans %= p;
	}
	printf("%lld\n", ans);
}

