const int MAX = 3000000;
const ll MOD = 1e9+7;
ll fac[MAX], finv[MAX], inv[MAX];

void combinit() {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}
ll comb(int n, int k) {
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll r1, c1, r2, c2;
int xleft(int x, int y) {
	return max(-c2+x+y,r1);
}
int yleft(int x, int y) {
	return min(-r1+x+y,c2);
}
ll morau(int x, int y) {
	ll ret = 0;
	if (x == r1)ret += comb(x+y-1, x-1);
	if (y == c1)ret += comb(x+y-1, y-1);
	return ret;
}
ll kubaru(int x, int y) {
	ll ret = 0;
	if (x != r2)ret += comb(x+y, y);
	if (y != c2)ret += comb(x+y, y);
	return ret;
}

