		ll sl = comb(xl+yl,yl);
		int fl = ((xr == xl) && (yr == yl));
		//貰うパート
		cursum += morau(xr,yr);
		if(!fl)cursum += morau(xl,yl);
		ans += cursum;
		//配るパート
		cursum = 2LL * (cursum - sr - ((!fl)?sl:0) + 10LL*MOD) % MOD;
		cursum += kubaru(xr,yr);
		if(!fl)cursum += kubaru(xl,yl);
		ans %= MOD;
		cursum %= MOD;
	}
	for (int yr = c1; yr <= c2; yr++) {
		int xr = r2;
		int xl = xleft(xr,yr);
		int yl = yleft(xr,yr);
		ll sr = comb(xr+yr,yr);
		ll sl = comb(xl+yl,yl);
		int fl = ((xr == xl) && (yr == yl));
		//貰うパート
		cursum += morau(xr, yr);
