struct Mod {
    static ll BASE;
    ll value = 0;
    static ll residue(ll value) { return (value % BASE + BASE) % BASE; }
    Mod()
    : value(0) {}
    Mod(ll value)
    : value(residue(value)) {}
    Mod operator+(const Mod& rhs) const { return Mod(value + rhs.value); }
    void operator+=(const Mod& rhs) { *this = *this + rhs; }
    Mod operator-(const Mod& rhs) const { return Mod(value - rhs.value); }
    void operator-=(const Mod& rhs) { *this = *this - rhs; }
    Mod operator*(const Mod& rhs) const { return Mod(value * rhs.value); }
    void operator*=(const Mod& rhs) { *this = *this * rhs; }
    static Mod power(Mod base, ll n) {
        assert(n >= 0);
        Mod ans(1);
        Mod pow(base);
        for (int i = 0; i < 63; i++) {
            if ((n >> i) & 1) {
                ans *= pow;
            }
            pow = pow * pow;
        }
        return ans;
    }
    Mod operator/(const Mod& rhs) const { return *this * rhs.inv(); }
    void operator/=(const Mod& rhs) { *this = *this / rhs; }
    Mod inv() const {
        assert(value != 0);
        return power(value, Mod::BASE - 2);
    }
    static ll gcd(ll x, ll y, ll* out_cx, ll* out_cy) {
        if (x < 0) {
            ll d = gcd(-x, y, out_cx, out_cy);
            if (out_cx) {
                *out_cx *= -1;
            }
            return d;
        }
        if (y < 0) {
            ll d = gcd(x, -y, out_cx, out_cy);
            if (out_cy) {
                *out_cy *= -1;
            }
            return d;
        }
        if (x > y) {
            return gcd(y, x, out_cy, out_cx);
        }
        if (x == 0) {
            if (out_cx && out_cy) {
                *out_cx = 0;
                *out_cy = 1;
            }
            return y;
        }
        ll q = y / x;
        ll r = y % x;
        ll d = gcd(r, x, out_cy, out_cx);
        if (out_cx) {
            *out_cx -= q * *out_cy;
        }
        return d;
    }
    static vector<vector<Mod>> binom_table(ll n) {
        vector<vector<Mod>> ans;
        auto get = [&ans](ll r, ll k) -> Mod {
            if (r < 0 || k < 0 || k > r) {
                return Mod(0);
            } else {
                return ans[r][k];
            }
        };
        ans.push_back({Mod(1)});
        for (ll r = 1; r <= n; r++) {
            ans.push_back(vector<Mod>());
            for (ll k = 0; k <= r; k++) {
                ans[r].push_back(get(r - 1, k) + get(r - 1, k - 1));
            }
        }
        return ans;
    }
};
ll Mod::BASE = 1000000007;

vector<Mod> fact_table;

Mod binom(ll n, ll k) {
    if (!(n >= 0 && 0 <= k && k <= n)) {
        return 0;
    }
    if (k == 0 || k == n) {
        return 1;
    }
    return fact_table[n] / fact_table[k] / fact_table[n-k];
}

Mod ans_for(ll I, ll J) {
    Mod ans = 0;
    rep(j,0,J+1) {
        ans += binom(j+1+I, I);
    }
    return ans;
}

