    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

ll f(int r, int c) {
  return ((r + 2) * COM(c + r + 2, r + 2) % mod - c - 1 + mod) % mod * modpow(c + 1, mod - 2) % mod;
}

