class mint {
public:
	static int mod;
	mint() : x(1) {}
	mint(int x_) : x(x_) {}

	mint operator +(mint rhs) {
		ll ans = ll(x) + ll(rhs.x);
		while(ans >= mod) ans -= mod;
		while(ans < 0) ans += mod;
		return ans; }

	mint operator -(mint rhs) {
		ll ans = ll(x) - ll(rhs.x);
		while(ans >= mod) ans -= mod;
		while(ans < 0) ans += mod;
		return ans; }

	mint operator *(mint rhs) {
		int ans = ll(x)*ll(rhs.x) % mod;
		while(ans < 0) ans += mod;
		return ans; }

	mint operator /(mint rhs) { return *this * inv(rhs); }

	mint& operator +=(mint rhs) { return *this = *this + rhs; }
	mint& operator -=(mint rhs) { return *this = *this - rhs; }
	mint& operator *=(mint rhs) { return *this = *this * rhs; }
	mint& operator /=(mint rhs) { return *this = *this / rhs; }

	friend ostream& operator <<(ostream& out, mint x) { return out<<x.x; }
	friend istream& operator >>(istream& in, mint& x) { return in>>x.x; }
	friend mint mpow(mint a, int n);
	friend mint inv(mint a);

private:
	int x;
};

mint mpow(mint a, int n) {
	if(n == 0) return 1;
	mint x = mpow(a, n/2);
	x *= x;
	if(n % 2 == 1) x *= a;
	return x;
}

mint inv(mint a) {
	return mpow(a, mint::mod - 2);
}

