  fact_table[0] = 1;
  fact_inverse[0] = 1;
  for(long long int i = 1; i < NMAX; i++){
    fact_table[i] = (fact_table[i-1]*i + MOD)%MOD;
    fact_inverse[i] = mod_inverse(fact_table[i], MOD);
  }

