ll mp(ll a, ll b) {
    if (b == 0) return 1LL;
    if (b == 1) return a;
    ll ret = mp(a,b/2);
    ret *= ret;
    ret %= mod;
    if (b&1) ret *= a;
    return ret % mod;
}

ll inv(ll k) {
    return mp(k,mod-2);
}

void init() {
    kai[0] = 1;
    kai[1] = 1;
    for (ll i = 2; i < (1 << 21); i++) {
        kai[i] = kai[i - 1] * i % mod;
        in[i] = inv(kai[i]);
    }
}

ll c(ll n, ll k) {
    if (k == 0) return 1;
    if (n == k) return 1;
    return kai[n] * in[k] % mod * in[n-k] % mod;
}


ll s(ll r, ll cc) {
    ll ret = 0;
    if (r < cc) return 0;
    for (int i = 0; i <= cc; i++) {
        ret += c(r - cc + i + 1, i + 1);
        ret %= mod;
    }
    return ret;
}

