void Init() {
	fac[1] = inv[1] = 1;
	for (int i = 2; i <= (int) 2e6 + 1; ++i) {
		fac[i] = 1ll * fac[i - 1] * i % mod;
		int res = mod % i, div = mod / i;
		inv[i] = 1ll * inv[res] * (mod - div) % mod;
	}
	for (int i = 2; i <= (int) 2e6 + 1; ++i)
		inv[i] = 1ll * inv[i] * inv[i - 1] % mod;
	fac[0] = inv[0] = 1;
}
