template <ll mod> class modint
{
public:
    modint(ll value = 0) : _value(value >= 0 ? value % mod : (value % mod) + mod) {}

    modint operator+() const { return *this; }
    modint operator-() const { return modint(-_value); }

    modint &operator+=(const modint &rhs) {
        if ((_value += rhs._value) >= mod) _value -= mod;
        return *this;
    }
    modint &operator-=(const modint &rhs) {
        if ((_value += mod - rhs._value) >= mod) _value -= mod;
        return *this;
    }
    modint &operator*=(const modint &rhs) {
        (_value *= rhs._value) %= mod;
        return *this;
    }
    modint &operator/=(const modint &rhs) {
        *this *= rhs.inv();
        return *this;
    }
    modint operator+(const modint &rhs) const { return modint(*this) += rhs; }
    modint operator-(const modint &rhs) const { return modint(*this) -= rhs; }
    modint operator*(const modint &rhs) const { return modint(*this) *= rhs; }
    modint operator/(const modint &rhs) const { return modint(*this) /= rhs; }

    modint operator++() { *this += 1; return *this; }
    modint operator--() { *this -= 1; return *this; }
    modint operator++(int) { modint tmp = *this; ++*this; return tmp; }
    modint operator--(int) { modint tmp = *this; --*this; return tmp; }

    bool operator==(const modint &rhs) const { return _value == rhs._value; }
    bool operator!=(const modint &rhs) const { return _value != rhs._value; }

    modint inv() const {
        ll a = _value, b = mod, u = 1LL, v = 0LL;
        while (b > 0) {
            ll tmp = a / b;
            a -= tmp * b; swap(a, b);
            u -= tmp * v; swap(u, v);
        }
        return modint(u);
    }

    modint pow(ll n) const {
        modint e = *this, res = 1;
        while (n) {
            if (n & 1) res *= e;
            e *= e, n >>= 1;
        }
        return res;
    }

    friend ostream &operator<<(ostream &os, const modint &m) {
        os << m._value;
        return os;
    }

    friend istream &operator>>(istream &is, modint &m) {
        ll in;
        is >> in;
        m = modint(in);
        return is;
    }

private:
    ll _value;
};
