inline long long M (long long X){
    if (X < MOD)
        return X;
    return X % MOD;
}
void E(long long a, long long b, long long &x, long long &y)
{
    if(!b)
    {
        y=0;
        x=1;
    }
    else
    {
        long long x0, y0;
        E(b, a%b, x0, y0);
        x = y0;
        y = x0 - (a / b) * y0;
    }
}

long long S (int a, int b){
    long long ans = 0;
    long long curr, curr1, x, y;
    if (a > b)
        swap (a, b);
    for (int it = 0; it < a; ++it){
        curr = M((b + 1) * v[b + it + 2]);
        curr1 = M(v[b + 1] * v[it + 2]);
        curr = (curr + MOD - curr1) % MOD;
        E(v[it + 2], MOD, x, y);
        while(x < 0)
            x += MOD;
        curr1 = x;
        E(v[b + 1], MOD, x, y);
        while(x < 0)
            x += MOD;
        curr1 = M(curr1 * x);
        curr = M(curr * curr1);
        ans = M (ans + curr);
    }
    return ans;
}

