ll fat[N];

void init(){
    fat[0] = 1LL;
    for(ll i = 1; i < N; i++){
        fat[i] = fat[i-1] % MOD * (ll) i % MOD;
        fat[i] %= MOD;
    }
}

ll fast(ll a, ll p){
    if(p == 1) return a % MOD;
    if(p&1) return ((a % MOD) * (fast(a, p-1) % MOD)) % MOD;
    int x = p / 2;
    ll t = fast(a, x);
    return ((t % MOD) * (t % MOD)) % MOD;
}

ll nck(ll n, ll k){
    if(n < k) return 0;
    if(k == 0) return 1;
    ll up = fat[n];
    ll a = fast(fat[k], MOD - 2);
    ll b = fast(fat[n-k], MOD - 2);

    ll prod = up % MOD * a % MOD;
    prod %= MOD;
    prod *= b;

    return prod % MOD;
}

ll g(ll r1, ll r2, ll c){
    ll a = nck(r2 + c + 1, c + 1);
    ll b = nck(r1 + c, c + 1);
    return (a - b) % MOD;
}

