const int Mod=1e9+7;
inline int MyPow(int a,int b){
    int ss=1;
    for(;b;b>>=1){
        if(b&1) ss=1ll*ss*a%Mod;
        a=1ll*a*a%Mod;
    }
    return ss;
}
inline int C(const int n,int m){
    if(n<m) return 0;
    if(n==m) return 1;
    if(m>n-m) m=n-m;
    int sn=1,sm=1;
    for(register int i=0;i<m;i++){
        sn=1ll*(n-i)%Mod*sn%Mod;
        sm=1ll*(m-i)%Mod*sm%Mod;
    }
    return 1ll*sn*MyPow(sm,Mod-2)%Mod;
}
inline int Lucas(const int n,const int m){
    if(!m) return 1;
    return 1ll*C(n%Mod,m%Mod)*Lucas(n/Mod,m/Mod)%Mod;
}
inline int Get(const int a,const int b){
    return Lucas(a+b,a);
}
