    ans = g(r2, c2);
    ans = (ans + MOD - g(r2, c1 - 1)) % MOD;
    ans = (ans + MOD - g(r1 - 1, c2)) % MOD;
    ans += g(r1 - 1, c1 - 1);
    ans %= MOD;
    cout << ans << endl;
}

