ll bigMode( ll base, ll b ){
    ll ans = 1;
    while( b ){
        if( b%2 == 1 ){
            ans = (ans*base)%MOD;
        }
        base = (base*base)%MOD;
        b /= 2;
    }
    return ans%MOD;
}

