//組み合わせの数nCrを計算
uint32_t calcNumOfCombination(uint32_t n, uint32_t r){
    uint32_t num = 1;
    for(uint32_t i = 1; i <= r; i++){
        num = num * (n - i + 1) / i;
        num = num % Div;
    }
    return num;
}

uint32_t get_path_num(uint32_t i, uint32_t j)
{
    uint32_t ret = 0;
    ret = calcNumOfCombination(i+j, std::min(i,j));
    return ret;
}


