#include <bits/stdc++.h>

using namespace std;

const int maxn = 2e6 + 5;
const int mod = 1e9 + 7;

long long fac[maxn], inv[maxn];

void init() {
    inv[1] = inv[0] = 1;
    fac[1] = 1;
    for (int i = 2; i < maxn; i++) {
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = (mod - mod / i) * inv[mod % i] % mod;
    }
    for (int i = 2; i < maxn; i++) {
        inv[i] = inv[i - 1] * inv[i] % mod;
    }
}

long long C(int a, int b) {
    if (a <= 0 || b < 0 || b > a) return 0;
    return fac[a] * inv[b] % mod * inv[a - b] % mod;
}

int main() {
    init();
    int x1, x2, y1, y2;
    scanf("%d%d%d%d", &x1, &y1, &x2, &y2);
    long long ans = 0;
    for (int i = x1; i <= x2; i++) {
        ans += C(i + y2 + 1, y2) - C(i + y1, y1 - 1);
    }
    ans = (ans % mod + mod) % mod;
    printf("%lld\n", ans);
    return 0;
}

