{
    long long res = 1;
    while (n > 0)
    {
        if (n & 1)
            res = res * a % modd;
        a = a * a % modd;
        n >>= 1;
    }
    return res;
}
long long modinv(long long a)
{
    return modpow(a, modd - 2);
}
