const int N = 2000006, M = 1000000007;
ll fact[N], infact[N];

ll power(int x, int y) {
    if (y == 0) {
        return 1;
    }
    ll temp = power(x, y >> 1);
    temp *= temp;
    temp %= M;
    if (y & 1) {
        temp *= x;
        temp %= M;
    }
    return temp;
}

void init() {
    fact[0] = infact[0] = 1;
    for (int i = 1; i < N; i++) {
        fact[i] = (fact[i-1] * i) % M;
        infact[i] = power(fact[i], M - 2);
    }
}

ll C(int n, int r) {
    if (r > n) return 0;
    ll ret = fact[n];
    ret *= infact[n-r];
    ret %= M;
    ret *= infact[r];
    ret %= M;
    return ret;
}

ll calc(int x, int y) {
    ll ret = 0;
    for (int i = 1; i <= y; i++) {
        ret += C(i + x + 1, i + 1);
    }
    ret -= y;
    ret += M;
    ret %= M;
    return ret;
}

int main() {
    //ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    init();
    int x1, y1, x2, y2;
    scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
    ll res = calc(x2, y2);
    res -= calc(x1 - 1, y2);
    res += M;
    res %= M;
    res -= calc(x2, y1 - 1);
    res += M;
    res %= M;
    res += calc(x1 - 1, y1 - 1);
    res %= M;
    printf("%lld", res);
    return 0;
}

