// 1 <= k <= n <= 10^7
#define CNKMAX 2000001
class CNK {
    std::vector<long long> fac, finv, inv;
    int MOD;
public:
    CNK(int mod = 1000000007): MOD(mod), fac(CNKMAX), finv(CNKMAX), inv(CNKMAX) {
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[1] = 1;
        for (int i = 2; i < CNKMAX; i++){
            fac[i] = fac[i - 1] * i % MOD;
            inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
            finv[i] = finv[i - 1] * inv[i] % MOD;
        }
    }
    int get(const int &n, const int &k) const {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
    }
};

LL calc(const CNK &cnk, int x, int y) {
    if (x < y) swap(x,y);
    LL sum = 0;
    REP(i,0,y) {
        sum += cnk.get(x+i, i + 1);
        if (sum >= MOD) sum -= MOD;
    }
    return sum;
}

