ll fact[M*2];

ll quick_mod(ll a,ll b,ll mod){
	ll ans=1;
	a%=mod;
	while(b){
		if(b&1)ans=(ans%mod * a%mod)%mod;
		a=(a%mod * a%mod)%mod;
		b>>=1;
	}
	return ans%mod;
}
ll get_inv(ll x){
	return quick_mod(x,MOD-2,MOD);
}

ll C_mod(ll n,ll k){
	return (fact[n] * get_inv(fact[k])%MOD * get_inv(fact[n-k])%MOD)%MOD;
}

