    friend istream& operator>>(istream& is, modint& a) {
        LL tmp; is >> tmp;
        a = tmp;
        return is;
    }
};



template<typename Ring>
struct Fact {

    vector<Ring> fact;

    Fact(int n) {
        fact.resize(n+1);
        fact[0] = Ring{1};
        for (int i = 1; i <= n; ++i) {
            fact[i] = fact[i-1] * Ring{i};
        }
    }

    Ring operator[](int i) {
        return fact[i];
    }
};

template<typename Field>
struct Comb {
    Fact<Field> fact;

    Comb(int n) : fact(n) {}

    Field operator()(int n, int r) {
        if (n < 0 || n-r < 0 || r < 0) {
            return Field{0};
        }
        return fact[n] / (fact[n-r] * fact[r]);
    }
};

using Int = modint<MOD>;


Int sum(LL r, LL c) {

    Comb<Int> comb(r+c);

    Int ret = Int(2).pow(r+c+1) - 1;

    for (int i = 0; i < c; ++i) {
        ret -= comb(r+c-1-i, r) * (Int(2).pow(i+1)-1);
    }

    for (int i = 0; i < r; ++i) {
        ret -= comb(r+c-1-i, c) * (Int(2).pow(i+1)-1);
    }

    return ret;
}


