int main() {
    const i64 mod = 1000000000 + 7;

    int n = 3e6;

    vector<i64> inv(n + 1);
    vector<i64> fact(n + 1);
    vector<i64> fact_inv(n + 1);

    for (i64 i = 1; i < n + 1; i++) {
        inv[i] = (i == 1) ? 1 : (mod - (mod / i) * inv[mod % i] % mod);
    }

    fact[0] = 1;
    fact_inv[0] = 1;

    for(int i = 1; i < n + 1; ++i) {
        fact[i] = fact[i - 1] * i % mod;
        fact_inv[i] = fact_inv[i - 1] * inv[i] % mod;
    }

    auto comb = [&](int n, int k) {
        if (n < k) {
            return i64(0);
        }

        return fact[n] * fact_inv[n - k] % mod * fact_inv[k] % mod;
    };

    int r1, c1, r2, c2;
    in(r1, c1, r2, c2);

    i64 ans = 0;

    for (int r = 1; r <= r2 + 1; r++) {
        ans = (ans + comb(r + c2, r)) % mod;
    }

    for (int r = 1; r <= r2 + 1; r++) {
        ans = (ans + mod - comb(r + c1 - 1, r)) % mod;
    }

    for (int r = 1; r <= r1; r++) {
        ans = (ans + mod - comb(r + c2, r)) % mod;
    }

    for (int r = 1; r <= r1; r++) {
        ans = (ans + comb(r + c1 - 1, r)) % mod;
    }

    out(ans);
}

