long long fastpower(long long a,long long b)
{
    if(b==0)
        return 1;
    if(b==1)
        return a;
    long long res = fastpower(a,b/2)%Mod;
    res = (res %Mod  * res % Mod )%Mod;
    if(b%2!=0)
        res*=a;
    return res % Mod;
}

ll mul_self(ll &x , ll y){
    x = (x * y)%Mod;
}

ll add_self(ll &x , ll y){
    x = (x + y)%Mod;
}


ll C(ll n , ll k){
    if(n - k < 0)   return 1;
    ll x = 1;
    mul_self(x , Fact[k]);
    mul_self(x , Fact[n - k]);
    ll y = Fact[n];
    mul_self(y , fastpower(x , Mod - 2));
    return y;
}

