    ret -= g(r2, c1 - 1);
    ret = (ret + MOD) % MOD;
    ret -= g(r1 - 1, c2);
    ret = (ret + MOD) % MOD;

    ret += g(r1 - 1, c1 - 1);
    ret %= MOD;

    cout << ret << endl;
    return 0;
}

