	for (int i = 1; i < N; i++)
		fact[i] = (fact[i-1] * i) % MOD;
}

ll powmod(ll a, ll b) {
	ll r = 1;
	while (b > 0) {
		if (b&1) r = (r * a) % MOD;
		a = (a * a) % MOD;
		b /= 2;
	}
	return r;
}

ll comb(int n, int k) {
	assert(n >= k && k >= 0);
	ll a = (fact[k] * fact[n-k]) % MOD;
	a = (fact[n] * powmod(a, MOD-2)) % MOD;
	//printf("comb(%d, %d) = %lld\n", n, k, a);
	return a;
}

ll g(int r, int c) {
	ll ret = (comb(r + c + 2, c + 1) + MOD - 1) % MOD;
	return ret;
}

