int64_t const MAXRC = 1e6;
int const MAXN = (MAXRC+1)*2;

int64_t inv[MAXN+1];
int64_t fact[MAXN+1];
int64_t ifact[MAXN+1];

void init(int n) {
  fact[0] = ifact[0] = fact[1] = ifact[1] = inv[1] = 1;
  for(int64_t i = 2; i <= n; ++i) {
    fact[i] = fact[i-1]*i%MOD;
    inv[i] = (MOD/i)*(MOD - inv[MOD%i])%MOD;
    ifact[i] = ifact[i-1]*inv[i]%MOD;
  }
}

int64_t f(int r, int c) {
  int64_t res = fact[r+c+2]*ifact[r+1]%MOD;
  (res *= ifact[c+1]) %= MOD;
  (res += MOD-1) %= MOD;
  return res;
}

