const ll MOD = 1000000007;
template <typename T, typename F>
T apply_doubling(const T& x,
    const long long& n,
    const T& id_elem,
    const F& binary_op)
{
    if (n == 0)
        return id_elem;
    T ret = apply_doubling(binary_op(x, x), n / 2, id_elem, binary_op);
    if (n % 2 == 1)
        ret = binary_op(ret, x);
    return ret;
}

long long mod_pow(long long x, long long n, long long mod)
{
    return apply_doubling(x, n, 1ll, [mod](ll a, ll b) { return a * b % mod; });
}

long long mod_inv(long long x, long long mod)
{
    return mod_pow(x, mod - 2, mod);
}

template <uint_fast64_t MOD>
struct mod_int {
    mod_int() noexcept
        : m_value(0)
    {
    }
    constexpr mod_int(uint_fast64_t x) noexcept
        : m_value((x + MOD) % MOD)
    {
    }

    constexpr mod_int(long long x) noexcept
        : m_value((x + MOD) % MOD)
    {
    }
    constexpr mod_int(int x) noexcept
        : m_value((x + MOD) % MOD)
    {
    }

    constexpr mod_int operator+(const mod_int rhs) const noexcept
    {
        return mod_int(m_value) += rhs;
    }
    constexpr mod_int operator-(const mod_int rhs) const noexcept
    {
        return mod_int(m_value) -= rhs;
    }
    constexpr mod_int operator*(const mod_int rhs) const noexcept
    {
        return mod_int(m_value) *= rhs;
    }
    constexpr mod_int operator/(const mod_int rhs) const noexcept
    {
        return mod_int(m_value) /= rhs;
    }
    constexpr mod_int& operator+=(const mod_int rhs) noexcept
    {
        m_value += rhs.m_value;
        if (m_value >= MOD)
            m_value %= MOD;
        return *this;
    }
    constexpr mod_int operator-=(const mod_int rhs) noexcept
    {
        if (m_value < rhs.m_value)
            m_value += MOD;
        m_value -= rhs.m_value;
        return *this;
    }
    constexpr mod_int operator*=(const mod_int rhs) noexcept
    {
        m_value = m_value * rhs.m_value % MOD;
        return *this;
    }
    constexpr mod_int operator/=(mod_int rhs) noexcept
    {
        uint_fast64_t exp = MOD - 2;
        while (exp > 0) {
            if (exp % 2 == 1)
                *this *= rhs;
            rhs *= rhs;
            exp /= 2;
        }

        return *this;
    }

    mod_int inv() const noexcept
    {
        return mod_int(1) /= *this;
    }
    uint_fast64_t value() const
    {
        return m_value;
    }

    friend ostream& operator<<(ostream&, const mod_int& v);
    friend istream& operator>>(istream&, mod_int& v);

private:
    uint_fast64_t m_value;
};

template <uint_fast64_t MOD>
ostream& operator<<(ostream& os, const mod_int<MOD>& v)
{
    return os << v.m_value;
}

template <uint_fast64_t MOD>
istream& operator>>(istream& is, mod_int<MOD>& v)
{
    return is >> v.m_value;
}

