        return comb((ll)r + c, (ll)c);
    };
    auto g = [&](int r, int c) {
        return f(r + 1, c + 1) - 1;
    };

    ll ans = g(r2, c2) + MOD - g(r2, c1 - 1) + MOD - g(r1 - 1, c2) + g(r1 - 1, c1 - 1);
    ans %= MOD;

    cout << ans << endl;
}

