const int N = 3e6;
const int M = 1e9 + 7;

int fp(int a, int p) {
	int x = 1;
	for (; p > 0; p >>= 1) {
		if (p & 1) {
			(x *= a) %= M;
		}
		(a *= a) %= M;
	}
	return x;
}

int fac[N], inv[N];

int cnk(int n, int k) {
	assert(0 <= k && k <= n && n < N);
	int up = fac[n], dn = inv[k] * inv[n - k] % M;
	return up * dn % M;
}
int f(int r, int c) {
	return cnk(r + c, r);
}

int solve(int r, int c) {
	int ans = 0, s = 1;
	for (int d = 0; d <= r + c; ++d) {
		// (0, d) ... (d, 0)
		//cerr << d << " " << s << endl;
		ans += s;
		(s *= 2) %= M;
		if (d >= r) {
			int i = r, j = d - r;
			(s += M - f(i, j)) %= M;
		}
		if (d >= c) {
			int i = d - c, j = c;
			(s += M - f(i, j)) %= M;
		}
	}
	return ans;
}

