		(fac[i] = fac[i - 1] * i) %= M;
	}
	inv[N - 1] = fp(fac[N - 1], M - 2);
	for (int i = N - 2; i >= 0; --i) {
		(inv[i] = inv[i + 1] * (i + 1)) %= M;
	}

	cin >> r1 >> c1 >> r2 >> c2;
	--r1;
	--c1;
	int res = solve(r2, c2) - solve(r2, c1) - solve(r1, c2) + solve(r1, c1);
	res %= M;
	res += M;
	res %= M;
	cout << res << endl;
	return 0;
}

