    long r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;

    constexpr long MOD = 1e9 + 7;
    vector<long> fact(3e6), ifact(3e6);
    fact[0] = 1;
    for(long i=1; i<3e6; i++)
        fact[i] = (fact[i-1] * i) % MOD;
    {
        long n = 3e6-1;
        long a = fact[n], b = MOD-2, r = 1;
        while(b) {
            if(b&1) r *= a, r %= MOD;
            a *= a, a %= MOD;
            b >>= 1;
        }
        ifact[n] = r;
    }
    for(long i=3e6-2; i>=0; i--)
        ifact[i] = (ifact[i+1] * (i+1)) % MOD;

    auto f = [&](long n, long a, long b) {
        // aCn + ... + bCn
        // nCn + ... bCn == b+1Cn+1
        // b+1Cn+1 - aCn+1
        long r = 1;
        r *= fact[b+1], r %= MOD;
        r *= ifact[n+1], r %= MOD;
        r *= ifact[b-n], r %= MOD;

        long s = 1;
        s *= fact[a], s %= MOD;
        s *= ifact[n+1], s %= MOD;
        s *= ifact[a-n-1], s %= MOD;
        return (MOD + r - s) % MOD;
    };

    long res = 0;
    for(long c=c1; c<=c2; c++)
        res += f(c, r1+c, r2+c), res %= MOD;
    cout << res << endl;
}

