int power(int x, int y) 
{ 
	int res = 1;	 // Initialize result 

	x = m(x); // Update x if it is more than or 
				// equal to p 

	while (y > 0) 
	{ 
		// If y is odd, multiply x with result 
		if (y & 1) 
			res = m(m(res)*m(x)); 

		// y must be even now 
		y = y>>1; // y = y/2 
		x = m(m(x)*m(x)); 
	} 
	return res; 
} 
