#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const ll M = 1'000'000'007ULL;

vector<ll> fac(1'000'006);   // n!(mod M)
vector<ll> ifac(1'000'006);  // k!^{M-2} (mod M)
// a,bの範囲的にこれだけ配列を用意していけば十分

ll mpow(ll x,
        ll n) {  // x^n(mod M) ←普通にpow(x,n)では溢れてしまうため，随時mod計算
  ll ans = 1;
  while (n != 0) {
    if (n & 1)
      ans = ans * x % M;
    x = x * x % M;
    n = n >> 1;
  }
  return ans;
}

ll comb(ll a, ll b) {  // aCbをmod計算
  if (a == 0 && b == 0)
    return 1;
  if (a < b || a < 0)
    return 0;
  ll tmp = ifac[a - b] * ifac[b] % M;
  return tmp * fac[a] % M;
}

int64_t calc(int r, int c) {
  if (r < 0 || c < 0) return 0;
  return comb(r + c + 2, c + 1) - 1;
}

void solve() {
  int r1, c1, r2, c2;
  cin >> r1 >> c1 >> r2 >> c2;
  --r1;
  --c1;
  auto area1 = calc(r1, c1);
  auto area2 = calc(r2, c1);
  auto area3 = calc(r1, c2);
  auto area4 = calc(r2, c2);

  auto res = area4 - area2 - area3 + area1;
  if (res < 0)
    res += M;
  res %= M;

  cout << res << endl;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  fac[0] = 1;
  ifac[0] = 1;
  for (ll i = 0; i < 1'000'005; i++) {
    fac[i + 1] = fac[i] * (i + 1) % M;  // n!(mod M)
    ifac[i + 1] =
        ifac[i] * mpow(i + 1, M - 2) % M;  // k!^{M-2} (mod M) ←累乗にmpowを採用
  }

  solve();
}

