#define ull unsigned long long 
ull mod = 1000000007;

ull factorial(ull n) {
  ull ret = 1;
  for (ull i = 1; i <= n; ++i) {
    ret *= i;
    ret %= mod;
  }
  return ret;
}

ull pow(ull n, ull k){
  ull ret = 1;
  while (k > 0) {
    if (k & 1) {
      ret = ret * n;
      ret %= mod;
    }
    n = n * n;
    n %= mod;
    k >>= 1;
  }
  return ret;
}

ull inv_factorial(ull n) {
  ull ret = factorial(n);
  ret = pow(ret, mod - 2);
  return ret;
}

ull route(ull x, ull y){
  ull ret = factorial(x + y);
  ret *= inv_factorial(x);
  ret %= mod;
  ret *= inv_factorial(y);
  ret %= mod;
  return ret;
}

