  ans += route(r2 + 1, c2 + 1) - 1;
  ans -= route(r2 + 1, c1) - 1;
  ans -= route(r1, c2 + 1) - 1;
  ans += route(r1, c1) - 1;
  while (ans < 0) ans += mod;
  ans %= mod;

  cout << ans << endl;
  return 0;
}

