ll inverse(ll a){
    ll x = 1, p = MOD - 2;
    while(p != 0){
        if(p%2 == 1){ 
            x = (x * a) % MOD;
            p -= 1;
        }
        a = (a * a) % MOD;
        p /= 2;
    }        
    return x;
}

ll calc(ll x, ll y){
