const int MOD = 1e9 + 7, N = 2e6 + 3;

int add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    if (a < 0) a += MOD;
    return a;
}

int mul(int a, int b) {
    return 1LL * a * b % MOD;
}

int binpow(int a, int n) {
    int res = 1;
    while (n) {
        if (n % 2)
            res = mul(res, a);
        a = mul(a, a);
        n /= 2;
    }
    return res;
}

int inv(int a) {
    return binpow(a, MOD - 2);
}

int fact[N];

int C(int n, int k) {
    return mul(fact[n], inv(mul(fact[n - k], fact[k])));
}

void solve() {
    int r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;

    fact[0] = 1;
    for (int i = 1; i < N; ++i)
        fact[i] = mul(fact[i - 1], i);

    int ans = 0;
    for (int r = r1; r <= r2; ++r) {
        ans = add(ans, add(C(c2 + r + 1, c2), -C((c1 - 1) + r + 1, c1 - 1)));
    }
    cout << ans << '\n';
}

