const int mod = 1e9 + 7;
int fac[2000001];

int b_p(int a, int b) {
    if (b == 0) return 1;
    int val = b_p(a, b / 2);
    if (b % 2) return (((val * val) % mod) * a) % mod;
    return (val * val) % mod;
}

int dv(int a, int b) {
    return (a * b_p(b, mod - 2)) % mod;
}

int c(int n, int k) {
    return dv(fac[n], (fac[k] * fac[n - k]) % mod);
}

void solve() {
    int r1, c1, r2, c2;
    cin >> r1 >> c1 >> r2 >> c2;
    fac[0] = 1;
    for (int i = 1; i <= 2000000; ++i) fac[i] = (fac[i - 1] * i) % mod;
    int ans = 0, sum = 0;
    sum = c(r1 + c1, r1);
    ans = sum;
    //cout << sum << '\n';
    int lx = r1, ly = c1, rx = r1, ry = c1;
    while (ly < c2 || lx < r2) {
        sum += sum;
        if (ly < c2) {
            ++ly;
            sum += c(ly + lx - 1, ly);
        }
        else {
            sum -= c(lx + ly, lx);
            ++lx;
        }
        if (rx < r2) {
            ++rx;
            sum += c(ry + rx - 1, rx);
        }
        else {
            sum -= c(rx + ry, rx);
            ++ry;
        }
        sum = ((sum % mod) + mod) % mod;
        ans += sum;
        ans %= mod;
        //cout << sum << ' ' << lx << ' ' << ly << ' ' << rx << ' ' << ry << '\n';
    }
