ll modinv(ll a) {
	ll b = mod, u = 1, v = 0;
	while (b) {
		ll t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= mod; 
	if (u < 0) u += mod;
	return u;
}

ll modpow(ll a, ll b) {
