    }

    mint factorial(ll k) const { return fact.at(k); }
    mint combination(ll k, ll l) const {
        return fact.at(k) * ifact.at(l) * ifact.at(k - l);
    }
};

vector<mint> pow2;

mint calc(ll r, ll c){
    mint ans = 0;
    ans += pow2.at(r + c + 1) - 1;
    mintcomb mc(r + c + 1);
    REP(i, c){
        const mint v = mc.combination(r + i, i);
        ans -= v * (pow2.at(c - i) - 1);
    }
    REP(i, r){
        const mint v = mc.combination(c + i, i);
        ans -= v * (pow2.at(r - i) - 1);
    }
    return ans;
}

