    }

    const mint v1 = calc(r2, c2);
    const mint v2 = calc(r2, c1 - 1);
    const mint v3 = calc(r1 - 1, c2);
    const mint v4 = calc(r1 - 1, c1 - 1);
    const mint ans = v1 - v2 - v3 + v4;
    cout << ans << endl;
    return 0;
}

