#include <bits/stdc++.h>
using namespace std;

long long modpow(long long a,long long n,long long MOD){
    int ret = 1;
    while (n > 0) {
        if (n & 1) ret = ret * a % MOD;
        a = a * a % MOD;
        n >>= 1;
    }
    return ret;
}

long long modinv(long long a, long long MOD) {
    return modpow(a, MOD - 2, MOD);
}

int main(){
    int r1,c1,r2,c2;
    cin >> r1 >> c1 >> r2 >> c2;
    int MOD = 1000000007;
    int MAX = r2 + c2 + 1;
    long long fact[MAX + 1];
    //factorial mod, modulo inverse
    fact[0] = fact [1] = 1;
    for (int i = 1; i < MAX; i++){
        fact[i + 1] = fact[i] * (i + 1) % MOD;
    }
    int ans = 0;
    int X = 0;
    for (int i = c1; i <= c2; i++){
        X = ((fact[r2 + i + 1] * modinv(fact[r2],MOD)) % MOD * modinv(fact[i + 1],MOD) % MOD - (fact[r1 + i] * modinv(fact[r1 - 1],MOD)) % MOD * modinv(fact[i + 1],MOD) % MOD) % MOD;
        X %= MOD;
        if (X < 0) X += MOD;
        ans += X;
        ans %= MOD;
    }
    cout << ans << endl;
}

