int power(int x, int y) 
{ 
    int res = 1;
    x = x % mod; 

    while (y > 0) 
    { 
        if (y & 1) 
            res = (res*x) % mod; 
        y = y>>1LL; 
        x = (x*x) % mod;   
    } 
    return res; 
}

int inv(int n) 
{ 
    return power(n, mod-2); 
} 

int ncr (int n, int r)
{
    n++; r++;
    return fact[n] * inv(fact[n-r]) % mod * inv(fact[r]) % mod;
}


