    ll rez = 1;
    ll pw = x;
    for(ll t = 0 ; (1<<t) <= mod - 2; t++){
        if((mod-2)&(1<<t)){
            rez *= pw;
            rez %= mod;
        }
        pw *= pw;
        pw %= mod;
    }
    return rez;
}

ll f(ll x, ll y){
    ll rez = 1;
    for(ll k = 2; k <= x + y ; k++){
        rez *= k;
        rez %= mod;
        ll rv = inv(k);
        if(k <= x){
            rez *= rv;
            rez %= mod;
        }
        if(k <= y){
            rez *= rv;
            rez %= mod;
        }
    }
    assert((rez + mod - 1)%mod <= mod);
    return (rez + mod - 1)%mod;

}


