ll fast(ll n,ll a,ll m)
{
    if(n==0)
      return 1;
    else if(n==1)
        return a;
    else
    {
        ll res=fast(n/2,a,m);
        res=((res%m)*(res%m))%m;
        if(n%2==0)
            return res;
        else
            return (((res%m)*(a%m))%m);
    }
}
ll nCr(ll n,ll r)
{
    ll p=fac[n];
    ll u=fast(1e9+5,fac[n-r],1e9+7);
    ll v=fast(1e9+5,fac[r],1e9+7);
    p=((p%M)*(u%M))%M;
    p=((p%M)*(v%M))%M;
    return p;
}
ll func(ll i,ll c1,ll c2)
{
    ll A,B;
    A=nCr(c2+i+2,i+1);
    B=nCr(c1+i+1,i+1);
    A-=B;
    if(A<0)
    {
        A+=M;
        A%=M;
    }
    return A;

}
