const long long big_prime = 1000000007;

long long fact_P[fact_idx_max + 1], fact_M[fact_idx_max + 1];

long long calc_sq(long long x) {
	x = x % big_prime;
	return (x * x) % big_prime;
}

//a^b
long long calc_pow(long long a, long long b) {
	long long ret;
	if (b == 0)return 1;
	if (b == 1)return a;
	if (b % 2 == 0) {
		ret = calc_sq(calc_pow(a, b / 2));
		return ret % big_prime;
	}
	if (b % 2 == 1) {
		ret = a * calc_sq(calc_pow(a, b / 2));
		return ret % big_prime;
	}
}

void make_fact(long long n) {
	fact_P[0] = fact_M[0] = 1;
	for (int i = 1; i <= n; i++) {
		fact_P[i] = (fact_P[i - 1] * i) % big_prime;
		fact_M[i] = (fact_M[i - 1] * calc_pow(i, big_prime - 2)) % big_prime;
	}
}

//nCr
long long calc_comb(long long n, long long r) {
	long long ret = (((fact_P[n] * fact_M[r]) % big_prime)*fact_M[n - r]) % big_prime;
	return ret;
}

