template <long long Modulus> class modint {
  long long a;

public:
    constexpr modint(const long long x = 0) noexcept : a((x % Modulus + Modulus) % Modulus) {}
    constexpr long long val() const noexcept { 
        return a; 
    }
    constexpr modint operator + (const modint rhs) const noexcept {
        return modint(*this) += rhs;
    }
    constexpr modint operator - (const modint rhs) const noexcept {
        return modint(*this) -= rhs;
    }
    constexpr modint operator * (const modint rhs) const noexcept {
        return modint(*this) *= rhs;
    }
    constexpr modint operator / (const modint rhs) const noexcept {
        return modint(*this) /= rhs;
    }
    constexpr modint &operator += (const modint rhs) noexcept {
        a += rhs.a;
        if (a >= Modulus) {
            a -= Modulus;
        }
        return *this;
    }
    constexpr modint &operator -= (const modint rhs) noexcept {
        if (a < rhs.a) {
            a += Modulus;
        }
        a -= rhs.a;
        return *this;
    }
    constexpr modint &operator *= (const modint rhs) noexcept {
        a = a * rhs.a % Modulus;
        return *this;
    }
    constexpr modint &operator /= (modint rhs) noexcept {
        long long exp = Modulus - 2;
        while (exp) {
          if (exp % 2) {
              *this *= rhs;
          }
          rhs *= rhs;
          exp /= 2;
      }
      return *this;
    }
    constexpr bool operator == (const modint rhs) const noexcept {
        return modint(*this).val() == rhs.val();
    }
    constexpr bool operator != (const modint rhs) const noexcept {
        return modint(*this).val() != rhs.val();
    }
};
