long long ksm(long long x,long long y)
{
	x %= MOD;
	long long rt = 1LL;
	while ( y )
	{
		if ( y & 1 ) 
			rt = rt * x % MOD;
		x = x * x % MOD;
		y >>= 1;
	}
	return rt;
}

long long C(long long n,long long m)
{
	if ( n < m )
		return 0LL;
	long long rt = 1LL;
	for ( long long i = 0LL ; i < m ; i++ )
		rt = rt * (n-i) % MOD * ksm(i+1LL,MOD-2) % MOD;
	return rt;
}

