/*-----------------------------------------------------SegTree---------------------------------------------*/
int mxn11 = 2e5 + 1;
vector<ll> t(4 * mxn11 + 1, 0);
vector<ll> tAdd(4 * mxn11 + 1, 0);

void build(int v, int vl, int vr) {
    if (vl == vr) {
        /*t[v]=prefsummleft[vl];*/
    } else {
        int tmp = (vl + vr) >> 1;
        build(2 * v, vl, tmp);
        build(2 * v + 1, tmp + 1, vr);
        t[v] = min(t[2 * v], t[2 * v + 1]);
    }
}

void push(int v) {
    tAdd[2 * v] += tAdd[v];
    tAdd[2 * v + 1] += tAdd[v];
    t[v] += tAdd[v];
    tAdd[v] = 0;
}

ll get(int v, int vl, int vr, int l, int r) {
    if (l > r) return 0;
    if (vl == l && vr == r) {
        return t[v] + tAdd[v];
    }
    int tmp = (vl + vr) >> 1;
    push(v);
    ll a = get(2 * v, vl, tmp, l, min(tmp, r));
    ll b = get(2 * v + 1, tmp + 1, vr, max(tmp + 1, l), r);
    return min(a, b);
}

void update(int v, int vl, int vr, int l, int r, ll cnt) {
    if (l > r) return;
    if (vl == l && vr == r) {
        tAdd[v] += cnt;
        return;
    }
    int tmp = (vl + vr) >> 1;
    push(v);
    update(2 * v, vl, tmp, l, min(tmp, r), cnt);
    update(2 * v + 1, tmp + 1, vr, max(tmp + 1, l), r, cnt);
    t[v] = min(t[2 * v] + tAdd[2 * v], t[2 * v + 1] + tAdd[2 * v + 1]);
}
