	if ( b == 0 ) return 1;
	int half = expo(a,b/2);
	half = ( 1LL * half * half ) % mo;
	if (b & 1) half = ( half * 1LL * a )% mo;
	return half;
}

LL C( int a, int b ){
	LL ans = F[a];
	ans = ( ans * 1LL * IF[b]) % mo;
	ans = ( ans * 1LL * IF[a-b]) % mo;
	return ans;
}

LL f( int r, int c ){
	LL ans = 0;
	for ( int i = 0; i <= c; i++ ){
		ans = ( ans + i + 1 ) % mo;
	}
	// printf("= %lld\n",ans);
	for ( int i = 2; i <= r; i++ ){
		ans = (ans+ C(i+c+1,c)) % mo;
	}
	// printf("%d %d %lld\n",r,c,ans);
	return ans;
}

