    }
    return temp;
}

void init() {
    fact[0] = infact[0] = 1;
    for (int i = 1; i < N; i++) {
        fact[i] = (fact[i-1] * i) % M;
        infact[i] = power(fact[i], M - 2);
    }
}

ll C(int n, int r) {
    if (r > n) return 0;
    ll ret = fact[n];
    ret *= infact[n-r];
    ret %= M;
    ret *= infact[r];
    ret %= M;
    return ret;
}

