struct ModInt {
    long long value;
    static long long mod; // mod must be a prime number

    ModInt(long long v = 0) : value(v % mod) {}

    ModInt pow(long long n) const {
        long long x = value, res = 1;
        while(n > 0) {
            if(n & 1) {
                res = res * x % mod;
            }
            x = x * x % mod;
            n >>= 1;
        }
        return ModInt(res);
    }

    ModInt inverse() const {
        return pow(mod - 2);
    }

    ModInt operator-() const {
        return ModInt((mod - value) % mod);
    }

    ModInt& operator+=(const ModInt& a) {
        value += a.value;
        value %= mod;
        return *this;
    }

    ModInt& operator-=(const ModInt& a) {
        value += (-a).value;
        value %= mod;
        return *this;
    }

    ModInt& operator*=(const ModInt& a) {
        value *= a.value;
        value %= mod;
        return *this;
    }

    ModInt& operator/=(const ModInt& a) {
        return (*this) *= a.inverse();
    }

    ModInt operator+(const ModInt& a) const {
        return ModInt(*this) += a;
    }

    ModInt operator-(const ModInt& a) const {
        return ModInt(*this) -= a;
