class Combination {
public:
    int N;
    vector<mint> fact;
    vector<mint> factsum;

    Combination(int n) : N(n), fact(n+1), factsum(n+1) {
        fact[0] = 1;
        factsum[0] = 1;
        for(ll i=1; i<=N; i++){
            fact[i] = fact[i-1] * i;
            factsum[i] = factsum[i-1] + fact[i];
        }
    }    

    // a ** b (mod m)
    static mint modpow(mint a, ll n) {
        mint res = 1;
        while(n > 0) {
            if(n & 1) {
                res *= a;
            }
            a *= a;
            n >>= 1;
        }
        return res;
    }

    // a / b (mod m)
    static mint moddiv(const mint& a, const mint& b) {
        return a * modpow(b, mint::mod - 2);
    }

    mint combin(int n, int k) {
        if(n < 0 || k < 0 || n < k) {
            return 1;
        }
        return fact[n] * modpow(fact[k] * fact[n-k], mint::mod - 2);
    }
};

