constexpr int MOD = 1000000007;

// O(log(p))
ll mpow(ll x, ll p) {
    if (p == 1) { return x % MOD; }
    if (p % 2) { return (x * mpow(x, p - 1)) % MOD; }
    ll sub = mpow(x, p / 2);
    return (sub * sub) % MOD;
}

// O(1)
int f(const vll& fac, const vll& inv, int i, int j, vvi& dp) {
    if (i == 0 || j == 0) { return 1; }
    if (i == 1 || j == 1) { return dp[i][j] = dp[j][i] = (i + j) % MOD; }
    if (dp[i][j] != -1) { return dp[i][j]; }
    return dp[i][j] = dp[j][i] = (((fac[i + j] * inv[i]) % MOD) * inv[j]) % MOD;
}

