    // O(n)
    fac[0] = 1;
    rep(i, 1, n + 1) { fac[i] = (i * fac[i - 1]) % MOD; }

    // O(nlog(MOD))
    inv.back() = mpow(fac.back(), MOD - 2);
    rrep(i, min(r1, c1), n) { inv[i] = (inv[i + 1] * (i + 1)) % MOD; }

    ll sum = 0;
    vvi dp(n + 1, vi(n + 1, -1));
    rep(i, r1, r2 + 1) {
        rep(j, c1, c2 + 1) {
