const long long MOD = 1000000007;

template <typename T> class Factorial {
  public:
    vector<T> fact;
    vector<T> factinv;
    Factorial(long long N);
    static T bipow(T c, T n);
    static T square(T n);
    T conv(T n, T m) const;
    T perm(T n, T m) const;
};

template <typename T> Factorial<T>::Factorial(long long N) : fact(N+1), factinv(N+1) {
  fact[0] = 1;
  for (long long i = 1; i < N+1; i++) {
    fact[i] = fact[i-1]*static_cast<T>(i)%MOD;
  }
  factinv[N] = bipow(fact[N], MOD-2);
  for (int i = N; i > 0; i--) {
    factinv[i-1] = factinv[i]*static_cast<T>(i)%MOD;
  }
}

template <typename T> T Factorial<T>::bipow(T c, T n) {
  if (n == 0) {
    return 1;
  } else if(n == 1) {
    return c;
  } else if(n%2 == 0) {
    return square(bipow(c, n/2))%MOD;
  } else {
    return (static_cast<T>(c)*square(bipow(c, (n-1)/2)))%MOD;
  }
}

template <typename T> T Factorial<T>::square(T n) {
  return static_cast<long long>(n)*n%MOD;
}

template <typename T> T Factorial<T>::conv(T n, T m) const {
  if (n < m) {
    return 0;
  }
  return (((static_cast<long long>(fact[n])*factinv[m])%MOD)*factinv[n-m])%MOD;
}

template <typename T> T Factorial<T>::perm(T n, T m) const {
  if (n < m) {
    return 0;
  }
  return (static_cast<long long>(fact[n])*factinv[n-m])%MOD;
  }

void solve(std::vector<long long> r, std::vector<long long> c){
  Factorial<long long> F(r[1]+c[1]+2LL);

  long long ret = 0;

  ret += (F.conv(r[1]+c[1]+2, r[1]+1) - 1 + MOD) % MOD;
  ret -= (F.conv(r[1]+c[0]+1, r[1]+1) - 1 + MOD) % MOD;
  ret %= MOD;
  ret -= (F.conv(r[0]+c[1]+1, r[0]) - 1 + MOD) % MOD;
  ret %= MOD;
  ret += (F.conv(r[0]+c[0], r[0]) - 1 + MOD) % MOD;
  ret %= MOD;
  std::cout << ret << std::endl;
}

int main(){
  std::vector<long long> r(2);
  std::vector<long long> c(2);
  for(int i = 0 ; i < 2 ; i++){
    scanf("%lld",&r[i]);
    scanf("%lld",&c[i]);
  }
  solve(std::move(r), std::move(c));
  return 0;
}

