    factorials[0] = FiniteField(1)
    for (i in 1..n) {
        factorials[i] = factorials[i - 1] * FiniteField(i)
    }
    val iFactorials = Array(n + 1, { FiniteField(0) })
    for (i in 0..n) {
        iFactorials[i] = FiniteField(1) / factorials[i]
    }

    fun combination(a: Int, b: Int): FiniteField {
        if (a < b) return FiniteField(0)
        return factorials[a] * iFactorials[b] * iFactorials[a - b]
    }

