fun C(k: Int, n: Int): Long {
    var res = (fact[n] * inv(fact[n - k])) % mod
    res = (res * inv(fact[k])) % mod
    return res
}

fun inv(x: Long): Long = pow(x, mod - 2)
fun pow(a: Long, x: Long): Long {
    var a = a
    var x = x
    var res = 1L
    while (x > 0) {
        if (x % 2 == 1L) res = (res * a) % mod
        a = (a * a) % mod
        x /= 2
    }
    return res
}

class FastScanner(s: InputStream) {
    private var st = StringTokenizer("")
