fun path(r:Int, c:Int):Array<Array<ULong>>{
    var pathList= Array(r, {Array(c, {it.toULong()})})
    pathList[0][0]= 1u
    for (i in 0 until r){
        pathList[i][0]=1u
        for (j in 1 until c){
            pathList[i][j]=pathList[i][j-1]*(i+j).toUInt()/j.toUInt()
        }
    }
    return pathList
}

