class Comb(max: Int, val mod: Int = 1000000007) {
    val fac = LongArray(max + 1).apply { this[0] = 1L; this[1] = 1L }
    val finv = LongArray(max + 1).apply { this[0] = 1L; this[1] = 1L }
    val inv = LongArray(max + 1).apply { this[1] = 1L }

    init {
        for (i in 2..max) {
            fac[i] = fac[i - 1] * i % mod
            inv[i] = mod - inv[mod % i] * (mod / i) % mod
            finv[i] = finv[i - 1] * inv[i] % mod
        }
    }

    /**
     * nCk
     */
    operator fun get(n: Int, k: Int): Long {
        if (n < k) return 0
        if (n < 0 || k < 0) return 0
        return fac[n] * (finv[k] * finv[n - k] % mod) % mod
    }
}

