    private static void solve() {
        map = new int[r2 + 1][c2 + 1];
        int ans = 0;

        for (int r = 0; r <= r2; r++) {
            for (int c = 0; c <= c2; c++) {
                if (r == 0 && c == 0) {
                    map[0][0] = 1;
                } else if (r == 0) {
                    map[0][c] = 1;
