        R = (R - COM(X1+Y2+1, X1)%MOD) % MOD;
        if(R<0) R += MOD;
        R = (R - COM(X2+Y1+1, Y1)%MOD) % MOD;
        if(R<0) R += MOD;
        R = (R + COM(X1+Y1, X1)) % MOD;

        System.out.println(R);
    }

