import java.io.*;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;

public class Main {

    static int R1, C1, R2, C2;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        R1 = sc.nextInt();
        C1 = sc.nextInt();
        R2 = sc.nextInt();
        C2 = sc.nextInt();

        System.out.println(solve());
    }

    static int solve() {
        // 10^6なのでうっとなるがまぁ大丈夫だろう...
        FermatCombination fc = new FermatCombination(R2+C2+10);

        int a = f(R2, C2, fc);
        int b = f(R2, C1-1, fc);
        int c = f(R1-1, C2, fc);
        int d = f(R1-1, C1-1, fc);
        // debug(a, b, c, d);
        return add(sub(sub(a, b), c), d);
    }

    static int f(int r, int c, FermatCombination fc) {
        // debug("f", r, c);
        int sum = 0;

        // 一行がO(1)で出るのでそのようにする, divがO(1)でない気もするがまぁ
        for (int i = 0; i <= c; i++) {
            // k(0, c) + k(1, c) + ...k(r, c) = k(r, c+1) らしい
            // k(r, c) = (r+c)! / r!c!

            // debug(mul(mul(fc.factorial[r+i+1], fc.inverse[r]), fc.factorial[i+1]));
            sum = add(sum, mul(mul(fc.factorial[r+i+1], fc.inverse[r]), fc.inverse[i+1]));
        }
        return sum;
    }

    static int MOD = 1_000_000_007;

    static int pow(int base, long exp) {
        if( exp == 0 ) return 1;

        int ans = 1;
        base %= MOD;
        while( exp > 0 ) {
            if( (exp & 1) == 1 ) {
                ans = mul(ans, base);
            }

            base = mul(base, base);
            exp = exp >> 1;
        }
        return ans;
    }

    static int sub(int a, int b) {
        int c = a - b;
        if( c < 0 ) c += MOD;
        return c;
    }

    static int div(int a, int b) {
        return mul(a, pow(b, MOD-2));
    }

    static int add(int a, int b) {
        int c = a + b;
        if( c >= MOD ) c %= MOD;
        return c;
    }

    static int mul(int a, int b) {
        long c = (long)a * b;
        if( c >= MOD ) c %= MOD;
        return (int)c;
    }

    static class FermatCombination {
        private final int size;
        private final int[] factorial; // n -> factorial(n)
        private final int[] inverse;   // n -> inverse(factorial(n))

        FermatCombination(int size) {
            this.size = size;
            factorial = new int[size + 1];
            inverse = new int[size + 1];

            init();
        }

        private void init() {
            factorial[0] = 1;
            factorial[1] = 1;
            inverse[0] = 1;
            inverse[1] = 1;
            for (int i = 2; i <= size; i++) {
                factorial[i] = mul(factorial[i-1], i);
                inverse[i] = pow(factorial[i], MOD - 2);
            }
        }

        int comb(int n, int k) {
            if( n > size ) throw new RuntimeException("wtf : size=" + size + " n=" + n);
            return mul(mul(factorial[n], inverse[k]), inverse[n - k]);
        }

        // 重複組み合わせ
        // k種類からn個選ぶ場合の数
        int hcomb(int k, int n) {
            return comb(k+n-1, n);
        }

        int group(int n, int g, int k) {
            // C(n, g) * C(n-g, g)... / k!
            // n! / (n-gk)! / g! ^ k / k!
            int ret = factorial[n];             // n!
            ret = mul(ret, inverse[n - g*k]);   // 1 / (n-gk)!
            ret = mul(ret, pow(inverse[g], k)); // 1 / (g! ^ k)
            ret = mul(ret, inverse[k]);         // 1 / k!
            return ret;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
