		dp[0][0]=0;
		for(int i=1;i<=r;i++)
		{
			for(int j=1;j<=c;j++)
			{
				dp[i][j]=(dp[i-1][j]+dp[i][j-1])%m;
			}
		}

		return dp;
	}

