    static long f(int r, int c) {
        return combination.of(r + c, r);
    }
    static long g(int r, int c) {
        Mod.Value v = mod.value(0);
        for (int i = 1; i <= r + 1; i++) {
            v.add(f(i, c));
        }
        return v.longValue();
    }
    static void solve(MyScanner in, MyWriter out) {
        int r1 = in.nextInt();
        int c1 = in.nextInt();
        int r2 = in.nextInt();
        int c2 = in.nextInt();
        Mod.Value ans = mod.value(g(r2, c2))
                           .subtract(g(r2, c1 - 1))
                           .subtract(g(r1 - 1, c2))
                           .add(g(r1 - 1, c1 - 1));
        out.println(ans);
    }
    static final class Mod {
        private final int divisor;

        Mod(int divisor) {
            if (divisor <= 0) {
                throw new IllegalArgumentException();
            }
            this.divisor = divisor;
        }
        long mod(long dividend) {
            return Math.floorMod(dividend, divisor);
        }
        long add(long a, long b) {
            return mod(mod(a) + mod(b));
        }
        long subtract(long a, long b) {
            return mod(mod(a) - mod(b));
        }
        long multiply(long a, long b) {
            return mod(mod(a) * mod(b));
        }
        long pow(long a, long b) {
            if (b < 0) {
                throw new IllegalArgumentException();
            }
            long r = 1;
            while (b > 0) {
                if ((b & 1) == 1) {
                    r = multiply(r, a);
                }
                a = multiply(a, a);
                b >>= 1;
            }
            return r;
        }
        long inverse(long a) {
            // assert isCoprime(a, divisor);
            if (a == 0) {
                throw new IllegalArgumentException();
            }
            a = mod(a);
            long b = divisor;
            long u = 1;
            long v = 0;
            while (b != 0) {
                long q = a / b;
                a -= q * b;
                u -= q * v;

                long tmp = a;
                a = b;
                b = tmp;

                tmp = u;
                u = v;
                v = tmp;
            }
            return mod(u);
        }
        long div(long a, long b) {
            return multiply(a, inverse(b));
        }
        Value value(long initialValue) {
            return new Value(this, initialValue);
        }
        Combination combination(int maxN) {
            return new Combination(divisor, maxN);
        }

        static final class Value {
            private final Mod mod;
            private long value;

            private Value(Mod mod, long initialValue) {
                this.mod = mod;
                value = mod.mod(initialValue);
            }
            long longValue() {
                return value;
            }
            Value add(long a) {
                value = mod.add(value, a);
                return this;
            }
            Value add(Value a) {
                return add(a.value);
            }
            Value subtract(long a) {
                value = mod.subtract(value, a);
                return this;
            }
            Value subtract(Value a) {
                return subtract(a.value);
            }
            Value multiply(long a) {
                value = mod.multiply(value, a);
                return this;
            }
            Value multiply(Value a) {
                return multiply(a.value);
            }
            Value pow(long a) {
                value = mod.pow(value, a);
                return this;
            }
            Value inverse() {
                value = mod.inverse(value);
                return this;
            }
            Value div(long a) {
                value = mod.div(value, a);
                return this;
            }
            Value div(Value a) {
                return div(a.value);
            }
            @Override
            public String toString() {
                return Long.toString(value);
            }
        }
        // https://qiita.com/drken/items/3b4fdf0a78e7a138cd9a
        // http://drken1215.hatenablog.com/entry/2018/06/08/210000
        static final class Combination {
            private final int divisor;
            private final long[] factorial;
            private final long[] factorialInverse;

            private Combination(int divisor, int maxN) {
                this.divisor = divisor;
                factorial = new long[maxN + 1];
                long[] inverse = new long[factorial.length];
                factorialInverse = new long[factorial.length];

                factorial[0] = factorial[1] = 1;
                inverse[1] = 1;
                factorialInverse[0] = factorialInverse[1] = 1;
                for (int i = 2; i < factorial.length; i++) {
                    factorial[i] = factorial[i - 1] * i % divisor;
                    inverse[i] = divisor
                                 - inverse[divisor % i]
                                   * (divisor / i)
                                   % divisor;
                    factorialInverse[i] =
                            factorialInverse[i - 1] * inverse[i] % divisor;
                }
            }
            long of(int n, int k) {
                if (k > n) {
                    return 0;
                }
                return factorial[n]
                       * (factorialInverse[k]
                          * factorialInverse[n - k]
                          % divisor)
                       % divisor;
            }
        }
    }
