			factorial[i] = (factorial[i-1]*i)%MOD;
		long ans = 0;
		for (int r = R1; r <= R2; r++) {
			//Hockey Stick prefix sum
			long val = (choose(r+C2+1,r+1)-choose(r+C1,r+1)+MOD)%MOD;
			ans = (ans+val)%MOD;
		}
		pw.println(ans);
