        int c1 = Math.min(tc1, tc2);

        int r2 = tr1+tr2-r1;
        int c2 = tc1+tc2-c1;

        int part1 = modAdd(comb(r1 + c1, c1), comb(r2 + c2 + 2, c2 + 1), true);
