            // out.println(ans);
        }
        for(int j = c1; j <= c2; j++){
            int pi = r1-1;
            int pj = j;
            long prev = C(pi+pj,pi,mod,fif);
            // out.println(prev);
            int qi = r2-r1;
            int qj = c2-j;
            long tmp = C(qi+qj+2,qi+1,mod,fif)-1;
            long val = prev * (mod+tmp%mod)%mod;
            ans += val;
            ans %= mod;
        }

