import java.util.*;
import java.io.PrintWriter;
public class Main{
	static long mod=1000000007;
	static long[] fact;
	static long[] inv;
	public static void main(String[] args){
		Scanner sc=new Scanner(System.in);
		int r1=sc.nextInt();
		int c1=sc.nextInt();
		int r2=sc.nextInt();
		int c2=sc.nextInt();
		long ans=0;
		fact=new long[c2+r2+2];
		fact[1]=1;
		for(int i=2; i<=c2+r2+1; i++){
			fact[i]=(fact[i-1]*i)%mod;
		}
		inv=new long[c2+r2+2];
		inv[c2+r2+1]=pow(fact[c2+r2+1],mod-2);
		for(int i=c2+r2; i>=0; i--){
			inv[i]=(inv[i+1]*(i+1))%mod;
		}
		for(int i=c1; i<=c2; i++){
			ans+=comb(i+r2+1,i+1)-comb(i+r1,i+1);
			ans%=mod;
		}
		System.out.println(ans);
	}
	static long comb(int t,int y){
		if(y>t){
			return 0;
		}
		long re=1;
		re*=fact[t];
		re*=inv[y];
		re%=mod;
		re*=inv[t-y];
		return re%mod;
	}

	static long pow(long p,long q){
		long res=1;
		while(q>0){
			if((q & 1)==1){
				res*=p;
				res%=mod;
			}
			q>>=1;
			p*=p;
			p%=mod;
		}
		return res;
	}
}

import java.math.BigInteger;
import java.util.Scanner;

public class Main
{

	static public BigInteger mod = new BigInteger("1000000007");
	public static void main(String[] args)
	{
		Scanner scan = new Scanner(System.in);
		int r1 = scan.nextInt();
		int c1 = scan.nextInt();
		int r2 = scan.nextInt();
		int c2 = scan.nextInt();

		BigInteger ans = BigInteger.ZERO;
		BigInteger f1 = BigInteger.ZERO;
		for (int i=c1; i<c2+1;i++) {
			if (ans == BigInteger.ZERO) {
				f1 = f(c1, r1);
			} else {
				f1 =  f1.multiply(BigInteger.valueOf((long)(r1+i))).divide(BigInteger.valueOf((long)i));
			}
			ans = ans.add(f1);
			BigInteger f2 = f1;
			for (int j=r1+1;j<r2+1;j++) {
				f2 = f2.multiply(BigInteger.valueOf((long)(j+i))).divide(BigInteger.valueOf((long)j));
				ans = ans.add(f2);
			}
		}
		ans = ans.remainder(mod);
		System.out.println(ans);
	}

	static public BigInteger f2(int r, int c) {

		if (c > r) {
			int tmp = c;
			c = r;
			r = tmp;
		}

	    BigInteger result = BigInteger.ONE;
	    int j = 2;
	    for (int i = c+1; i <= c+r; i++) {
	        result = result.multiply(BigInteger.valueOf(i)).divide(BigInteger.valueOf(j));
	    	j++;
	    }
	    return result;

	}

	static public BigInteger f(int r, int c) {

		if (c > r) {
			int tmp = c;
			c = r;
			r = tmp;
		}

		BigInteger rcf = factorial_m(c,r);
		BigInteger rf = factorial(r);
		BigInteger ans = rcf.divide(rf);
		return ans;
	}
	static public BigInteger factorial(int n) {
	    BigInteger result = BigInteger.ONE;
	    for (int i = 2; i <= n; i++)
	        result = result.multiply(BigInteger.valueOf(i));
	    return result;
	}
	static public BigInteger factorial_m(int c, int r) {
	    BigInteger result = BigInteger.ONE;
	    for (int i = c+1; i <= c+r; i++)
	        result = result.multiply(BigInteger.valueOf(i));
	    return result;
	}

}

import java.util.HashMap;
