public void solve() {
	prepareFact();
	int r[] = ni(2);
	int c[] = ni(2);
	r[0] --;
	r[1] --;
	pow_2 = pows_m(2, (int)1e7);
	long ans = 0;
	ans += cal(c[0], c[1]);
	ans = mod(ans);
	ans -= cal(r[0], c[1]);
	ans = mod(ans);
	ans -= cal(c[0], r[1]);
	ans = mod(ans);
	ans += cal(r[0], r[1]);
	ans = mod(ans);
	prtln(ans);
}

long pow_2[];

long cal(int x, int y) {
	long tmp = 0;
	tmp += pow_2[x + y + 1] - 1;
	tmp = mod(tmp);
	errprtln(tmp);
	for(int i = 0; i <= y; i ++) {
		long tmp2 = C(x + i, i);
		tmp2 *= pow_2[y - i] - 1;
		tmp2 = mod(tmp2);
		tmp = mod(tmp - tmp2);
		errprtln(x, y, tmp2);
	}
	errprtln(tmp);
	for(int i = 0; i <= x; i ++) {
		long tmp2 = C(i + y, i);
		tmp2 *= pow_2[x - i] - 1;
		tmp2 = mod(tmp2);
		tmp = mod(tmp - tmp2);
	errprtln(x, y, tmp2);
	}
	errprtln(tmp);
	return tmp;
}

