public class Main {
	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		int r1 = sc.nextInt();
		int c1 = sc.nextInt();
		int r2 = sc.nextInt();
		int c2 = sc.nextInt();
		sc.close();

		int mod = 1000000007;
		long[] p = new long[1000003];
		long[] pi = new long[1000003];
		p[0] = 1;
		pi[0] = 1;
		for (int i = 1; i < p.length; i++) {
			p[i] = p[i - 1] * i % mod;
			pi[i] = modinv(p[i], mod);
		}

		long v1 = nCr(r2 + c2 + 2, r2 + 1, mod, p, pi);
		long v2 = nCr(r1 + c2 + 1, r1, mod, p, pi);
		long v3 = nCr(r2 + c1 + 1, c1, mod, p, pi);
		long v4 = nCr(r1 + c1, r1, mod, p, pi);
		long ans = v1 - v2 - v3 + v4;
		ans %= mod;
		System.out.println(ans);
	}

	static long nCr(int n, int r, int m, long[] p, long[] pi) {
		return p[n] * pi[r] % m * pi[n - r] % m;
	}

	static long modinv(long a, int m) {
		long b = m;
		long u = 1;
		long v = 0;
		long tmp = 0;

		while (b > 0) {
			long t = a / b;
			a -= t * b;
			tmp = a;
			a = b;
			b = tmp;

			u -= t * v;
			tmp = u;
			u = v;
			v = tmp;
		}

		u %= m;
		if (u < 0) u += m;
		return u;
	}
}

import java.util.*;

class Main{
    public static final int MOD = 1000000007;

    long[] fac, finv, inv;

    void init(int MAX){
        fac  = new long[MAX];
        finv = new long[MAX];
        inv  = new long[MAX];

        fac[0]  = fac[1]  = 1;
        finv[0] = finv[1] = 1;
        inv[1]  = 1;
        for(int i=2; i<MAX; i++){
            fac[i]  = fac[i-1] * i % MOD;
            inv[i]  = MOD - inv[MOD%i] * (MOD/i) % MOD;
            finv[i] = finv[i-1] * inv[i] % MOD;
        }
    }

    long COM(int n, int k){
        if(n < k)return 0;
        if(n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n-k] % MOD) % MOD;
    }

    public Main(){

        Scanner scanner = new Scanner(System.in);
        int X1, X2, Y1, Y2;
        X1 = scanner.nextInt();
        Y1 = scanner.nextInt();
        X2 = scanner.nextInt();
        Y2 = scanner.nextInt();

        init(X2+Y2+3);

        long R = COM(X2+Y2+2, X2+1);
        R = (R - COM(X1+Y2+1, X1)%MOD) % MOD;
        if(R<0) R += MOD;
        R = (R - COM(X2+Y1+1, Y1)%MOD) % MOD;
        if(R<0) R += MOD;
        R = (R + COM(X1+Y1, X1)) % MOD;

        System.out.println(COM(X2+Y2+2, X2+1)+","+COM(X1+Y2+1, X1)+","+COM(X2+Y1+1, Y1)+","+COM(X1+Y1, X1));

        System.out.println(R);
    }

    public static void main(String args[]) throws Exception{
        Main main = new Main();
    }
}

import java.math.BigInteger;
import java.util.Scanner;

public class Main
{

	static public BigInteger mod = new BigInteger("1000000007");
	public static void main(String[] args)
	{
		Scanner scan = new Scanner(System.in);
		int r1 = scan.nextInt();
		int c1 = scan.nextInt();
		int r2 = scan.nextInt();
		int c2 = scan.nextInt();

		BigInteger ans = BigInteger.ZERO;
		BigInteger f1 = BigInteger.ZERO;
		for (int i=c1; i<c2+1;i++) {
			if (ans == BigInteger.ZERO) {
				f1 = f2(c1, r1);
			} else {
				f1 =  f1.multiply(BigInteger.valueOf((long)(r1+i))).divide(BigInteger.valueOf((long)i));
			}
			ans = ans.add(f1);

			BigInteger f2 = f1;
			for (int j=r1+1;j<r2+1;j++) {
				f2 = f2.multiply(BigInteger.valueOf((long)(j+i))).divide(BigInteger.valueOf((long)j));
				ans = ans.add(f2);
			}
		}
		System.out.println(ans.remainder(mod));
	}

	static public BigInteger f2(int r, int c) {

		if (c > r) {
			int tmp = c;
			c = r;
			r = tmp;
		}

	    BigInteger result = BigInteger.ONE;
	    int j = 1;
	    for (int i = c+1; i <= c+r; i++) {
	        result = result.multiply(BigInteger.valueOf(i)).divide(BigInteger.valueOf(j));
	    	j++;
	    }
	    return result;

	}

	static public BigInteger f(int r, int c) {

		if (c > r) {
			int tmp = c;
			c = r;
			r = tmp;
		}

		BigInteger rcf = factorial_m(c,r);
		BigInteger rf = factorial(r);
		BigInteger ans = rcf.divide(rf);
		return ans;
	}
	static public BigInteger factorial(int n) {
	    BigInteger result = BigInteger.ONE;
	    for (int i = 2; i <= n; i++)
	        result = result.multiply(BigInteger.valueOf(i));
	    return result;
	}
	static public BigInteger factorial_m(int c, int r) {
	    BigInteger result = BigInteger.ONE;
	    for (int i = c+1; i <= c+r; i++)
	        result = result.multiply(BigInteger.valueOf(i));
	    return result;
	}

}

