    }

    // a^n mod を計算する
    static long modpow(long a, long n, long mod) {
        long res = 1;
        while (n > 0) {
            if ((n & 1) == 1){
                res = (res * a) % mod;
            }
            a = (a * a) % mod;
            n >>= 1;
        }
        return res;
    }

    // a^{-1} mod を計算する
    static long modinv(long a, long mod) {
        return modpow(a, mod - 2, mod);
