import java.io.*;
import java.util.*;

class Solver {
  final int r1, c1, r2, c2;
  ModCalculator mc;

  Solver(int r1, int c1, int r2, int c2) {
    this.r1 = r1;
    this.c1 = c1;
    this.r2 = r2;
    this.c2 = c2;
  }

  public long solve() {
    mc = new ModCalculator(1_000_000_007L);
    long answer = 0;
    long pathCount = mc.getC(r1 + c1, r1);
    answer = mc.add(answer, pathCount);
    for (int i = r1 + c1 + 1; i <= r2 + c2; i++) {
      pathCount = mc.mul(pathCount, 2);
      if (i - r1 <= c2) {
        pathCount = mc.add(pathCount, mc.getC(i - 1, r1 - 1));
      } else {
        pathCount = mc.sub(pathCount, mc.getC(i - 1, c2));
      }
      if (i - c1 <= r2) {
        pathCount = mc.add(pathCount, mc.getC(i - 1, c1 - 1));
      } else {
        pathCount = mc.sub(pathCount, mc.getC(i - 1, r2));
      }
      answer = mc.add(answer, pathCount);
    }
    return answer;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int r1 = reader.nextInt();
    int c1 = reader.nextInt();
    int r2 = reader.nextInt();
    int c2 = reader.nextInt();
    out.println(new Solver(r1, c1, r2, c2).solve());
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

