        static void Solve()
        {
            var rcrc = Sarray();
            var r1 = (int)rcrc[0];
            var c1 = (int)rcrc[1];
            var r2 = (int)rcrc[2];
            var c2 = (int)rcrc[3];
            var cmb = new Combination(2000007);
            long square(int x, int y) => cmb.nCk(x + y + 2, x + 1);
            var ans = square(r2, c2)
                    - square(r2, c1 - 1)
                    - square(r1 - 1, c2)
                    + square(r1 - 1, c1 - 1);
            WriteLine((ans % Mod + Mod) % Mod);
        }
        public class Combination
        {
            readonly long mod;
            readonly long[] fac, finv, inv;
            public Combination(long n, long mod = 1000000007)
            {
                long max = n + 1;
                this.mod = mod;
                fac = new long[max];
                finv = new long[max];
                inv = new long[max];
                fac[0] = fac[1] = 1;
                finv[0] = finv[1] = 1;
                inv[1] = 1;
                for (int i = 2; i < max; ++i)
                {
                    fac[i] = fac[i - 1] * i % mod;
                    inv[i] = mod - inv[mod % i] * (mod / i) % mod;
                    finv[i] = finv[i - 1] * inv[i] % mod;
                }
            }
            public long nCk(int n, int k)
            {
                if (n < k) return 0;
                if (n < 0 | k < 0) return 0;
                return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
            }
        }
    }
}

