    internal class Program
    {
        private const int p = 1000000007;

        private static void Main(string[] args)
        {
            var input = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToList();
            var r1 = input[0];
            var c1 = input[1];
            var r2 = input[2];
            var c2 = input[3];

            int result = 0;
            for (int i = r1; i <= r2; ++i)
                for (int j = c1; j <= c2; ++j)
                    result = (result + Combi(i + j, i)) % p;

            Console.WriteLine(result);
        }

        private static readonly IDictionary<string, int> memo
            = new Dictionary<string, int>();

        private static int Combi(int n, int k)
        {
            if (k * 2 > n)
                return Combi(n, n - k);

            if (k == 0)
                return 1;
            if (k == 1)
                return n;

            var key = $"{n}:{k}";
            if (memo.ContainsKey(key))
                return memo[key];

            memo[key] = (Combi(n - 1, k) + Combi(n - 1, k - 1)) % p;

            return memo[key];
        }
    }
}

