		{
			var (r1, c1, r2, c2) = cin.ReadValue<long, long, long, long>();
			r1--;
			c1--;
			ModInt ans = ((c2 + 2) * Calc.nCr(r2 + c2 + 2, r2) - r2 - 1) / (r2 + 1);
			ans -= ((c1 + 2) * Calc.nCr(r2 + c1 + 2, r2) - r2 - 1) / (r2 + 1);
			ans -= ((c2 + 2) * Calc.nCr(r1 + c2 + 2, r1) - r1 - 1) / (r1 + 1);
			ans += ((c1 + 2) * Calc.nCr(r1 + c1 + 2, r1) - r1 - 1) / (r1 + 1);
			Console.WriteLine(ans);
		}

