using CompLib.Util;
using System;

public class Program
{
    int R1, R2, C1, C2;

    ModInt[] Fact;
    public void Solve()
    {
        var sc = new Scanner();
        R1 = sc.NextInt();
        C1 = sc.NextInt();
        R2 = sc.NextInt();
        C2 = sc.NextInt();


        Fact = new ModInt[500001];
        Fact[0] = 1;
        for (int i = 1; i <= 500000; i++)
        {
            Fact[i] = Fact[i - 1] * i;
        }
        // f(r,c) = (r+c) C r

        // rを固定
        ModInt ans = 0;
        for(int i = R1; i <= R2; i++)
        {
            ans += Calc(i);
        }

        Console.WriteLine(ans);
    }

    private ModInt Calc(int r)
    {
        return Calc2(r, C2) - Calc2(r, C1 - 1);
    }

    // Σ (r+c) C c
    private ModInt Calc2(int r, int c)
    {
        // r = 0 return = c + 1
        // r = 1 return 1 + 2 + 3 + 4 ...

        // パスカルの三角形の r+1,c

        return C(r + 1 + c, c);

    }

    private ModInt C(int r, int c)
    {
        return Fact[r] * ModInt.Inverse(Fact[r - c] * Fact[c]);
    }

    public static void Main(string[] args) => new Program().Solve();
}


