    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        int r1 = cr;
        int c1 = cr;
        int r2 = cr;
        int c2 = cr;
        factors = Mod.CreateFactor(r2 + c2 + 4);
        return CombSum(r2, c2) - CombSum(r2, c1 - 1) - CombSum(r1 - 1, c2) + CombSum(r1 - 1, c1 - 1);
    }
    Mod.Factor factors;

    Mod CombSum(int r, int c) =>
        factors.Combine(r + c + 2, r + 1) - 1;
