class Program {
  public static void Main() {
    long[] input = Console.ReadLine().Split(' ').Select(i => long.Parse(i)).ToArray();
    long xa = input[0], ya = input[1], xb = input[2], yb = input[3];

    double total = 0;

    for (long i = xa; i <= xb; i++) {
      for (long j = ya; j <= yb; j++) {
        total += Kaizyo(i + j) / (Kaizyo(i) * Kaizyo(j));
      }
    }

    Console.WriteLine(total % (Math.Pow(10.0, 9.0) + 7));
  }

  public static long Kaizyo(double n) {
    double fact;

    if (n == 0)
      fact = 1;
    else
      fact = n * Kaizyo(n - 1);

    return fact;
  }
}

