using System;
using System.Linq;
using CompLib.Mathematics;
using CompLib.Util;

public class Program
{
    int R1, C1, R2, C2;

    ModInt[] F;
    public void Solve()
    {
        var sc = new Scanner();
        R1 = sc.NextInt();
        C1 = sc.NextInt();
        R2 = sc.NextInt();
        C2 = sc.NextInt();

        F = new ModInt[3000001];
        F[0] = 1;
        for (int i = 1; i <= 3000000; i++)
        {
            F[i] = F[i - 1] * i;
        }

        ModInt ans = 0;
        for (int i = R1; i <= R2; i++)
        {
            ans += C(C2 + i + 1, C2);
            ans -= C(C1 + i, C1 - 1);
        }

        Console.WriteLine(ans);
    }

    ModInt C(int n, int m)
    {
        return F[n] * ModInt.Inverse(F[n - m] * F[m]);
    }

