class Program
{
	static void Main(string[] args)
	{
		string[] str = Console.ReadLine().Split();
		long r1 = long.Parse(str[0]);
		long c1 = long.Parse(str[1]);
		long r2 = long.Parse(str[2]);
		long c2 = long.Parse(str[3]);
		long mod = 1000000007;
		long A = 1;
		long B4 = 0;
		for(var i=0;i<=r1-1;i++){
			A = A * (i+c1-1+1) % mod * Mpow(i+1,mod-2,mod) % mod;
			B4 = (B4 + A) % mod;
		}
		long B3 = B4;
		for(var i=r1;i<=r2;i++){
			A = A * (i+c1-1+1) % mod * Mpow(i+1,mod-2,mod) % mod;
			B3 = (B3 + A) % mod;
		}
		A = 1;
		long B2 = 0;
		for(var i=0;i<=r1-1;i++){
			A = A * (i+c2+1) % mod * Mpow(i+1,mod-2,mod) % mod;
			B2 = (B2 + A) % mod;
		}
		long B = B2;
		for(var i=r1;i<=r2;i++){
			A = A * (i+c2+1) % mod * Mpow(i+1,mod-2,mod) % mod;
			B = (B + A) % mod;
		}
		Console.WriteLine((B-B2-B3+B4+mod+mod)%mod);
	}
	public static long Mpow(long x,long n,long m)
	{
		long ans = 1;
		while(n > 0){
			if(n % 2 == 1){
				ans = ans * x % m;
				n -= 1;
			}
			x = x * x % m;
			n /= 2;
		}
		return ans;
	}
}

