const MOD = 1000000007

var fac [2000020]int

func bipow(n, m int) int {
	if m == 0 {
		return 1
	}
	if m%2 == 0 {
		return bipow((n*n)%MOD, m/2)
	} else {
		return (n * bipow(n, m-1)) % MOD
	}
}

func fill_table() {
	fac[0] = 1
	for i := 1; i < 2000020; i++ {
		fac[i] = (fac[i-1] * i) % MOD
	}
}

func comb(n, m int) int {
	a := fac[n]
	b := bipow(fac[m], MOD-2)
	c := bipow(fac[n-m], MOD-2)
	ret := (((a * b) % MOD) * c) % MOD
	return ret
}

func S(r, c int) int {
	ret := 0
	for j := 0; j <= c; j++ {
		ret += comb(j+r+1, r)
		ret %= MOD
	}
	return ret
}

