var fac, ifac []int

func facInit(n int) {
	fac = make([]int,n+1)
	ifac = make([]int,n+1)

	mpow := func (x,n int) int {
		res := 1
		for n!=0 {
			if n&1 == 1 { res = res*x%mod }
			x = x*x%mod; n >>= 1
		}
