    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}

func SumInt(A ...int) int {
  sum := 0
  for _, a := range A {
    sum += a
  }
  return sum
}

func Factorial(N int) (F, Finv, Inv []int) {
  F = make([]int, N + 1)
  Finv = make([]int, N + 1)
  Inv = make([]int, N + 1)
  F[0] = 1
  F[1] = 1
  Finv[0] = 1
  Finv[1] = 1
  Inv[0] = 1
  Inv[1] = 1
  for i := 2; i < N + 1; i++ {
    F[i] = F[i - 1] * i % p
    Inv[i] = p - Inv[p % i] * (p / i) % p
    Finv[i] = Finv[i - 1] * Inv[i] % p
  }
  return
}

func Comb(F, Finv *[]int, A ...int) int {
  S := SumInt(A...)
  C := (*F)[S]
  for _, a := range A {
    C *= (*Finv)[a]
    C %= p
  }
  return C
}

const p = 1000000007

func SC(F, Finv *[]int, X, Y int) int {
  S := 0
  for y := 0; y <= Y; y++ {
    S += Comb(F, Finv, X, y + 1)
    S %= p
  }
  return S
}

func Solve() {
  var r1, c1, r2, c2 int
  NextInt(&r1, &c1, &r2, &c2)
  F, Finv, _ := Factorial(r2 + c2 + 1)
  ans := (SC(&F, &Finv, r2, c2) - SC(&F, &Finv, r2, c1 - 1) - SC(&F, &Finv, r1 - 1, c2) + SC(&F, &Finv, r1 - 1, c1 - 1) + 2 * p) % p
  Write(ans)
  return
}

func main() {
  Solve()
  Output()
}

