var mod int = 1000000007

func main() {
	buf := make([]byte, 0)
	sc.Buffer(buf, mod)
	sc.Split(bufio.ScanWords)
	r1, c1, r2, c2 := iScan(), iScan(), iScan(), iScan()
	f := make([]int, 2100000)
	inv := make([]int, 2100000)
	f[0], inv[0] = 1, 1
	for i := 1; i < 2100000; i++ {
		f[i] = f[i-1] * i % mod
		inv[i] = modinv(f[i], mod)
	}
	ans := path(r2, c2, f, inv) - path(r2, c1-1, f, inv) - path(r1-1, c2, f, inv) + path(r1-1, c1-1, f, inv)
	ans %= mod
	if ans < 0 {
		ans += mod
	}
	fmt.Println(ans)
}
func path(r int, c int, f []int, inv []int) int {
	ret := 0
	for i := c; i <= r+c+1; i++ {
		ret += f[i] * inv[i-c] % mod * inv[c] % mod
		ret %= mod
	}
	return ret
}
func modinv(a, m int) int {
	b, u, v := m, 1, 0
	for {
		t := a / b
		a -= t * b
		u -= t * v
		a, b, u, v = b, a, v, u
		if b == 0 {
			break
		}
	}
	u %= m
	if u < 0 {
		u += m
	}
	return u
}

