	cm.init(int(1e6+1) * 2)
	var ans int64

	ans = cm.calc(r2+c2+2, r2+1) + cm.calc(r1+c1, r1) - cm.calc(r2+1+c1, c1) - cm.calc(r1+1+c2, r1)
