type mint int

func (a *mint) add(b int) { *a = (*a+mint(b))%mod; if *a<0 { *a += mod } }
func (a *mint) sub(b int) { *a = (*a-mint(b))%mod; if *a<0 { *a += mod } }

var fac, ifac []int

func facInit(n int) {
	fac = make([]int,n+1)
	ifac = make([]int,n+1)

	mpow := func (x,n int) int {
		res := 1
		for n!=0 {
			if n&1 == 1 { res = res*x%mod }
			x = x*x%mod; n >>= 1
		}
		return res
	}

	fac[0] = 1; ifac[0] = 1

	for i := 0; i < n; i++ {
		fac[i+1] = fac[i]*(i+1)%mod
		ifac[i+1] = ifac[i]*mpow(i+1,mod-2)%mod
	}
}

func comb(a,b int) int { return (fac[a]*ifac[b]%mod)*ifac[a-b]%mod }
func perm(a,b int) int { return fac[a]*ifac[a-b]%mod }

