class ModInt:

    def __init__(self, mod=1000000007, mem_size=2000000, precalc=True):
        self.mod = mod
        self.mem_factorial = [0] * mem_size
        self.mem_size = mem_size
        if precalc:
            self.mem_factorial[0] = 1
            for i in range(1, mem_size):
                self.mem_factorial[i] = self.mem_factorial[i-1]*i % mod

    def inverse(self, x, mod: int = None):
        if mod is None:
            mod = self.mod
        return int(pow(x, mod - 2, mod))

    def factorial(self, x, mod: int = None):
        if x == 0:
            return 1
        if mod is None:
            mod = self.mod
        if x < self.mem_size and self.mem_factorial[x] > 0:
            pass
        else:
            self.mem_factorial[x] = (self.factorial(x - 1, mod) * x) % mod
        return self.mem_factorial[x]

    def comb(self, m, n, mod: int = None):
        if mod is None:
            mod = self.mod
        a = self.factorial(m, mod)
        b = self.factorial(n, mod)
        c = self.factorial(m - n, mod)
        bc = b * c % mod
        ret = a * self.inverse(bc, mod) % mod
        return ret

