LARGE = 10 ** 9 + 7


def solve_special(r, c):

    if r > 0 and c > 0:
        r, c = max(r, c), min(r, c)
        inv_large = [0] * (c + 2)
        for i in range(1, c + 2):
            inv_large[i] = pow(i, LARGE - 2, LARGE)

        ncr = 1
        res = 0

        for i in range(1, c + 2):
            ncr *= (r + i)
            ncr %= LARGE
            ncr *= inv_large[i]
            ncr %= LARGE
            res += ncr
        return res % LARGE
    else:
        return r + c + 1


