    c = get_cache(i, j)
    if c is not None:
        return c

    cache_i = get_cache(i - 1, j)
    cache_j = get_cache(i, j - 1)
    if cache_i is not None:
        return cache_i * (i + j) // i
    if cache_j is not None:
        return cache_j * (i + j) // j

    raise ValueError('hoge')


