def think(r1, c1, r2, c2):
    mode = 10 ** 9 + 7
    count = 0

    n = r2 + c2
    inverse_fact = [1] * (n + 1)
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i
        fact[i] %= mode
    inverse_fact[n] = pow(fact[n], mode - 2, mode)
    for i in range(n - 1, -1, -1):
        inverse_fact[i] = inverse_fact[i + 1] * (i + 1)
        inverse_fact[i] %= mode

    cache = {}
    for y in range(r1, r2 + 1):
        for x in range(c1, c2 + 1):
            if (x + y, x) in cache:
                count += cache[(x + y, x)]
            else:
                result = combination(x + y, x, fact, inverse_fact, mode)
                cache[(x + y, x)] = result
                cache[(x + y, y)] = result
                count += result
            count %= mode

    return count


def combination(n, r, fact, inverse_fact, mode):
    if r > n or n < 0 or r < 0:
        return 0
    return (fact[n] * inverse_fact[r] * inverse_fact[n - r]) % mode


