        c2: usize
    }
    let d = 1000000007;
    println!("{}", (solve(r2, c2, d) + solve(r1 - 1, c1 - 1, d) + 2 * d - solve(r1 - 1, c2, d) - solve(r2, c1 - 1, d)) % d);
}

fn solve(r: usize, c: usize, d: usize) -> usize {
    (r + 2..r + c + 3).fold(1, |ac, x| ac * x % d) * inv_m((1..c + 2).fold(1, |ac, x| ac * x % d), d) % d - 1
}

fn pow_m(n: usize, mut p: usize, d: usize) -> usize {
    let mut r = n;
    let mut ret = 1;
    while p > 0 {
        if p % 2 == 0 {
            r = r * r % d;
            p /= 2;
        } else {
            ret = ret * r % d;
            p -= 1;
        }
    }
    ret
}

fn inv_m(n: usize, d: usize) -> usize {
    pow_m(n, d - 2, d)
}

const M : usize = 1000000007;

type Number = usize;

fn main()
{
    let mut line = String::new();
    std::io::stdin().read_line(&mut line).unwrap();

    let data: Vec<&str> = line.split_whitespace().collect();
    let r1 = data[0].parse().unwrap_or(0);
    let c1 = data[1].parse().unwrap_or(0);
    let r2 = data[2].parse().unwrap_or(0);
    let c2 = data[3].parse().unwrap_or(0);

    let n = r2 + c2 + 2;

    let mut facts : Vec<Number> = vec![1; n];
    let mut finvs : Vec<Number> = vec![1; n];
    let mut invs  : Vec<Number> = vec![1; n];

    invs[0] = 0;

    for i in 2..n
    {
        facts[i] = (i * facts[i - 1]) % M;
        invs[i]  = M - (invs[M % i] * (M / i)) % M;
        finvs[i] = (finvs[i - 1] * invs[i]) % M;
    }

    let ncr = |n: Number, r: Number| -> Number
    {
        (facts[n] * ((finvs[r] * finvs[n - r]) % M)) % M
    };

    let sum = |x: Number, y: Number| -> Number
    {
        (1 .. (x + 2)).fold(0, |val, index| (val + ncr(y + index, index)) % M)
    };

    let a = sum(r2, c2);
    let b = sum(r1 - 1, c2);
    let c = sum(r2, c1 - 1);
    let d = sum(r1 - 1, c1 - 1);

    let ans = (a + d - b - c) % M;
    println!("{}", ans);
}

