use std::ops::Neg;
use std::ops::Sub;


#[derive(Debug, Clone, Copy, Eq, PartialEq, Ord, PartialOrd)]
struct Mod {
  val: usize,
}

// 和を定義
impl Add for Mod {
  type Output = Mod;
  // O(1)
  fn add(self, other: Mod) -> Mod {
    Mod {
      val: (self.val + other.val) % MOD,
    }
  }
}

// 差を定義
impl Sub for Mod {
  type Output = Mod;

  // O(1)
  fn sub(self, other: Mod) -> Mod {
    let mx = max(self.val, other.val);
    let mn = min(self.val, other.val);

    Mod {
      val: (mx - mn) % MOD,
    }
  }
}

// 積を定義
impl Mul for Mod {
  type Output = Mod;

  // O(1)
  fn mul(self, other: Mod) -> Mod {
    Mod {
      val: (self.val * other.val) % MOD,
    }
  }
}

// 加法単位元
impl Neg for Mod {
  type Output = Mod;

  // O(1)
  fn neg(self) -> Mod {
    Mod {
      val: MOD - self.val,
    }
  }
}

// 逆元を定義
// フェルマーの小定理により実装
impl Div for Mod {
  type Output = Mod;

  //O(logN)
  fn div(self, other: Mod) -> Mod {
    self * other.inv()
  }
}

impl Mod {
  // コンストラクター
  fn new(n: usize) -> Mod {
    Mod { val: n % MOD }
  }

  // 加法単位元
  fn new_zero() -> Mod {
    Mod { val: 0 }
  }

  // 乗法単位元
  fn new_one() -> Mod {
    Mod { val: 1 }
  }

  // 加法逆元
  // 上記にて定義

  // 乗法逆元
  fn inv(self) -> Mod {
    if self.val == 0 {
      panic!("zero divide");
    }
    self.pow(MOD - 2)
  }

  // 累乗を定義
  // O(logN)
  fn pow(self, n: usize) -> Mod {
    let mut res = 1;
    let mut a = self.unwrap();
    let mut n = n;

    while n > 0 {
      if n % 2 == 0 {
        a = a * a;
        n /= 2;
      } else {
        res = res * a;
        a = a * a;
        n /= 2;
      }
      res %= MOD;
      a %= MOD;
    }
    Mod::new(res)
  }

  // 最大公約数
  // O(logN)
  fn gcd(self, other: Mod) -> usize {
    let mut x = self.val;
    let mut y = other.val;
    while y != 0 {
      let t = y;
      y = x % y;
      x = t;
    }
    x
  }

  // 階乗
  // O(N)
  fn fact(self) -> Mod {
    let mut res = 1;
    for i in 1..self.val + 1 {
      res *= i;
      res %= MOD;
    }

    Mod::new(res)
  }

  // 順列
  fn perm(self, other: Mod) -> Mod {
    let mut res = Mod::new_one();
    for x in (self.val - other.val + 1)..self.val + 1 {
      res = res * Mod::new(x);
    }

    res
  }

  // 組み合わせ O(N)
  fn conb(self, other: Mod) -> Mod {
    if self < other {
      return Mod::new_zero();
    }
    self.fact() / (other.fact() * (self - other).fact())
  }
  fn unwrap(self) -> usize {
    self.val % MOD
  }
}

#[derive(Debug, Clone, Eq, PartialEq, Ord, PartialOrd)]
struct ModConb {
  table: Vec<usize>,
  table_inv: Vec<usize>,
  n: usize,
}

impl ModConb {
  // O(N)
  fn new(n: usize) -> ModConb {
    // 階乗のテーブル
    let mut table = vec![0; n + 1];
    // 逆元計算用テーブル
    let mut table_calc = vec![0; n + 1];
    // 逆元のテーブル
    let mut table_inv = vec![0; n + 1];

    // init
    table[0] = 1;
    table[1] = 1;
    table_calc[0] = 0;
    table_calc[1] = 1;
    table_inv[0] = 1;
    table_inv[1] = 1;

    for i in 2..n + 1 {
      table[i] = table[i - 1] * i % MOD;
      table_calc[i] = ((MOD - table_calc[MOD % i]) * (MOD / i)) % MOD;
      table_inv[i] = table_inv[i - 1] * table_calc[i] % MOD;
    }

    ModConb {
      table: table,
      table_inv: table_inv,
      n: n,
    }
  }
  // O(1)
  fn get(&self, i: usize, j: usize) -> Mod {
    if i < j {
      return Mod { val: 0 };
    }
    Mod {
      val: ((self.table[i] * self.table_inv[j]) % MOD) * self.table_inv[i - j] % MOD,
    }
  }
}

use std::io::{stdin, Read};
const MOD: usize = 1000000007;

fn gcd(a: usize, b: usize) -> usize {
    match b {
        0 => a,
        _ => gcd(b, a % b),
    }
}

fn powmod(base: usize, exp: usize, m: usize) -> usize {
    let b: Vec<bool> = format!("{:b}", exp)
        .chars()
        .map(|x| x.to_digit(10).unwrap() != 0)
        .collect();
    let mut v = 1;
    for bi in b {
        v *= v;
        v %= m;
        if bi {
            v *= base;
            v %= m
        }
    }
    return v % m;
}

fn invmod(x: usize, m: usize) -> usize {
    powmod(x, m - 2, m)
}

fn prime_factors(x: usize) -> Vec<usize> {
    let mut res = vec![];
    let mut y = x;
    let mut p = 2;
    let upper = (y as f64).sqrt() as usize;
    while y > 1 && p <= upper {
        match y % p {
            0 => {
                res.push(p);
                y /= p;
            }
            _ => {
                p += 1;
            }
        }
    }
    if y > 1 {
        res.push(y)
    }
    return res;
}

fn get_factorials(n: usize, m: usize) -> Vec<usize> {
    let mut res = vec![0; n as usize];
    res[0] = 1;
    for i in 1..(n as usize) {
        res[i] = (res[i - 1] * (i as usize)) % m;
    }
    res
}

fn get_facinvs(n: usize, m: usize, facts: &Vec<usize>) -> Vec<usize> {
    let mut res = vec![0; n];
    res[n - 1] = invmod(facts[n - 1], m);
    for i in (0..(n - 1)).rev() {
        res[i] = (res[i + 1] * (i + 1)) % m;
    }
    res
}

fn combmod(a: usize, b: usize, m: usize, facts: &Vec<usize>, invs: &Vec<usize>) -> usize {
    if a < b {
        0
    } else {
        (((facts[a as usize] * invs[b as usize]) % m) * invs[(a - b) as usize]) % m
    }
}

macro_rules! parse {
    ($iter: ident) => {
        $iter.next().unwrap().parse().unwrap()
    };
    ($iter: ident,2) => {
        (parse!($iter), parse!($iter))
    };
    ($iter: ident,3) => {
        (parse!($iter), parse!($iter), parse!($iter))
    };
    ($iter: ident,4) => {
        (parse!($iter), parse!($iter), parse!($iter), parse!($iter))
    };
    ($iter: ident, $n: ident) => {
        (&mut $iter).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut it = s.split_whitespace();
    const n: usize = 1;
    let v = vec![vec![0; n]; n];
    let (r1, c1, r2, c2): (usize, usize, usize, usize) = parse!(it, 4);
    let facts = get_factorials(1000010, MOD);
    let invs = get_facinvs(1000010, MOD, &facts);
    let f = |i, j| combmod(i + j, i, MOD, &facts, &invs);
    let g = |i, j| -> usize { (0..(i + 1)).map(|x| f(x + 1, j)).sum() };
    let ret = (100 * MOD + g(r2, c2) + g(r1 - 1, c1 - 1)) - (g(r2, c1 - 1) + g(r1 - 1, c2));
