const M: usize = 1_000_000_007;

struct Combination {
    modp: usize,
    mfact: Vec<usize>,
    rfact: Vec<usize>,
}

impl Combination {
    fn new(size: usize, modp: usize) -> Self {
        let mut rfact = vec![0; size + 1];
        let mut mfact = vec![0; size + 1];
        mfact[0] = 1;
        for i in 1..mfact.len() {
            mfact[i] = (mfact[i - 1] * i) % modp;
        }
        rfact[size] = Self::inv(mfact[size], modp);
        for i in (0..size).rev() {
            rfact[i] = rfact[i + 1] * (i + 1) % modp;
        }

        Combination {
            modp: modp,
            mfact: mfact,
            rfact: rfact,
        }
    }

    fn pow(mut x: usize, mut n: usize, modp: usize) -> usize {
        let mut ret = 1;
        while n > 0 {
            if n & 1 > 0 {
                ret *= x;
                ret %= modp;
            }
            x *= x;
            x %= modp;
            n >>= 1;
        }
        ret
    }

    fn inv(x: usize, modp: usize) -> usize {
        Self::pow(x, modp - 2, modp)
    }

    fn C(&self, p: usize, q: usize) -> usize {
        if p < q {
            return 0;
        }
        (((self.mfact[p] * self.rfact[q]) % self.modp) * self.rfact[p - q]) % self.modp
    }
}

fn g(r: usize, c: usize, comb: &Combination) -> usize {
    (comb.C(r + c + 2, c + 1) + M - 1) % M
}

fn main() {
    input! {
        r1: usize1,
        c1: usize1,
        r2: usize,
        c2: usize,
    }
    let comb = Combination::new(2000001, M);

    let mut ans = g(r2, c2, &comb);
    ans += M - g(r2, c1, &comb);
    ans %= M;
    ans += M - g(c2, r1, &comb);
    ans %= M;
    ans += g(r1, c1, &comb);
    ans %= M;

    println!("{}", ans);
}

