fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let mut r1: usize = sc.read();
    let mut c1: usize = sc.read();
    let r2: usize = sc.read();
    let c2: usize = sc.read();
    r1 -= 1;
    c1 -= 1;
    let mut result = ModInt::new(0);

    let mod_util = ModUtil::new(2000010, 1e9 as usize + 7 as usize);
    result += g(r2, c2, &mod_util);
    result -= g(r1, c2, &mod_util);
