fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());
    input!{
        r1:i64,c1:i64,r2:i64,c2:i64
    }
    let mo = 1_000_000_007;
    let mc = ModComb::new(1000000, mo);
    // f(r,c) = nCk(r+c,r)
    // f(r+1,c) = f(r,0)+f(r,1)+...f(r,c) = fsum(r,c)
    // g(r,c) = fsum(0,c)+fsum(1,c)+...+fsum(r,c)
    let fsum = |r:i64,c:i64| {
        mc.nCk(r+c+1,c)
    };
    let g = |r:i64,c:i64| -> Mod {
        let mut tot = 0;
        for i in 0..r+1 {
            tot += fsum(i,c);
            tot %= mo;
        }
        tot.into()
    };
    let ans = g(r2,c2) - g(r1-1,c2) - g(r2,c1-1) + g(r1-1,c1-1);
    writeln!(out,"{}",ans);
}
