type ModInt = mod_int::ModInt<usize>;
const MAX_RC: usize = 1000010;
const MOD: i64 = 1e9 as i64 + 7;

fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let r1: usize = sc.read();
    let c1: usize = sc.read();
    let r2: usize = sc.read();
    let c2: usize = sc.read();

    let mut result = ModInt::new(0);
    let util = ModUtil::new(2 * MAX_RC, MOD as usize);
    let mut rows = vec![0; MAX_RC];
    let mut cols = vec![0; MAX_RC];
    let mut cnt = 0;
    for i in (c1..c2 + 1).rev() {
        let n = r2 - r1 + 1;
        let sum = n * (2 * 1 + (n - 1) * cnt) / 2;
        cols[i] = sum % MOD as usize;
        cnt += 1;
    }
    cnt = 0;
    for i in (r1..r2 + 1).rev() {
        let n = c2 - c1 + 1;
        let sum = n * (2 + (n - 1) * cnt) / 2;
        rows[i] = sum % MOD as usize;
        cnt += 1;
    }
    let mut tmp = ModInt::new(0);
    for x in (r1..r2 + 1).rev() {
        let y = c1 - 1;
        tmp += rows[x];
        result += tmp * util.combination(x + y, x);
    }
    tmp = ModInt::new(0);
    for y in (c1..c2 + 1).rev() {
        let x = r1 - 1;
        tmp += cols[y];
        result += tmp * util.combination(x + y, x);
    }
    println!("{}", result.0);
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}

