const MOD: i64 = 1000000007i64;
fn factorial(upper_limit: usize) -> (Vec<i64>, Vec<i64>) {
    let mut fact = vec![1i64; upper_limit + 1];
    let mut div = vec![1i64; upper_limit + 1];
    let mut inverse = vec![1i64; upper_limit + 1];
    for i in 2 ..= upper_limit {
        fact[i] = i as i64 * fact[i - 1] % MOD;
        div[i] = (MOD - MOD / i as i64) * div[(MOD % i as i64) as usize] % MOD;
        inverse[i] = div[i] * inverse[i - 1] % MOD;
    }
    (fact, inverse)
}
fn main() {
    read!(r1: i32, c1: i32, r2: i32, c2: i32);
    let (fact, inverse) = factorial((r2 + c2) as usize);
    let combination = |n: i32, r: i32| fact[n as usize] * inverse[r as usize] % MOD * inverse[(n - r) as usize] % MOD;
    let f = |r: i32, c: i32| combination(r + c, r);
    let mut line_sum = f(r1, c1);
    let mut result = line_sum;
    let mut r_min = r1;
    let mut r_max = r1;
    for d in r1 + c1 + 1 ..= r2 + c2 {
        let next_r_min = max(r1, d - c2);
        let next_r_max = min(r2, d - c1);
        line_sum = (line_sum << 1) % MOD;
        line_sum += if next_r_min != r_min {
            MOD - combination(d - 1, r_min)
        }else {
            combination(d - 1, r_min - 1)
        };
        line_sum += if next_r_max != r_max {
            combination(d - 1, r_max + 1)
        }else {
            MOD - combination(d - 1, r_max)
        };
        line_sum %= MOD;
        result += line_sum;
        r_min = next_r_min;
        r_max = next_r_max;
    }
    println!("{}", result % MOD);
}

