    fn combination(&self, n: usize, r: usize) -> Modi64 {
        if r <= n {
            self.fact[n] * self.inv_fact[r] * self.inv_fact[n - r]
        } else {
            0.into()
        }
    }
    fn f(&self, r: usize, c: usize) -> Modi64 {
        self.combination(r + c + 2, c + 1) - 1.into()
    }
}
fn main() {
    input! { r1,c1,r2,c2 };
    let cmb = MemorizedFactorial::new(r2 + c2 + 5);
    let mut ans = Modi64(0);
    ans += cmb.f(r2, c2);
    ans -= cmb.f(r2, c1 - 1);
    ans -= cmb.f(r1 - 1, c2);
    ans += cmb.f(r1 - 1, c1 - 1);
    println!("{}", ans.0);
}

