    static DEC_DIGITS_LUT: &'static [u8; 200] = b"0001020304050607080910111213141516171819\
            2021222324252627282930313233343536373839\
            4041424344454647484950515253545556575859\
            6061626364656667686970717273747576777879\
            8081828384858687888990919293949596979899";

    fn write_int<W: Write>(mut writer: W, mut n: u64, is_negative: bool) {
        unsafe {
            let mut buf: [u8; 39] = mem::uninitialized();
            let buf_ptr_start = buf.as_mut_ptr().offset(39);
            let mut buf_ptr = buf_ptr_start;
            let lut_ptr = DEC_DIGITS_LUT.as_ptr();

            while n >= 10000 {
                let rem = (n % 10000) as isize;
                n /= 10000;

                let d1 = (rem / 100) << 1;
                let d2 = (rem % 100) << 1;
                buf_ptr = buf_ptr.offset(-4);
                ptr::copy_nonoverlapping(lut_ptr.offset(d1), buf_ptr, 2);
                ptr::copy_nonoverlapping(lut_ptr.offset(d2), buf_ptr.offset(2), 2);
            }

            let mut n = n as isize; // possibly reduce 64bit math

            // decode 2 more chars, if > 2 chars
            if n >= 100 {
                let d1 = (n % 100) << 1;
                n /= 100;
                buf_ptr = buf_ptr.offset(-2);
                ptr::copy_nonoverlapping(lut_ptr.offset(d1), buf_ptr, 2);
            }

            // decode last 1 or 2 chars
            if n < 10 {
                buf_ptr = buf_ptr.offset(-1);
                *buf_ptr = (n as u8) + b'0';
            } else {
                let d1 = n << 1;
                buf_ptr = buf_ptr.offset(-2);
                ptr::copy_nonoverlapping(lut_ptr.offset(d1), buf_ptr, 2);
            }

            if is_negative {
                buf_ptr = buf_ptr.offset(-1);
                *buf_ptr = b'-';
            }

            let buf_slice =
                slice::from_raw_parts(buf_ptr, buf_ptr_start as usize - buf_ptr as usize);

            writer.write_all(buf_slice).unwrap();
        }
    }

    pub trait Writable {
        fn display<W: Write>(&self, writer: &mut W);
    }

    impl Writable for str {
        #[inline]
        fn display<W: Write>(&self, writer: &mut W) {
            writer.write_all(self.as_bytes()).unwrap()
        }
    }

    impl<'a> Writable for &'a str {
        #[inline]
        fn display<W: Write>(&self, writer: &mut W) {
            writer.write_all(self.as_bytes()).unwrap()
        }
    }

    impl Writable for String {
        #[inline]
        fn display<W: Write>(&self, writer: &mut W) {
            writer.write_all(self.as_bytes()).unwrap()
        }
    }

    impl Writable for bool {
        #[inline]
        fn display<W: Write>(&self, writer: &mut W) {
            let s: &'static [u8] = if *self { b"Yes" } else { b"No" };
            writer.write_all(s).unwrap();
        }
    }

    macro_rules! impl_writable_int {
        ($($int:ty)*) => {
            $(
                impl Writable for $int {
                    #[allow(unused_comparisons)]
                    fn display<W: Write>(&self, writer: &mut W) {
                        let is_negative = !(*self >= 0);
                        let abs = if is_negative {
                            (!*self as u64).wrapping_add(1)
                        } else {
                            *self as u64
                        };
                        write_int(writer, abs, is_negative);
                    }
                }
            )*
        };
    }

    macro_rules! impl_writable_float {
        ($($float:ty)*) => {
            $(
                impl Writable for $float {
                    #[inline]
                    fn display<W: Write>(&self, writer: &mut W) {
                        write!(writer, "{}", *self).unwrap();
                    }
                }
            )*
        }
    }

    impl_writable_int!(u8 u16 u32 u64 usize i8 i16 i32 i64 isize);
    impl_writable_float!(f32 f64);

    pub static mut SCANNER: *mut StdinScanner = 0 as *mut StdinScanner;
    pub static mut WRITER: *mut StdoutWriter = 0 as *mut StdoutWriter;

    #[inline]
    pub fn atcoder_initialize() {
        unsafe {
            SCANNER = mem::transmute(Box::new(StdinScanner::new()));
            WRITER = mem::transmute(Box::new(StdoutWriter::new()));
        }
    }

    #[inline]
    pub fn atcoder_finish() {
        unsafe {
            (*WRITER).flush().unwrap();
        }
    }
}

macro_rules! input {
    () => {};
    (@scanner $scanner:ident, @pred [ $($pred:tt)* ], $var:tt : $t:tt) => {
        let $($pred)* $var = scan!($scanner, $t);
    };
    (@scanner $scanner:ident,) => {};
    (@scanner $scanner:ident, $var:tt : $t:tt) => {
        input!(@scanner $scanner, @pred [], $var : $t);
    };
    (@scanner $scanner:ident, mut $var:tt : $t:tt) => {
        input!(@scanner $scanner, @pred [mut], $var : $t);
    };
    (@scanner $scanner:ident, $var:tt : $t:tt, $($r:tt)*) => {
        input!(@scanner $scanner, $var : $t);
        input!(@scanner $scanner, $($r)*);
    };
    (@scanner $scanner:ident, mut $var:tt : $t:tt, $($r:tt)*) => {
        input!(@scanner $scanner, mut $var : $t);
        input!(@scanner $scanner, $($r)*);
    };
    ($($r:tt)*) => {
        let scanner_ref = unsafe { &mut *$crate::utils::SCANNER };
        input!(@scanner scanner_ref, $($r)*);
    }
}

macro_rules! scan {
    ($scanner:ident, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| scan!($scanner; $t)).collect::<Vec<_>>()
    };
    ($scanner:ident, usize1) => {
        scan!($scanner; usize) - 1
    };
    ($scanner:ident, line) => {
        $scanner.readl().to_string()
    };
    ($scanner:ident, $t:ty) => {
        $scanner.read::<$t>()
    };
}

macro_rules! pprint {
    ($value:expr) => {
        unsafe {
            (*$crate::utils::WRITER).write($value);
        }
    };
    ($value:expr, $($r:tt)*) => {
        let writer = unsafe { &*$crate::utils::WRITER };
        writer.write($value);
        writer.write(" ");
        pprint!($($r)*);
    };
}

macro_rules! pprintln {
    ($value:expr) => {
        unsafe {
            (*$crate::utils::WRITER).writeln($value);
        }
    };
    ($value:expr, $($r:tt)*) => {
        let writer = unsafe { &*$crate::utils::WRITER };
        writer.write($value);
        writer.write(" ");
        pprintln!($($r)*);
    };
}

macro_rules! atcoder_main {
    ($func:ident) => {
        fn main() {
            $crate::utils::atcoder_initialize();
            $func();
            $crate::utils::atcoder_finish();
        }
    };
}

use std::ops::{Add, AddAssign, Sub, SubAssign, Mul, MulAssign, Div, DivAssign};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModU64 {
    num: u64,
    prime: u64,
}

impl ModU64 {
    pub fn new(num: u64, prime: u64) -> ModU64 {
        ModU64 {
            num: num % prime,
            prime: prime
        }
    }

    pub fn pow(&self, mut n: u64) -> ModU64 {
        let mut a = self.num;
        let mut res = 1;
        while n > 0 {
            if n & 1 == 1 {
                res = res * a % self.prime;
            }
            a = a * a % self.prime;
            n >>= 1;
        }

        return ModU64::new(res, self.prime);
    }

    pub fn recip(&self) -> ModU64 {
        return self.pow(self.prime - 2);
    }

    pub fn to_u64(&self) -> u64 {
        self.num
    }
}

impl AddAssign<u64> for ModU64 {
    fn add_assign(&mut self, rhs: u64) {
        self.num = (self.num + rhs) % self.prime;
    }
}

impl SubAssign<u64> for ModU64 {
    fn sub_assign(&mut self, rhs: u64) {
        let tmp = rhs % self.prime;
        if self.num >= tmp {
            self.num -= tmp;
        } else {
            self.num += self.prime - tmp;
        }
    }
}

impl MulAssign<u64> for ModU64 {
    fn mul_assign(&mut self, rhs: u64) {
        // TODO: avoid overflow
        self.num *= rhs;
        self.num %= self.prime;
    }
}

impl DivAssign<u64> for ModU64 {
    fn div_assign(&mut self, rhs: u64) {
        *self *= ModU64::new(rhs, self.prime).recip().num;
    }
}

impl Add<u64> for ModU64 {
    type Output = ModU64;
    fn add(self, rhs: u64) -> ModU64 {
        let mut cp = self.clone();
        cp += rhs;
        return cp;
    }
}

impl Sub<u64> for ModU64 {
    type Output = ModU64;
    fn sub(self, rhs: u64) -> ModU64 {
        let mut cp = self.clone();
        cp -= rhs;
        return cp;
    }
}

impl Mul<u64> for ModU64 {
    type Output = ModU64;
    fn mul(self, rhs: u64) -> ModU64 {
        let mut cp = self.clone();
        cp *= rhs;
        return cp;
    }
}

impl Div<u64> for ModU64 {
    type Output = ModU64;
    fn div(self, rhs: u64) -> ModU64 {
        let mut cp = self.clone();
        cp /= rhs;
        return cp;
    }
}

#[derive(Debug)]
struct ModCombination {
    prime: u64,
    fact: Vec<u64>,
    ifact: Vec<u64>,
}

impl ModCombination {
    pub fn with_capacity(capacity: usize, prime: u64) -> ModCombination {
        let mut fact = Vec::with_capacity(capacity);
        let mut ifact = Vec::with_capacity(capacity);
        fact.push(1);
        ifact.push(1);

        ModCombination {
            prime: prime,
            fact: fact,
            ifact: ifact,
        }
    }

    pub fn run(&mut self, n: u64, r: u64) -> u64 {
        assert!(n < self.prime);

        if n < r {
            return 0;
        }

        if r == 0 || n == r {
            return 1;
        }

        self.update_factorial(n);

        unsafe {
            let n_fac = self.fact.get_unchecked(n as usize);
            let r_fac = self.ifact.get_unchecked(r as usize);
            let npr_fac = self.ifact.get_unchecked((n - r) as usize);

            n_fac * (r_fac * npr_fac % self.prime) % self.prime
        }
    }

    fn update_factorial(&mut self, n: u64) {
        let current_size = self.fact.len() as u64;
        if current_size > n {
            return;
        }

        self.fact.reserve((n + 1) as usize);
        self.ifact.reserve((n + 1) as usize);

        unsafe {
            self.ifact.set_len((n + 1) as usize);
        }

        let mut last_fact = self.fact.last().unwrap().clone();
        for i in current_size..n + 1 {
            last_fact = last_fact * i % self.prime;
            self.fact.push(last_fact);
        }

        let mut last_ifact = ModU64::new(last_fact, self.prime).recip().num;
        self.ifact[n as usize] = last_ifact;
        for i in (current_size..n).rev() {
            last_ifact = last_ifact * (i + 1) % self.prime;
            unsafe {
                *self.ifact.get_unchecked_mut(i as usize) = last_ifact;
            }
        }
    }
}

fn run() {
    input! {
        r1: u64,
        c1: u64,
        r2: u64,
        c2: u64,
    }

    let mut combinator = ModCombination::with_capacity(2000005, 1000000007);
    let mut g = |r: u64, c: u64| -> u64 {
        combinator.run(r + c + 2, c + 1)
    };

    let mut result = ModU64::new(0, 1000000007);
    result += g(r2, c2);
    result += g(r1 - 1, c1 - 1);
    result -= g(r1 - 1, c2);
    result -= g(r2, c1 - 1);

    pprintln!(result.to_u64());
}

atcoder_main!(run);

use std::io::Read;

fn read<T: std::str::FromStr>() -> T {
    let token: String = std::io::stdin()
        .bytes()
        .map(|c| c.ok().unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

mod mint {
    use std::ops::{Add, AddAssign, BitAnd, Div, Mul, Rem, Shr, Sub};

    #[derive(Copy, Clone)]
    pub struct Mint<T> {
        x: T,
        mo: T,
    }
    impl<T> Mint<T>
    where
        T: Copy,
    {
        pub fn new(x: T, mo: T) -> Mint<T> {
            Mint { x, mo }
        }
    }
    impl<T> Mint<T>
    where
        T: Copy,
    {
        pub fn val(&self) -> T {
            self.x
        }
        pub fn mo(&self) -> T {
            self.mo
        }
    }
    impl<T> Add<T> for Mint<T>
    where
        T: Copy,
        T: Add<Output = T>,
        T: Rem<Output = T>,
    {
        type Output = Mint<T>;
        fn add(self, rhs: T) -> Mint<T> {
            Mint::new((self.val() + rhs % self.mo()) % self.mo(), self.mo())
        }
    }
    impl<T> Add<Mint<T>> for Mint<T>
    where
        T: Copy,
        Mint<T>: Add<T, Output = Mint<T>>,
    {
        type Output = Mint<T>;
        fn add(self, rhs: Mint<T>) -> Mint<T> {
            self + rhs.val()
        }
    }
    impl<T> Sub<T> for Mint<T>
    where
        T: Copy,
        T: Add<Output = T>,
        T: Sub<Output = T>,
        T: Rem<Output = T>,
    {
        type Output = Mint<T>;
        fn sub(self, rhs: T) -> Mint<T> {
            Mint::new(
                (self.val() + self.mo() - rhs % self.mo()) % self.mo(),
                self.mo(),
            )
        }
    }
    impl<T> Sub<Mint<T>> for Mint<T>
    where
        T: Copy,
        Mint<T>: Sub<T, Output = Mint<T>>,
    {
        type Output = Mint<T>;
        fn sub(self, rhs: Mint<T>) -> Mint<T> {
            self - rhs.val()
        }
    }
    impl<T> Mul<T> for Mint<T>
    where
        T: Copy,
        T: Mul<Output = T>,
        T: Rem<Output = T>,
    {
        type Output = Mint<T>;
        fn mul(self, rhs: T) -> Mint<T> {
            Mint::new((self.val() * rhs % self.mo()) % self.mo(), self.mo())
        }
    }
    impl<T> Mul<Mint<T>> for Mint<T>
    where
        T: Copy,
        Mint<T>: Mul<T, Output = Mint<T>>,
    {
        type Output = Mint<T>;
        fn mul(self, rhs: Mint<T>) -> Mint<T> {
            self * rhs.val()
        }
    }

    impl<T> Mint<T>
    where
        T: Copy,
        T: Sub<Output = T>,
        T: Div<Output = T>,
        T: PartialOrd,
        T: PartialEq,
        T: BitAnd<Output = T>,
        T: Shr<Output = T>,
        Mint<T>: Mul<Output = Mint<T>>,
    {
        pub fn pow(self, y: T) -> Mint<T> {
            let one = self.mo() / self.mo();
            let zero = self.mo() - self.mo();
            let mut res = Mint::one(self.mo());
            let mut base = self;
            let mut exp = y;
            while exp > zero {
                if (exp & one) == one {
                    res = res * base;
                }
                base = base * base;
                exp = exp >> one;
            }
            res
        }
    }
    impl<T> Div<T> for Mint<T>
    where
        T: Copy,
        T: Sub<Output = T>,
        T: Div<Output = T>,
        T: PartialOrd,
        T: PartialEq,
        T: BitAnd<Output = T>,
        T: Shr<Output = T>,
        Mint<T>: Mul<Output = Mint<T>>,
    {
        type Output = Mint<T>;
        fn div(self, rhs: T) -> Mint<T> {
            let one = self.mo() / self.mo();
            self * Mint::new(rhs, self.mo()).pow(self.mo() - one - one)
        }
    }
    impl<T> Div<Mint<T>> for Mint<T>
    where
        T: Copy,
        Mint<T>: Div<T, Output = Mint<T>>,
    {
        type Output = Mint<T>;
        fn div(self, rhs: Mint<T>) -> Mint<T> {
            self / rhs.val()
        }
    }
    impl<T> Mint<T>
    where
        T: Copy,
        T: Div<Output = T>,
        Mint<T>: Div<Output = Mint<T>>,
    {
        pub fn inv(self) -> Mint<T> {
            Mint::one(self.mo()) / self
        }
    }
    impl<T> std::fmt::Display for Mint<T>
    where
        T: Copy + std::fmt::Display,
    {
        fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
            write!(f, "{}", self.val())
        }
    }
    impl<T> Mint<T>
    where
        T: Copy,
        T: Sub<Output = T>,
    {
        pub fn zero(mo: T) -> Mint<T> {
            Mint { x: mo - mo, mo }
        }
    }
    impl<T> Mint<T>
    where
        T: Copy,
        T: Div<Output = T>,
    {
        pub fn one(mo: T) -> Mint<T> {
            Mint { x: mo / mo, mo }
        }
    }
}

use mint::Mint;

fn factorials(n: usize, mo: usize) -> (Vec<Mint<usize>>, Vec<Mint<usize>>) {
    let mut fac = vec![Mint::new(0, mo); n];
    let mut fac_inv = vec![Mint::new(0, mo); n];
    fac[0] = Mint::new(1, mo);
    for i in 1..n {
        fac[i] = fac[i - 1] * i;
    }
    fac_inv[n - 1] = fac[n - 1].inv();
    for i in (0..n - 1).rev() {
        fac_inv[i] = fac_inv[i + 1] * (i + 1);
    }
    (fac, fac_inv)
}

fn main() {
    let r1: usize = read();
    let c1: usize = read();
    let r2: usize = read();
    let c2: usize = read();

    let mo = 1000000007;
    let solve = |r: usize, c: usize| -> Mint<usize> {
        let (fac, fac_inv) = factorials(r + c + 2, mo);
        let binom = |a: usize, b: usize| {
            if a < b {
                return Mint::new(0, mo);
            }
            fac[a] * fac_inv[b] * fac_inv[a - b]
        };
        let mut ans = Mint::new(0, mo);
        for i in 0..=r {
            ans = ans + binom((i + 1) + c, c);
        }
        ans
    };
    let mut ans = Mint::new(0, mo);
    ans = ans + solve(r2, c2);
    ans = ans - solve(r1 - 1, c2);
    ans = ans - solve(r2, c1 - 1);
    ans = ans + solve(r1 - 1, c1 - 1);
    println!("{}", ans);
}

pub fn main() {
    let (r1, c1, r2, c2): (i64, i64, i64, i64) = {
        let mut buf = String::new();
