        let words: Vec<i64> = buf.split_whitespace().map(|w| w.parse().unwrap()).collect();
        (words[0], words[1], words[2], words[3])
    };
    let p: i64 = 1_000_000_007;
    fn inverse(x: i64, p: i64) -> i64 {
        if x == 1 {
            1
        } else {
            let q = p / x;
            let y = p % x;
            q * (p - inverse(y, p)) % p
        }
    }
    fn binom(m: i64, n: i64, p: i64) -> i64 {
        let (m, n) = if m < n { (m, n) } else { (n, m) };
        let mut c = 1;
        for i in 0..m {
            c = c * (n + m - i) % p;
            c = c * inverse(m - i, p) % p;
        }
        c
    }
    let mut ans = binom(r2 + 1, c2 + 1, p);
    ans = (ans - binom(r2 + 1, c1, p) + p) % p;
    ans = (ans - binom(r1, c2 + 1, p) + p) % p;
    ans = (ans + binom(r1, c1, p)) % p;
    println!("{}", ans);
}

