pub struct Combination {
    fact: Vec<ModInt>,
    ifact: Vec<ModInt>,
}
impl Combination {
    pub fn new(n: i32) -> Self {
        if n > 3000000 {
            panic!("error");
        }
        let mut fact = vec![ModInt::new(0); (n + 1) as usize];
        let mut ifact = vec![ModInt::new(0); (n + 1) as usize];
        fact[0] = ModInt::new(1);
        for i in 1..n + 1 {
            fact[i as usize] = fact[(i - 1) as usize] * ModInt::new(i as i64)
        }
        ifact[n as usize] = fact[n as usize].inv();
        for i in (1..n + 1).rev() {
            ifact[(i - 1) as usize] = ifact[i as usize] * ModInt::new(i as i64)
        }
        let a = Combination {
            fact: fact,
            ifact: ifact,
        };
        return a;
    }
    #[macro_use]
    pub fn gen(&mut self, n: i32, k: i32) -> ModInt {
        if (k < 0 || k > n) {
            return ModInt::new(0 as i64);
        };
        return self.fact[n as usize] * self.ifact[k as usize] * self.ifact[(n - k) as usize];
    }
    pub fn P(&mut self, n: i32, k: i32) -> ModInt {
        self.fact[n as usize] * self.ifact[(n - k) as usize]
    }
}

fn main() {
    input! {
       mut r1:i32,
       mut c1:i32,
       mut r2:i32,
       mut c2:i32,
    }
    let mut cmb = Combination::new(1e6 as i32);
    let mut a = cmb.gen(r2 + c2 + 2, r2 + 1) - ModInt::new(1);
    let mut b = cmb.gen(r2 + c1 + 2 - 1, r2 + 1) - ModInt::new(1);
    let mut c = cmb.gen(r1 + c2 + 2 - 1, c2 + 1) - ModInt::new(1);
    let mut d = cmb.gen(r1 + c1 + 2 - 2, r1) - ModInt::new(1);

    let ans = a + d - c - b;
    echo!(ans.to_string());
}

