fn count(r: usize, c: usize, facts: &[Modulo]) -> Modulo {
    let mut coef = Modulo(1);
    let mut summed = vec![Modulo(0); r + c];
    for i in 1..r + c {
        summed[i] = summed[i - 1] + coef;
        coef *= 2;
    }
    let mut ret = summed[r + c - 1] - summed[r - 1] - summed[c - 1];
    for ri in 1..r {
        let coef = comb(ri + c - 1, ri, facts);
        ret -= coef * summed[r - ri - 1];
    }
    for ci in 1..c {
        let coef = comb(ci + r - 1, ci, facts);
        ret -= coef * summed[c - ci - 1];
    }
    ret
}

