    for i in 2..r2 + c2 + 1 {
        facts[i] = facts[i - 1] * i as i64;
    }
    let ans = count(r2, c2, &facts) - count(r2, c1 - 1, &facts) - count(r1 - 1, c2, &facts)
        + count(r1 - 1, c1 - 1, &facts);
