fn sub(r: u64, c: u64, pc: &mut PowCache, cc: &mut CombinatoricsCache) -> ModP {
    let mut s = modp(0);
    let mut res = modp(0);
    for i in r+1..r+c+1 {
        let m = cc.choose(i, r+1);
        res += (m-s) * (pc.get(r+c-i+1) - 1);
        s = m;
    }
    res
}

fn solve(r: u64, c: u64, pc: &mut PowCache, cc: &mut CombinatoricsCache) -> ModP {
    pc.get(r+c+1)-1 - sub(r, c, pc, cc) - sub(c, r, pc, cc)
}

fn main() {
    unsafe { ModP::set_mod(1_000_000_007).unwrap(); }
    let mut pc = ModP::pow_cache(2);
    let mut cc = ModP::combinatorics_cache();
    read!(r1 = u64, c1 = u64, r2 = u64, c2 = u64);
    dbg!(solve(3, 4, &mut pc, &mut cc));
    println!("{}", solve(r2, c2, &mut pc, &mut cc)
             - solve(r1-1, c2, &mut pc, &mut cc)
             - solve(r2, c1-1, &mut pc, &mut cc)
             + solve(r1-1, c1-1, &mut pc, &mut cc));
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
