#[derive(Clone, Debug)]
struct ModCombinationCache {
    fac: u64,
    finv: u64,
    inv: u64,
}

#[derive(Debug)]
struct ModCombinator {
    prime: u64,
    factorial: Vec<ModCombinationCache>,
}

impl ModCombinator {
    pub fn with_capacity(capacity: usize, prime: u64) -> ModCombinator {
        let mut factorial = Vec::with_capacity(capacity);
        factorial.push(ModCombinationCache {
            fac: 1,
            finv: 1,
            inv: 0,
        });
        factorial.push(ModCombinationCache {
            fac: 1,
            finv: 1,
            inv: 1,
        });

        ModCombinator {
            prime: prime,
            factorial: factorial,
        }
    }

    pub fn run(&mut self, n: u64, r: u64) -> u64 {
        if n < r {
            return 0;
        }

        if r == 0 || n == r {
            return 1;
        }

        // update cache
        self.factorial.reserve((n + 1) as usize);

        // update factorial
        let mut last_fac: ModCombinationCache = self.factorial.last().unwrap().clone();

        for i in self.factorial.len() as u64..n + 1 {
            let inv = self.prime
                - self.factorial[(self.prime % i) as usize].inv * (self.prime / i) % self.prime;
            let new_fac = ModCombinationCache {
                fac: last_fac.fac * i % self.prime,
                inv: inv,
                finv: last_fac.finv * inv % self.prime,
            };
            self.factorial.push(new_fac.clone());
            last_fac = new_fac;
        }

        unsafe {
            let n_fac = self.factorial.get_unchecked(n as usize).fac;
            let r_fac = self.factorial.get_unchecked(r as usize).finv;
            let npr_fac = self.factorial.get_unchecked((n - r) as usize).finv;

            n_fac * (r_fac * npr_fac % self.prime) % self.prime
        }
    }
}

fn run() {
    input! {
        r1: u64,
        c1: u64,
        r2: u64,
        c2: u64,
    }

    let mut combinator = ModCombinator::with_capacity(2000005, 1000000007);
    let mut g = |r: u64, c: u64| -> u64 {
        combinator.run(r + c + 2, c + 1)
    };

    let mut result = 0u64;
    result += g(r2, c2);
    result += g(r1 - 1, c1 - 1);
    result -= g(r1 - 1, c2);
    result -= g(r2, c1 - 1);

    pprintln!(result % 1000000007);
}

atcoder_main!(run);

