fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let it = s.trim().split_whitespace();
    let a: Vec<usize> = it.map(|s| s.parse().unwrap()).collect();
    let (a, c, b, d) = (a[0], a[1], a[2], a[3]);
    let (a, b, c, d) = if b - a <= d - c {
        (a, b, c, d)
    } else {
        (c, d, a, b)
    };
    let pc = Precalc::new(2_000_000);
    let mut sum = pc.comb(a + c, a);
    let mut ans = sum;
    for i in (a + 1)..(b + 1) {
        sum = ModInt(2) * sum + pc.comb(i + c - 1, c - 1) + pc.comb(a - 1 + (c + i - a), a - 1);
        ans += sum;
    }
    for i in (c + 1)..(d - (b - a) + 1) {
        sum = ModInt(2) * sum - pc.comb(b + i - 1, b) + pc.comb(a - 1 + (i + b - a), a - 1);
        ans += sum;
    }
    for i in 1..(b - a + 1) {
        sum = ModInt(2) * sum - pc.comb(a + i - 1 + d, d) - pc.comb(b + d - (b - a) + i - 1, b);
        ans += sum;
    }
    println!("{}", ans);
}

