type Number = i64;

const M : Number = 1_000_000_007;

fn main()
{
    let mut line = String::new();
    std::io::stdin().read_line(&mut line).unwrap();

    let data: Vec<&str> = line.split_whitespace().collect();
    let r1: Number = data[0].parse().unwrap_or(0);
    let c1: Number = data[1].parse().unwrap_or(0);
    let r2: Number = data[2].parse().unwrap_or(0);
    let c2: Number = data[3].parse().unwrap_or(0);

    let n = (r2 + c2 + 2) as usize;

    let mut facts : Vec<Number> = vec![1; n];
    let mut finvs : Vec<Number> = vec![1; n];
    let mut invs  : Vec<Number> = vec![1; n];

    invs[0] = 0;

    for i in 2..n
    {
        facts[i] = ((i as Number) * facts[i - 1]) % M;
        invs[i]  = M - (invs[(M as usize) % i] * (M / (i as Number))) % M;
        finvs[i] = (finvs[i - 1] * invs[i]) % M;
    }

    let ncr = |n: Number, r: Number| -> Number
    {
        (facts[n as usize] * ((finvs[r  as usize] * finvs[(n as usize) - (r as usize)]) % M)) % M
    };

    let sum = |x: Number, y: Number| -> Number
    {
        (1 .. (x + 2)).fold(0, |val, index| (val + ncr(y + index, index)) % M)
    };

    let a = sum(r2, c2);
    let b = sum(r1 - 1, c2);
    let c = sum(r2, c1 - 1);
    let d = sum(r1 - 1, c1 - 1);

    let ans = (a + d - b - c) % M;
    println!("{}", ans);
}

