fn count(r: usize, c: usize, facts: &[Modulo], facts_inv: &[Modulo], summed: &[Modulo]) -> Modulo {
    let mut ret = summed[r + c - 1] - summed[r - 1] - summed[c - 1];
    for ri in 1..r {
        let coef = comb(ri + c - 1, ri, facts, facts_inv);
        ret -= coef * summed[r - ri - 1];
    }
    for ci in 1..c {
        let coef = comb(ci + r - 1, ci, facts, facts_inv);
        ret -= coef * summed[c - ci - 1];
    }
    ret
}

fn main() {
    let v = read_vec::<usize>();
    let (r1, c1, r2, c2) = (v[0] + 1, v[1] + 1, v[2] + 1, v[3] + 1);
    let mut facts = vec![Modulo(1); r2 + c2 + 1];
    for i in 2..r2 + c2 + 1 {
        facts[i] = facts[i - 1] * i as i64;
    }
    let mut facts_inv = vec![Modulo(1); r2 + c2 + 1];
    for i in 0..r2 + c2 + 1 {
        facts_inv[i] = facts[i].inv();
    }
    let mut coef = Modulo(1);
    let mut summed = vec![Modulo(0); r2 + c2];
    for i in 1..r2 + c2 {
        summed[i] = summed[i - 1] + coef;
        coef *= 2;
    }
    let ans = count(r2, c2, &facts, &facts_inv, &summed)
        - count(r2, c1 - 1, &facts, &facts_inv, &summed)
        - count(r1 - 1, c2, &facts, &facts_inv, &summed)
        + count(r1 - 1, c1 - 1, &facts, &facts_inv, &summed);
    println!("{}", ans);
}

