struct Combination {
    fact: Vec<i64>,
    invfact: Vec<i64>,
}

impl Combination {
    fn inv(a: i64) -> i64 {
        Combination::pow(a, MOD - 2)
    }

    fn pow(a: i64, p: i64) -> i64 {
        let mut p = p;
        let mut aa = a;
        let mut ret = 1;
        while p >= 1 {
            if p & 1 == 1 {
                ret *= aa;
                ret %= MOD;
            }
            p >>= 1;
            aa = aa * aa % MOD;
        }
        ret
    }

    fn new(upto: usize) -> Self {
        let mut fact = vec![0; upto];
        let mut invfact = vec![0; upto];

        fact[0] = 1;
        for i in 1..upto {
            fact[i] = fact[i - 1] * (i as i64) % MOD;
        }

        invfact[upto - 1] = Combination::inv(fact[upto - 1]);
        invfact[0] = 1;
        for i in (1..upto - 1).rev() {
            invfact[i] = invfact[i + 1] * ((i + 1) as i64) % MOD;
        }

        Combination {
            fact: fact,
            invfact: invfact,
        }
    }

    fn comb(&self, n: usize, r: usize) -> i64 {
        if r < 0 || r > n {
            return 0;
        }
        self.fact[n] * self.invfact[r] % MOD * self.invfact[n - r] % MOD
    }
}


// ===

const MOD: i64 = 1e9 as i64 + 7;


fn main() {
    input! {
        r1: usize, c1: usize,
        r2: usize, c2: usize
    };

    let mut comb = Combination::new(2000100);

    // C(a,0) + C(a+1,1) + ... + C(a+k,k) = C(a+k+1,k+1)
    // C(a,b) + C(a+1,b) + ... + C(a+k,b) = C(a+k+1,b+1)
    let solve = |x: usize, y: usize| {
        comb.comb(x+y+2, x+1)
    };
    let ans = MOD + MOD + solve(r2, c2) - solve(r1-1, c2) - solve(r2, c1-1) + solve(r1-1, c1-1);
    println!("{}", ans % MOD);
}

