type BoxResult<T> = Result<T, Box<std::error::Error>>;

const MOD: u64 = 1_000_000_000 + 7;

fn main() {
    let mut scanner = Scanner::new(stdin());
    let line = scanner.read_vector::<u64>().unwrap();
    let (r1, c1, r2, c2) = (line[0], line[1], line[2], line[3]);
    let mut a = combination(c1 + 1 + r2, r2, MOD);
    let mut b = combination(c1 + r1, r1 - 1, MOD);
    let mut ans = (a + MOD - b) % MOD;
    for i in (c1 + 1)..(c2 + 1) {
        let inv = power(i + 1, MOD - 2, MOD);
        a = (a * (i + 1 + r2)) % MOD;
        a = (a * inv) % MOD;
        if r1 > 1 {
            b = (b * (i + r1)) % MOD;
            b = (b * inv) % MOD;
        }
        ans += (a + MOD - b) % MOD;
        ans %= MOD;
    }
    println!("{}", ans);
}

fn combination(n: u64, k: u64, modulo: u64) -> u64 {
    if k == 0 || k == n {
        return 1;
    }
    if n < k {
        return 0;
    }
    let nk_fact = ((n - k + 1)..(n + 1)).fold(1, |acc, i| (acc * i) % modulo);
    let k_fact = (2..(k + 1)).fold(1, |acc, i| (acc * i) % modulo);
    let k_fact_inv = power(k_fact, modulo - 2, modulo);
    (nk_fact * k_fact_inv) % modulo
}

fn power(x: u64, mut k: u64, modulo: u64) -> u64 {
    let mut pows = vec![x];
    for i in 0..63 {
        let square = (pows[i] * pows[i]) % modulo;
        pows.push(square);
    }
    let mut pow = 1;
    for i in 0..64 {
        let flag = k & 1;
        k >>= 1;
        if flag == 1 {
            pow = (pow * pows[i]) % modulo;
        }
    }
    pow
}

