#[derive(Clone, Debug)]
struct MemorizedFactorial {
    n: usize,
    fact: Vec<Modi64>,
    inv_fact: Vec<Modi64>,
}
impl MemorizedFactorial {
    fn new(max_n: usize) -> MemorizedFactorial {
        let mut fact = vec![1.into(); max_n + 1];
        let mut inv_fact = vec![1.into(); max_n + 1];
        for i in 1..=max_n {
            fact[i] = fact[i - 1] * (i as i64).into();
            inv_fact[i] = inv_fact[i - 1] / (i as i64).into();
        }
        MemorizedFactorial {
            n: max_n + 1,
            fact: fact,
            inv_fact: inv_fact,
        }
    }
    fn combination(&self, n: usize, r: usize) -> Modi64 {
        if r <= n {
            self.fact[n] * self.inv_fact[r] * self.inv_fact[n - r]
        } else {
            0.into()
        }
    }
    fn f(&self, r: usize, c: usize) -> Modi64 {
        let mx = max(r, c);
        let mn = min(r, c);
        let mut res = Modi64(0);
        for i in 0..(mn + 1) {
            res += self.combination(mx + i + 1, i + 1);
        }
        res
    }
}
fn main() {
    input! { r1,c1,r2,c2 };
    let cmb = MemorizedFactorial::new(r2 + c2 + 5);
    let mut ans = Modi64(0);
    ans += cmb.f(r2, c2);
    ans -= cmb.f(r2, c1 - 1);
    ans -= cmb.f(r1 - 1, c2);
    ans += cmb.f(r1 - 1, c1 - 1);
    println!("{}", ans.0);
}
